repeat task.wait() until game:IsLoaded()

pcall(function()
    if (identifyexecutor() == "AWP" or identifyexecutor() == "Nihon") then
        cleardrawcache()
    end
end)

isnetworkowner = (function()
    if type(isnetworkowner) == "function" then return isnetworkowner end
    for _, name in ipairs({"isnetworkowneroff","isNetOwner","is_network_owner","checknetworkowner","getnetworkowner","isOwner"}) do
        local fn = _G and _G[name]
        if type(fn) == "function" then return fn end
    end
    if type(getnetworkowner) == "function" then
        return function(part)
            local ok, owner = pcall(getnetworkowner, part)
            if not ok then return true end
            return owner == game:GetService("Players").LocalPlayer
        end
    end
    return function(part)
        if not part or typeof(part) ~= "Instance" then return true end
        local ok, owner = pcall(function() return part:GetNetworkOwner() end)
        if not ok then return true end
        return owner == game:GetService("Players").LocalPlayer
    end
end)()

pcall(function() workspace.FallenPartsDestroyHeight = -0 / 0 end)

if not cloneref then cloneref = function(x) return x end end

Players = cloneref(game:GetService("Players"))
HttpService = cloneref(game:GetService("HttpService"))
UserInputService = cloneref(game:GetService("UserInputService"))
LocalPlayer = Players.LocalPlayer
Workspace = cloneref(game:GetService("Workspace"))
Lighting = cloneref(game:GetService("Lighting"))
MaterialService = cloneref(game:GetService("MaterialService"))
RunService = cloneref(game:GetService("RunService"))
GuiService = cloneref(game:GetService("GuiService"))
TextChatService = cloneref(game:GetService("TextChatService"))
TweenService = cloneref(game:GetService("TweenService"))
Stats = cloneref(game:GetService("Stats"))
Debris = cloneref(game:GetService("Debris"))
Backpack = LocalPlayer and (LocalPlayer:FindFirstChildOfClass("Backpack") or cloneref(Players:FindFirstChild("Backpack"))) or nil

if not LocalPlayer then
    warn("[Loadstring] no LocalPlayer, abort")
    return
end

_FRPlayers = cloneref and cloneref(game:GetService("Players")) or game:GetService("Players")
_FRPlayer = _FRPlayers.LocalPlayer
_ForceRestEnabled = false
_ForceRestHeartbeat = nil

function forceReset()
    local character = _FRPlayer.Character
    if character then
        local humanoid = character:FindFirstChild("Humanoid")
        if humanoid then humanoid.Health = 0 end
        character:BreakJoints()
    end
end

function checkHealth()
    if not _ForceRestEnabled then return end
    local character = _FRPlayer.Character
    if not character then return end
    local humanoid = character:FindFirstChild("Humanoid")
    if humanoid and humanoid.Health <= 10 then forceReset() end
end

if _FRPlayer then
    _FRPlayer.CharacterAdded:Connect(function()
        if _ForceRestEnabled then
            task.wait(0.5)
            checkHealth()
        end
    end)
end

if _ForceRestHeartbeat then
    _ForceRestHeartbeat:Disconnect()
    _ForceRestHeartbeat = nil
end
_ForceRestHeartbeat = game:GetService("RunService").Heartbeat:Connect(checkHealth)

