function _safeLoad(url)
    local separator = url:find("?") and "&" or "?"
    local freshUrl = url .. separator .. "t=" .. os.time()
    
    local fn, loadErr = loadstring(game:HttpGet(freshUrl))
    if not fn then
        warn("[loader] Failed to compile: " .. tostring(loadErr))
        return nil
    end
    
    local ok, res = pcall(fn)
    if ok then return res end
    
    warn("[loader] Failed to execute: " .. tostring(res))
    return nil
end

