-- loader
do
    local CACHE_BUST = tostring(os.time())

    function fetch(url, bust)
        local full = bust and (url .. (url:find("?", 1, true) and "&" or "?") .. "t=" .. CACHE_BUST) or url
        local req = request or http_request or (syn and syn.request)
        if req then
            local ok, r = pcall(req, { Url = full, Method = "GET" })
            if ok and type(r) == "table" and tonumber(r.StatusCode) == 200
                and type(r.Body) == "string" and #r.Body > 0 then
                return r.Body
            end
        end
        local ok, b = pcall(game.HttpGet, game, full)
        if ok and type(b) == "string" and #b > 0 then return b end
        return nil
    end

    SPEEDKIT_URL = "https://raw.githubusercontent.com/madeformeanduu/UR4/refs/heads/main/Rendering/SpeedKit.luau"
    DECODER_URL  = "https://raw.githubusercontent.com/madeformeanduu/UR4/refs/heads/main/Rendering/GifDecoder.luau"
    RENDERER_URL = "https://raw.githubusercontent.com/madeformeanduu/UR4/refs/heads/main/Rendering/GifRenderer.luau"

    local env = getgenv and getgenv() or _G
    if type(env.SpeedKit) ~= "table" or type(env.SpeedKit.Blend) ~= "function" then
        local kitSrc = fetch(SPEEDKIT_URL, true) or fetch(SPEEDKIT_URL, false)
        if kitSrc then
            local ok, kit = pcall(function()
                local mod = loadstring(kitSrc)()
                if type(mod) == "table" and type(mod.Blend) == "function" then
                    return mod
                end
                return nil
            end)
            if ok and kit then
                env.SpeedKit = kit
            else
                warn("[ERROR] SK load failed")
            end
        else
            warn("[ERROR] SK fetch failed")
        end
    end

    local decoderSrc = fetch(DECODER_URL, true) or fetch(DECODER_URL, false)
    if decoderSrc then
        local ok, decoded = pcall(function()
            local mod = loadstring(decoderSrc)()
            if type(mod) == "table" and type(mod.decode) == "function" then
                return mod
            end
            return nil
        end)
        if ok and decoded then
            env.GifDecoder = decoded

            local rendererSrc = fetch(RENDERER_URL, true) or fetch(RENDERER_URL, false)
            if rendererSrc then
                local ok2, renderer = pcall(function()
                    local mod = loadstring(rendererSrc)()
                    if type(mod) == "table" and type(mod.new) == "function" then
                        return mod
                    end
                    return nil
                end)
                if ok2 and renderer then
                    renderer.RequiredDecoderVersion = decoded.Version
                    env.GifRenderer = renderer
                else
                    warn("[ERROR] renderer load failed")
                end
            else
                warn("[ERROR] renderer fetch failed")
            end
        else
            warn("[ERROR] decoder load failed")
        end
    else
        warn("[ERROR] decoder fetch failed")
    end
end

