SkyboxNames = {}
for name in pairs(Skyboxes) do table.insert(SkyboxNames, name) end
table.sort(SkyboxNames)
table.insert(SkyboxNames, 1, 'None')

SkySection:AddDropdown('Skybox', {
    Values = SkyboxNames,
    Default = 'None',
    Text = 'Skybox',
})

SkySection:AddSlider('SkyboxSpin', {
    Text = 'Skybox Spin (deg/s)',
    Default = 0,
    Min = 0,
    Max = 360,
    Rounding = 1,
    Compact = false,
})

OriginalSky = nil
_activeCustomSky = nil

_G._skySpinAngle = 0
_G._skySpinSpeed = 0

function applySkybox(skyName)
    if OriginalSky == nil then
        for _, obj in ipairs(Lighting:GetChildren()) do
            if obj:IsA("Sky") then OriginalSky = obj break end
        end
        if OriginalSky == nil then OriginalSky = false end
    end

    if _activeCustomSky and _activeCustomSky.Parent then _activeCustomSky:Destroy() end
    _activeCustomSky = nil

    if skyName == 'None' or not Skyboxes[skyName] then
        if OriginalSky and OriginalSky.Parent == nil then OriginalSky.Parent = Lighting end
        return
    end

    if OriginalSky and OriginalSky.Parent then OriginalSky.Parent = nil end

    local data = Skyboxes[skyName]
    local sky = Instance.new("Sky")
    sky.Name = "CustomSkyboxzz"
    sky.SkyboxBk = data.SkyboxBk
    sky.SkyboxDn = data.SkyboxDn
    sky.SkyboxFt = data.SkyboxFt
    sky.SkyboxLf = data.SkyboxLf
    sky.SkyboxRt = data.SkyboxRt
    sky.SkyboxUp = data.SkyboxUp
    if data.StarCount ~= nil then sky.StarCount = data.StarCount end
    if data.SunAngularSize ~= nil then sky.SunAngularSize = data.SunAngularSize end
    if data.MoonAngularSize ~= nil then sky.MoonAngularSize = data.MoonAngularSize end
    if data.SunTextureId ~= nil then sky.SunTextureId = data.SunTextureId end
    if data.MoonTextureId ~= nil then sky.MoonTextureId = data.MoonTextureId end

    _G._skySpinAngle = 0
    sky.SkyboxOrientation = Vector3.new(0, 0, 0)

    sky.Parent = Lighting
    _activeCustomSky = sky
end

Options.Skybox:OnChanged(function()
    applySkybox(Options.Skybox.Value)
end)

Options.SkyboxSpin:OnChanged(function()
    _G._skySpinSpeed = Options.SkyboxSpin.Value or 0
end)

_G._SKY_SPIN_RUNNING = true
task.spawn(function()
    while _G._SKY_SPIN_RUNNING and task.wait(0.03) do
        if _activeCustomSky and _activeCustomSky.Parent and _G._skySpinSpeed > 0 then
            _G._skySpinAngle = (_G._skySpinAngle + _G._skySpinSpeed * 0.03) % 360
            pcall(function()
                _activeCustomSky.SkyboxOrientation = Vector3.new(0, _G._skySpinAngle, 0)
            end)
        end
    end
end)

task.spawn(function()
    task.wait(1)
    if Options.Skybox.Value ~= "None" then
        applySkybox(Options.Skybox.Value)
    end
end)

task.spawn(function()
    while _G._SKY_SPIN_RUNNING and task.wait(1) do
        if _activeCustomSky and not _activeCustomSky.Parent then
            _activeCustomSky.Parent = Lighting
        end
    end
end)

_G._SkyChildAddedConn = Lighting.ChildAdded:Connect(function(child)
    if child:IsA("Sky") and child ~= _activeCustomSky and _activeCustomSky then
        task.defer(function()
            if child.Parent then child.Parent = nil end
        end)
    end
end)

AuraSection = WorldTab:AddLeftGroupbox('Auras')

_G.aurp = _G.aurp or {}

_getobj = getobjects or (game and game.GetObjects and function(id) return game:GetObjects(id) end)
_G.aurasst = _G.aurasst or {}
_G.aurasst_loaded = _G.aurasst_loaded or false

_G.aur_asset_ids = {
    starlight = "134645216613107", heavenly = "139300897520961", ribbon = "132069507632161",
    sakura = "81755778619404", angel = "97658130917593", wind = "80694081850877",
    flow = "119913533725648", star = "73754563740680", explo = "75789713107155",
    waves = "94581063446738", pixel = "90816193741219", soundwaves = "114870034653215",
    king = "93563147247398", balloflight = "111538260393666", robes = "89189106998138",
    cinco = "108479261729538", hallownest = "13157241929", special = "126521784338665",
    Cardhandler = "10373359918", Tridents = "9098706617", Aether = "9021585133",
    Riverofstars = "9256108828", Trials = "8746150090",
    wingsofangels = "100676015469934", avatar = "8261337603", enchantment = "9952334427",
	gravity = "10446434302", 
}

function _G.aur_ensure_assets()
    if _G.aurasst_loaded or not _getobj then return end
    _G.aurasst_loaded = true
    for name, id in pairs(_G.aur_asset_ids) do
        local ok, objs = pcall(_getobj, "rbxassetid://" .. id)
        if ok and objs and objs[1] then _G.aurasst[name] = objs[1] end
    end
end

_G.aur_r6_to_r15 = {
    Head = "Head", Torso = "UpperTorso",
    ["Left Arm"] = "LeftUpperArm", ["Right Arm"] = "RightUpperArm",
    ["Left Leg"] = "LeftUpperLeg", ["Right Leg"] = "RightUpperLeg",
}

local AUR_BODY_PARTS = {}
for _, name in ipairs({
    "head", "torso", "uppertorso", "lowertorso", "body", "humanoidrootpart",
    "root", "hrp", "aura", "effect", "effects", "main", "core", "bodyeffect",
    "bodyeffects", "part", "meshpart", "unionoperation", "model", "sphere",
    "ball", "orb", "vfx", "portal", "portal particles", "gravity",
    "left arm", "right arm", "leftarm", "rightarm",
    "left leg", "right leg", "leftleg", "rightleg",
    "leftupperarm", "leftlowerarm", "lefthand", "rightupperarm", "rightlowerarm",
    "righthand", "leftupperleg", "leftlowerleg", "leftfoot", "rightupperleg",
    "rightlowerleg", "rightfoot",
}) do
    AUR_BODY_PARTS[name] = true
end

local AUR_TARGET_MAP = {
    ["aura"] = "hrp", ["effect"] = "hrp", ["effects"] = "hrp",
    ["main"] = "hrp", ["core"] = "hrp", ["bodyeffect"] = "hrp",
    ["bodyeffects"] = "hrp",
    ["part"] = "hrp", ["meshpart"] = "hrp", ["unionoperation"] = "hrp",
    ["model"] = "hrp", ["sphere"] = "hrp", ["ball"] = "hrp",
    ["orb"] = "hrp", ["vfx"] = "hrp",
    ["portal"] = "hrp", ["portal particles"] = "hrp", ["gravity"] = "hrp",
    ["head"] = "head",
    ["torso"] = "torso", ["uppertorso"] = "torso", ["lowertorso"] = "torso",
    ["body"] = "torso",
    ["humanoidrootpart"] = "hrp", ["root"] = "hrp", ["hrp"] = "hrp",
    ["left arm"] = "larm", ["leftarm"] = "larm", ["leftupperarm"] = "larm",
    ["leftlowerarm"] = "larm", ["lefthand"] = "larm",
    ["right arm"] = "rarm", ["rightarm"] = "rarm", ["rightupperarm"] = "rarm",
    ["rightlowerarm"] = "rarm", ["righthand"] = "rarm",
    ["left leg"] = "lleg", ["leftleg"] = "lleg", ["leftupperleg"] = "lleg",
    ["leftlowerleg"] = "lleg", ["leftfoot"] = "lleg",
    ["right leg"] = "rleg", ["rightleg"] = "rleg", ["rightupperleg"] = "rleg",
    ["rightlowerleg"] = "rleg", ["rightfoot"] = "rleg",
}

_G.aur_is_body_part = function(name)
    if not name then return false end
    return AUR_BODY_PARTS[name:lower()] == true
end

_G.aur_find_target = function(char, name)
    if not char or not name then return nil end
    local key = AUR_TARGET_MAP[name:lower()]
    if not key then
        local direct = char:FindFirstChild(name)
        if direct then return direct end
        local mapped = _G.aur_r6_to_r15[name]
        if mapped then return char:FindFirstChild(mapped) end
        return nil
    end
    if key == "hrp" then
        return char:FindFirstChild("HumanoidRootPart")
            or char:FindFirstChild("UpperTorso")
            or char:FindFirstChild("Torso")
    elseif key == "head" then return char:FindFirstChild("Head")
    elseif key == "torso" then
        return char:FindFirstChild("UpperTorso")
            or char:FindFirstChild("LowerTorso")
            or char:FindFirstChild("Torso")
    elseif key == "larm" then
        return char:FindFirstChild("LeftUpperArm")
            or char:FindFirstChild("LeftLowerArm")
            or char:FindFirstChild("LeftHand")
            or char:FindFirstChild("Left Arm")
    elseif key == "rarm" then
        return char:FindFirstChild("RightUpperArm")
            or char:FindFirstChild("RightLowerArm")
            or char:FindFirstChild("RightHand")
            or char:FindFirstChild("Right Arm")
    elseif key == "lleg" then
        return char:FindFirstChild("LeftUpperLeg")
            or char:FindFirstChild("LeftLowerLeg")
            or char:FindFirstChild("LeftFoot")
            or char:FindFirstChild("Left Leg")
    elseif key == "rleg" then
        return char:FindFirstChild("RightUpperLeg")
            or char:FindFirstChild("RightLowerLeg")
            or char:FindFirstChild("RightFoot")
            or char:FindFirstChild("Right Leg")
    end
    return nil
end

_G.aur_is_effect = function(inst)
    return inst:IsA("ParticleEmitter") or inst:IsA("Trail") or inst:IsA("Beam")
        or inst:IsA("PointLight") or inst:IsA("SpotLight") or inst:IsA("Sparkles")
        or inst:IsA("Fire") or inst:IsA("Smoke") or inst:IsA("Attachment")
end

_G.aur_colorables = _G.aur_colorables or {}

function _G.aur_collect_colorables(inst, out)
    if not inst then return end
    local c = inst.ClassName
    if c == "ParticleEmitter" or c == "Trail" or c == "Beam" then
        out[#out + 1] = { inst = inst, kind = "seq" }
    elseif c == "PointLight" or c == "SpotLight" then
        out[#out + 1] = { inst = inst, kind = "color" }
    end
    for _, child in ipairs(inst:GetChildren()) do
        _G.aur_collect_colorables(child, out)
    end
end

_G.updaurcol = function()
    local col = _G.aurcolwtff or Color3.fromRGB(255, 255, 255)
    local seq = ColorSequence.new(col)
    local list = _G.aur_colorables
    for i = 1, #list do
        local e = list[i]
        local inst = e.inst
        if inst.Parent then
            if e.kind == "seq" then inst.Color = seq
            else inst.Color = col end
        end
    end
end

_G.clraur = function()
    for i = 1, #_G.aurp do
        local v = _G.aurp[i]
        if v then v:Destroy() end
    end
    table.clear(_G.aurp)
    table.clear(_G.aur_colorables)
end

_G.aur_apply_children = function(src, char)
    if not src or not src.Parent then return end
    local target = _G.aur_find_target(char, src.Name)
    if not target then
        local node = src.Parent
        local depth = 0
        while node and depth < 4 do
            if _G.aur_is_body_part(node.Name) then
                target = _G.aur_find_target(char, node.Name)
                if target then break end
            end
            node = node.Parent
            depth = depth + 1
        end
    end
    if not target then return end
    local kids = src:GetChildren()
    for i = 1, #kids do
        local c = kids[i]
        if c:IsA("Motor6D") or c:IsA("Weld") or c:IsA("WeldConstraint")
            or c:IsA("Humanoid") or c:IsA("SpecialMesh") or c:IsA("Mesh")
            or c:IsA("Camera") or c:IsA("Script") or c:IsA("ModuleScript") or c:IsA("LocalScript")
            or c:IsA("BillboardGui") then
            c:Destroy()
        else
            c.Name = "\0"
            c.Parent = target
            table.insert(_G.aurp, c)
        end
    end
end

_G.applaur = function()
    _G.clraur()
    if not _G.aurenabwtff then return end
    local char = LocalPlayer.Character
    if not char then return end

    _G.aur_ensure_assets()

    local asset = _G.aurasst[_G.selaurwtff or "angel"]
    if not asset then return end
    local clo = asset:Clone()

    for _, d in ipairs(clo:GetDescendants()) do
        if d:IsA("Script") or d:IsA("LocalScript") then
            d:Destroy()
        end
    end

    local tops = clo:GetChildren()
    for i = 1, #tops do
        local node = tops[i]
        if node and node.Parent then
            if _G.aur_is_body_part(node.Name) then
                _G.aur_apply_children(node, char)
                node:Destroy()
            else
                local targ = _G.aur_find_target(char, node.Name)
                if targ then
                    local effs = node:GetChildren()
                    for j = 1, #effs do
                        local eff = effs[j]
                        eff.Name = "\0"
                        eff.Parent = targ
                        table.insert(_G.aurp, eff)
                    end
                    node:Destroy()
                end
            end
        end
    end

    local leftover = clo:GetDescendants()
    for i = 1, #leftover do
        local eff = leftover[i]
        if eff and eff.Parent and _G.aur_is_effect(eff) then
            local target = nil
            local walk = eff.Parent
            local depth = 0
            while walk and depth < 4 do
                if _G.aur_is_body_part(walk.Name) then
                    target = _G.aur_find_target(char, walk.Name)
                    if target then break end
                end
                walk = walk.Parent
                depth = depth + 1
            end
            if target then
                eff.Name = "\0"
                eff.Parent = target
                table.insert(_G.aurp, eff)
            end
        end
    end

    local hrp = char:FindFirstChild("HumanoidRootPart")

    local function isWelded(part)
        if part:FindFirstChildWhichIsA("Weld") or part:FindFirstChildWhichIsA("WeldConstraint") then return true end
        local p = part.Parent
        if p then
            for _, sib in ipairs(p:GetChildren()) do
                if sib:IsA("Weld") or sib:IsA("WeldConstraint") then
                    if sib.Part0 == part or sib.Part1 == part then return true end
                end
            end
        end
        return false
    end

    local function findAnchor(inst)
        local walk = inst.Parent
        while walk and walk ~= char do
            if walk:IsA("BasePart") and walk.Parent == char then
                return walk
            end
            walk = walk.Parent
        end
        return hrp
    end

    local function weldStray(container)
        if not container or not container.Parent then return end
        if container:IsA("BasePart") and not isWelded(container) then
            local anchor = findAnchor(container) or hrp
            if anchor then
                container.Anchored = false
                container.CanCollide = false
                container.Massless = true
                local w = Instance.new("WeldConstraint")
                w.Part0 = anchor
                w.Part1 = container
                w.Parent = container
            end
        end
        for _, d in ipairs(container:GetDescendants()) do
            if d:IsA("BasePart") and not isWelded(d) then
                local anchor = findAnchor(d) or hrp
                if anchor then
                    d.Anchored = false
                    d.CanCollide = false
                    d.Massless = true
                    local w = Instance.new("WeldConstraint")
                    w.Part0 = anchor
                    w.Part1 = d
                    w.Parent = d
                end
            end
        end
    end

    if hrp then
        for i = 1, #_G.aurp do
            weldStray(_G.aurp[i])
        end
    end

    clo:Destroy()

    table.clear(_G.aur_colorables)
    for i = 1, #_G.aurp do
        _G.aur_collect_colorables(_G.aurp[i], _G.aur_colorables)
    end

    _G.updaurcol()
end

getgenv().createFF = function()
    local char = LocalPlayer.Character
    if char and not char:FindFirstChild("FakeFF") then
        local ff = Instance.new("ForceField")
        ff.Name = "FakeFF"
        ff.Visible = true
        ff.Parent = char
    end
end

getgenv().removeFF = function()
    local char = LocalPlayer.Character
    if char then
        local ff = char:FindFirstChild("FakeFF")
        if ff then ff:Destroy() end
    end
end

