_G.AimMethod = 'Silent Aim'
_G.AimSmoothness = 0.25
_G.AimTargetPart = 'Head'

function GetAimPart(player)
    if not player or not player.Character then return nil end
    local char = player.Character
    local name = _G.AimTargetPart or 'Head'

    local part
    if name == 'Torso' then
        part = char:FindFirstChild('UpperTorso')
            or char:FindFirstChild('LowerTorso')
            or char:FindFirstChild('Torso')
    elseif name == 'LeftArm' then
        part = char:FindFirstChild('LeftUpperArm')
            or char:FindFirstChild('LeftLowerArm')
            or char:FindFirstChild('LeftHand')
            or char:FindFirstChild('Left Arm')
    elseif name == 'RightArm' then
        part = char:FindFirstChild('RightUpperArm')
            or char:FindFirstChild('RightLowerArm')
            or char:FindFirstChild('RightHand')
            or char:FindFirstChild('Right Arm')
    elseif name == 'LeftFoot' then
        part = char:FindFirstChild('LeftFoot')
            or char:FindFirstChild('LeftLowerLeg')
            or char:FindFirstChild('LeftUpperLeg')
            or char:FindFirstChild('Left Leg')
    elseif name == 'RightFoot' then
        part = char:FindFirstChild('RightFoot')
            or char:FindFirstChild('RightLowerLeg')
            or char:FindFirstChild('RightUpperLeg')
            or char:FindFirstChild('Right Leg')
    else
        part = char:FindFirstChild(name)
    end

    return part
        or char:FindFirstChild('Head')
        or char:FindFirstChild('HumanoidRootPart')
end

