TMC = nil
TMCCharAdded = nil
TMCChildAdded = nil
TMM = Enum.Material.Neon

function TMApply(tool, restore)
    pcall(function()
        if not tool then return end
        local h = tool:FindFirstChild("Default")
        if not h then return end

        if not restore then
            h.Material = TMM
            h.Color = Options.ToolMatColor.Value
            h.Transparency = Options.ToolMatColor.Transparency

            if not tool:GetAttribute("TMTex") then
                tool:SetAttribute("TMTex", h.TextureID)
            end
            h.TextureID = ""
        else
            local tex = tool:GetAttribute("TMTex")
            if tex then
                h.TextureID = tex
                h.Transparency = 0
            end
            h.Material = Enum.Material.Plastic
            tool:SetAttribute("TMTex", nil)
        end
    end)
end

function TMRestoreAll()
    pcall(function()
        local c = _56.Character
        if not c then return end

        for _, v in ipairs(c:GetChildren()) do
            if v:IsA("Tool") then TMApply(v, true) end
        end

        local bp = _56.Backpack
        if bp then
            for _, v in ipairs(bp:GetChildren()) do
                if v:IsA("Tool") then TMApply(v, true) end
            end
        end
    end)
end

function TMCurrent()
    pcall(function()
        local c = _56.Character
        if not c then return end
        local t = c:FindFirstChildOfClass("Tool")
        if t then TMApply(t, false) end
    end)
end

local function TMBindCharacter(char)
    if TMCChildAdded then
        TMCChildAdded:Disconnect()
        TMCChildAdded = nil
    end
    if not char then return end
    TMCChildAdded = char.ChildAdded:Connect(function(child)
        if child:IsA("Tool") and Toggles.ToolMat.Value then
            TMApply(child, false)
        end
    end)
end

Toggles.ToolMat:OnChanged(function(value)
    if TMC then TMC:Disconnect() TMC = nil end
    if TMCChildAdded then TMCChildAdded:Disconnect() TMCChildAdded = nil end
    if TMCCharAdded then TMCCharAdded:Disconnect() TMCCharAdded = nil end
    TMRestoreAll()

    if value then
        TMCurrent()

        TMCCharAdded = _56.CharacterAdded:Connect(function(char)
            task.wait(0.5)
            if not Toggles.ToolMat.Value then return end
            TMCurrent()
            TMBindCharacter(char)
        end)

        TMBindCharacter(_56.Character)
    end
end)

Options.ToolMatType:OnChanged(function(value)
    TMM = value == "Neon" and Enum.Material.Neon or Enum.Material.ForceField
    if Toggles.ToolMat and Toggles.ToolMat.Value then
        TMCurrent()
    end
end)

Options.ToolMatColor:OnChanged(function()
    if Toggles.ToolMat and Toggles.ToolMat.Value then
        TMCurrent()
    end
end)

