-- Marin ESP
ImageESP_Objects = {}
ImageESP_Enabled = false
ImageESP_FilePath = "woodie/assets/images/kitagawa.webp"
ImageESP_Config = {
    Size = 3.7,
    HeightScale = 0.9,
    Offset = Vector3.new(0, 1, 0),
    MaxDistance = 500,
    AspectRatio = Vector2.new(1.5, 1),
}

ImageESP_Cached = nil
ImageESP_PlayerConns = {}
ImageESP_ConnectionAdded = nil
ImageESP_ConnectionRemoving = nil
ImageESP_ConnectionLocalAdded = nil
ImageESP_RenderConnection = nil

function ImageESP_LoadAsset(path)
    if ImageESP_Cached then return ImageESP_Cached end
    local success, result = pcall(function() return getcustomasset(path) end)
    if success and result then
        ImageESP_Cached = result
        return result
    end
    return nil
end

function ImageESP_Create(plr, img)
    if not plr.Character then return end
    if ImageESP_Objects[plr.UserId] then return end

    local torso = plr.Character:FindFirstChild("LowerTorso") or plr.Character:FindFirstChild("HumanoidRootPart")
    if not torso then return end

    local hum = plr.Character:FindFirstChild("Humanoid")
    local hipHeight = hum and hum.HipHeight or 2
    local size = ImageESP_Config.Size * hipHeight * ImageESP_Config.HeightScale
    local width = size * ImageESP_Config.AspectRatio.X / ImageESP_Config.AspectRatio.Y

    local part = Instance.new("Part")
    part.Name = "ESP_" .. plr.UserId
    part.Size = Vector3.new(width, size, size)
    part.Transparency = 1
    part.CanCollide = false
    part.Anchored = true
    part.CanQuery = false
    part.CanTouch = false
    part.Massless = true
    part.Parent = workspace

    for _, face in pairs({Enum.NormalId.Front, Enum.NormalId.Back, Enum.NormalId.Left, Enum.NormalId.Right, Enum.NormalId.Top, Enum.NormalId.Bottom}) do
        local surface = Instance.new("SurfaceGui")
        surface.Face = face
        surface.CanvasSize = Vector2.new(100 * (ImageESP_Config.AspectRatio.X / ImageESP_Config.AspectRatio.Y), 100)
        surface.AlwaysOnTop = true
        surface.ZIndexBehavior = Enum.ZIndexBehavior.Global
        surface.Parent = part

        local imgLabel = Instance.new("ImageLabel")
        imgLabel.Size = UDim2.new(1, 0, 1, 0)
        imgLabel.BackgroundTransparency = 1
        imgLabel.Image = img
        imgLabel.ScaleType = Enum.ScaleType.Fit
        imgLabel.Parent = surface
    end

    ImageESP_Objects[plr.UserId] = { part = part, torso = torso, player = plr }
end

function ImageESP_UpdatePositions()
    local cam = workspace.CurrentCamera
    if not cam then return end
    local camPos = cam.CFrame.Position
    local maxDist = ImageESP_Config.MaxDistance
    local maxDistSq = maxDist * maxDist

    for uid, data in pairs(ImageESP_Objects) do
        if not data.part or not data.part.Parent then
            ImageESP_Objects[uid] = nil
        elseif not data.torso or not data.torso.Parent then
            if data.part then data.part:Destroy() end
            ImageESP_Objects[uid] = nil
        else
            local delta = data.torso.Position - camPos
            if delta.Magnitude > maxDist then
                if data.part.Parent then data.part.Parent = nil end
            else
                if not data.part.Parent then data.part.Parent = workspace end
                data.part.CFrame = CFrame.new(data.torso.Position + ImageESP_Config.Offset, camPos)
            end
        end
    end
end

function ImageESP_Remove(player)
    local data = ImageESP_Objects[player.UserId]
    if data and data.part then
        data.part:Destroy()
    end
    ImageESP_Objects[player.UserId] = nil
end

function ImageESP_Clear()
    for _, data in pairs(ImageESP_Objects) do
        if data.part then data.part:Destroy() end
    end
    table.clear(ImageESP_Objects)
end

function ImageESP_Refresh()
    ImageESP_Clear()

    if not ImageESP_Enabled then return end

    local img = ImageESP_LoadAsset(ImageESP_FilePath)
    if not img then return end

    for _, plr in ipairs(Players:GetPlayers()) do
        if plr ~= LocalPlayer and plr.Character then
            ImageESP_Create(plr, img)
        end
    end
end

function ImageESP_TrackPlayer(plr)
    if ImageESP_PlayerConns[plr] then return end
    local conns = {}

    table.insert(conns, plr.CharacterAdded:Connect(function()
        task.wait(0.5)
        if ImageESP_Enabled then
            local img = ImageESP_LoadAsset(ImageESP_FilePath)
            if img then ImageESP_Create(plr, img) end
        end
    end))

    table.insert(conns, plr.CharacterRemoving:Connect(function()
        ImageESP_Remove(plr)
    end))

    ImageESP_PlayerConns[plr] = conns
end

function ImageESP_UntrackPlayer(plr)
    local conns = ImageESP_PlayerConns[plr]
    if conns then
        for _, c in ipairs(conns) do
            pcall(function() c:Disconnect() end)
        end
        ImageESP_PlayerConns[plr] = nil
    end
    ImageESP_Remove(plr)
end

function ImageESP_RenderTick()
    if not ImageESP_Enabled then return end
    if next(ImageESP_Objects) then
        ImageESP_UpdatePositions()
    end
end

function ImageESP_Start()
    if not ImageESP_RenderConnection then
        ImageESP_RenderConnection = _52.RenderStepped:Connect(ImageESP_RenderTick)
    end

    if not ImageESP_ConnectionAdded then
        ImageESP_ConnectionAdded = Players.PlayerAdded:Connect(function(plr)
            if ImageESP_Objects[plr.UserId] then
                ImageESP_Remove(plr)
            end
            if ImageESP_Enabled then
                ImageESP_TrackPlayer(plr)
            end
        end)
    end

    if not ImageESP_ConnectionRemoving then
        ImageESP_ConnectionRemoving = Players.PlayerRemoving:Connect(function(plr)
            ImageESP_UntrackPlayer(plr)
        end)
    end

    if not ImageESP_ConnectionLocalAdded then
        ImageESP_ConnectionLocalAdded = LocalPlayer.CharacterAdded:Connect(function()
            task.wait(0.5)
            if ImageESP_Enabled then ImageESP_Refresh() end
        end)
    end

    for _, plr in ipairs(Players:GetPlayers()) do
        if plr ~= LocalPlayer then
            ImageESP_TrackPlayer(plr)
        end
    end
end

function ImageESP_Stop()
    if ImageESP_RenderConnection then
        pcall(function() ImageESP_RenderConnection:Disconnect() end)
        ImageESP_RenderConnection = nil
    end

    if ImageESP_ConnectionAdded then
        pcall(function() ImageESP_ConnectionAdded:Disconnect() end)
        ImageESP_ConnectionAdded = nil
    end

    if ImageESP_ConnectionRemoving then
        pcall(function() ImageESP_ConnectionRemoving:Disconnect() end)
        ImageESP_ConnectionRemoving = nil
    end

    if ImageESP_ConnectionLocalAdded then
        pcall(function() ImageESP_ConnectionLocalAdded:Disconnect() end)
        ImageESP_ConnectionLocalAdded = nil
    end

    for plr, conns in pairs(ImageESP_PlayerConns) do
        for _, c in ipairs(conns) do
            pcall(function() c:Disconnect() end)
        end
    end
    table.clear(ImageESP_PlayerConns)

    ImageESP_Clear()
end

_78:AddToggle('MarinESP', {
    Text = 'Marin ESP',
    Default = false,
    Searchable = true,
    Callback = function(value)
        ImageESP_Enabled = value
        if value then
            ImageESP_Start()
            ImageESP_Refresh()
        else
            ImageESP_Stop()
        end
    end,
})

_48:OnUnload(function()
    ImageESP_Enabled = false
    ImageESP_Stop()
    ImageESP_Cached = nil
end)

-- China hat core
ChinaHat = {}
enabled = false
enabledSelf = false
c1 = Color3.fromRGB(255, 0, 0)
c2 = Color3.fromRGB(0, 255, 0)
c3 = Color3.fromRGB(0, 0, 255)
c4 = Color3.fromRGB(255, 255, 0)
height = 0.7
radius = 2
sides = 25
hatTrs = 0.35
lineTrs = 1
speed = 0.2
offsetY = 0.5
CH_drawings = {}
CH_drawingsSelf = {}
CH_connection = nil
CH_selfConnection = nil
Players = game:GetService("Players")
LocalPlayer = Players.LocalPlayer
cam = workspace.CurrentCamera

function lerp(a, b, t) return a + (b - a) * t end

function lerpColor(a, b, t)
    return Color3.new(lerp(a.R, b.R, t), lerp(a.G, b.G, t), lerp(a.B, b.B, t))
end

function getColor(progress, time)
    local s = (progress + time * speed) % 1
    if s < 0.25 then return lerpColor(c1, c2, s / 0.25)
    elseif s < 0.5 then return lerpColor(c2, c3, (s - 0.25) / 0.25)
    elseif s < 0.75 then return lerpColor(c3, c4, (s - 0.5) / 0.25)
    else return lerpColor(c4, c1, (s - 0.75) / 0.25) end
end

function CH_setVisibility(list, visible)
    for _, d in ipairs(list) do
        if d[1] then pcall(function() d[1].Visible = visible end) end
        if d[2] then pcall(function() d[2].Visible = visible end) end
    end
end

function CH_destroyList(list)
    for _, d in ipairs(list) do
        if d[1] then pcall(function() d[1]:Remove() end) end
        if d[2] then pcall(function() d[2]:Remove() end) end
    end
    for i = #list, 1, -1 do list[i] = nil end
end

function CH_cleanup()
    if CH_connection then CH_connection:Disconnect() CH_connection = nil end
    if CH_selfConnection then CH_selfConnection:Disconnect() CH_selfConnection = nil end
    CH_destroyList(CH_drawings)
    CH_destroyList(CH_drawingsSelf)
end

function CH_buildList(list, count)
    CH_destroyList(list)
    for _ = 1, count do
        local line = Drawing.new('Line')
        local triangle = Drawing.new('Triangle')
        line.ZIndex = 2
        line.Thickness = 1
        line.Transparency = 1
        triangle.ZIndex = 1
        triangle.Filled = true
        triangle.Transparency = 1
        line.Visible = false
        triangle.Visible = false
        list[#list + 1] = {line, triangle}
    end
end

function CH_renderSelf()
    if not enabledSelf then
        CH_setVisibility(CH_drawingsSelf, false)
        return
    end

    local char = LocalPlayer.Character
    local head = char and char:FindFirstChild('Head')
    local hum = char and char:FindFirstChildOfClass('Humanoid')
    if not char or not head or not hum or hum.Health <= 0 then
        CH_setVisibility(CH_drawingsSelf, false)
        return
    end

    local headScreen = cam:WorldToViewportPoint(head.Position)
    if headScreen.Z <= 0 then
        CH_setVisibility(CH_drawingsSelf, false)
        return
    end

    if #CH_drawingsSelf ~= sides then
        CH_buildList(CH_drawingsSelf, sides)
    end

    local time = tick()
    local fullCircle = math.pi * 2
    local topPos = head.Position + Vector3.new(0, offsetY + height, 0)
    local basePos = head.Position + Vector3.new(0, offsetY, 0)

    for i = 1, sides do
        local line, triangle = CH_drawingsSelf[i][1], CH_drawingsSelf[i][2]
        local progress1 = i / sides
        local angle1 = progress1 * fullCircle
        local angle2 = ((i % sides) + 1) / sides * fullCircle
        local point1 = basePos + Vector3.new(math.cos(angle1), 0, math.sin(angle1)) * radius
        local point2 = basePos + Vector3.new(math.cos(angle2), 0, math.sin(angle2)) * radius
        local screen1 = cam:WorldToViewportPoint(point1)
        local screen2 = cam:WorldToViewportPoint(point2)
        local screenTop = cam:WorldToViewportPoint(topPos)
        local col = getColor(progress1, time)

        if screen1.Z > 0 and screen2.Z > 0 and screenTop.Z > 0 then
            line.From = Vector2.new(screen1.X, screen1.Y)
            line.To = Vector2.new(screen2.X, screen2.Y)
            line.Color = col
            line.Transparency = lineTrs
            line.Visible = true

            triangle.PointA = Vector2.new(screenTop.X, screenTop.Y)
            triangle.PointB = line.From
            triangle.PointC = line.To
            triangle.Color = col
            triangle.Transparency = hatTrs
            triangle.Visible = true
        else
            line.Visible = false
            triangle.Visible = false
        end
    end
end

function render()
    if not enabled then
        CH_setVisibility(CH_drawings, false)
        return
    end

    local visibleCount = 0
    local list = Players:GetPlayers()
    for _, player in ipairs(list) do
        if player ~= LocalPlayer then
            local char = player.Character
            local head = char and char:FindFirstChild('Head')
            local hum = char and char:FindFirstChildOfClass('Humanoid')
            if char and head and hum and hum.Health > 0 then
                local headScreen = cam:WorldToViewportPoint(head.Position)
                if headScreen.Z > 0 then
                    visibleCount = visibleCount + 1
                end
            end
        end
    end

    if visibleCount == 0 then
        CH_setVisibility(CH_drawings, false)
        return
    end

    local needed = visibleCount * sides
    if #CH_drawings ~= needed then
        CH_buildList(CH_drawings, needed)
    end

    local time = tick()
    local fullCircle = math.pi * 2
    local drawIndex = 0

    for _, player in ipairs(list) do
        if player ~= LocalPlayer then
            local char = player.Character
            local head = char and char:FindFirstChild('Head')
            local hum = char and char:FindFirstChildOfClass('Humanoid')

            if char and head and hum and hum.Health > 0 then
                local headScreen = cam:WorldToViewportPoint(head.Position)
                if headScreen.Z > 0 then
                    local topPos = head.Position + Vector3.new(0, offsetY + height, 0)
                    local basePos = head.Position + Vector3.new(0, offsetY, 0)

                    for i = 1, sides do
                        drawIndex = drawIndex + 1
                        local entry = CH_drawings[drawIndex]
                        if entry then
                            local line, triangle = entry[1], entry[2]
                            local progress1 = i / sides
                            local angle1 = progress1 * fullCircle
                            local angle2 = ((i % sides) + 1) / sides * fullCircle
                            local point1 = basePos + Vector3.new(math.cos(angle1), 0, math.sin(angle1)) * radius
                            local point2 = basePos + Vector3.new(math.cos(angle2), 0, math.sin(angle2)) * radius
                            local screen1 = cam:WorldToViewportPoint(point1)
                            local screen2 = cam:WorldToViewportPoint(point2)
                            local screenTop = cam:WorldToViewportPoint(topPos)
                            local col = getColor(progress1, time)

                            if screen1.Z > 0 and screen2.Z > 0 and screenTop.Z > 0 then
                                line.From = Vector2.new(screen1.X, screen1.Y)
                                line.To = Vector2.new(screen2.X, screen2.Y)
                                line.Color = col
                                line.Transparency = lineTrs
                                line.Visible = true

                                triangle.PointA = Vector2.new(screenTop.X, screenTop.Y)
                                triangle.PointB = line.From
                                triangle.PointC = line.To
                                triangle.Color = col
                                triangle.Transparency = hatTrs
                                triangle.Visible = true
                            else
                                line.Visible = false
                                triangle.Visible = false
                            end
                        end
                    end
                end
            end
        end
    end

    for i = drawIndex + 1, #CH_drawings do
        local entry = CH_drawings[i]
        if entry then
            if entry[1] then entry[1].Visible = false end
            if entry[2] then entry[2].Visible = false end
        end
    end
end

function ChinaHat:setEnabled(val)
    enabled = val
    if enabled then
        if not CH_connection then
            CH_connection = game:GetService("RunService").RenderStepped:Connect(render)
        end
    else
        CH_setVisibility(CH_drawings, false)
        if CH_connection then CH_connection:Disconnect() CH_connection = nil end
    end
end

function ChinaHat:setSelfEnabled(val)
    enabledSelf = val
    if enabledSelf then
        if not CH_selfConnection then
            CH_selfConnection = game:GetService("RunService").RenderStepped:Connect(CH_renderSelf)
        end
    else
        CH_setVisibility(CH_drawingsSelf, false)
        if CH_selfConnection then CH_selfConnection:Disconnect() CH_selfConnection = nil end
        CH_destroyList(CH_drawingsSelf)
    end
end

function ChinaHat:setColor1(c) c1 = c end
function ChinaHat:setColor2(c) c2 = c end
function ChinaHat:setColor3(c) c3 = c end
function ChinaHat:setColor4(c) c4 = c end
function ChinaHat:setHeight(h) height = h end
function ChinaHat:setRadius(r) radius = r end
function ChinaHat:setSides(s) sides = s CH_destroyList(CH_drawings) CH_destroyList(CH_drawingsSelf) end
function ChinaHat:setHatTransparency(t) hatTrs = t end
function ChinaHat:setLineTransparency(t) lineTrs = t end
function ChinaHat:setSpeed(s) speed = s end
function ChinaHat:setOffsetY(o) offsetY = o end

