AnimHDAttr = {
    idle1 = "IdleAnimation",
    idle2 = "IdleAnimation2",
    walk  = "WalkAnimation",
    run   = "RunAnimation",
    jump  = "JumpAnimation",
    climb = "ClimbAnimation",
    fall  = "FallAnimation",
}

AnimSlots = {
    {key = 'idle1', folder = 'idle',  name = 'Animation1'},
    {key = 'idle2', folder = 'idle',  name = 'Animation2'},
    {key = 'walk',  folder = 'walk',  name = 'WalkAnim'},
    {key = 'run',   folder = 'run',   name = 'RunAnim'},
    {key = 'jump',  folder = 'jump',  name = 'JumpAnim'},
    {key = 'climb', folder = 'climb', name = 'ClimbAnim'},
    {key = 'fall',  folder = 'fall',  name = 'FallAnim'},
}

AnimChangerEnabled  = false
AnimCharConn        = nil
AnimDebounceRunning = false
AnimPendingSet      = nil
AnimDebounceDelay   = 0.25
OriginalAnims       = setmetatable({}, {__mode = 'k'})
CachedAnimate       = setmetatable({}, {__mode = 'k'})
OriginalDescIDs     = setmetatable({}, {__mode = 'k'})

function AnimGetSlotObject(Animate, slot)
    local folder = Animate:FindFirstChild(slot.folder)
    return folder and folder:FindFirstChild(slot.name)
end

function AnimWaitForAnimate(char)
    if not char then return nil end
    local cached = CachedAnimate[char]
    if cached and cached.Parent then return cached end

    local Animate = char:FindFirstChild('Animate') or char:WaitForChild('Animate', 5)
    if not Animate then return nil end

    CachedAnimate[char] = Animate
    return Animate
end

function AnimGetDesc(char)
    local hum = char and char:FindFirstChildOfClass('Humanoid')
    if not hum then return nil end
    local desc = hum:FindFirstChildOfClass('HumanoidDescription')
    if desc then return desc end
    local ok, applied = pcall(function() return hum:GetAppliedDescription() end)
    if ok and applied then return applied end
    return nil
end

function AnimCaptureOriginals(char, Animate, desc)
    if not OriginalAnims[char] then
        local saved = {}
        for _, slot in ipairs(AnimSlots) do
            local obj = AnimGetSlotObject(Animate, slot)
            if obj then saved[slot.key] = obj.AnimationId end
        end
        OriginalAnims[char] = saved
    end

    if desc and not OriginalDescIDs[char] then
        local savedDesc = {}
        for key, attr in pairs(AnimHDAttr) do
            local ok, v = pcall(function() return desc:GetAttribute(attr) end)
            if ok and v ~= nil then
                savedDesc[key] = v
            end
        end
        OriginalDescIDs[char] = savedDesc
    end
end

function AnimReloadAnimate(char, Animate)
    local hum = char and char:FindFirstChildOfClass('Humanoid')
    local animator = hum and hum:FindFirstChildOfClass('Animator')
    if animator then
        local ok, tracks = pcall(function() return animator:GetPlayingAnimationTracks() end)
        if ok then
            for _, track in ipairs(tracks) do
                pcall(function() track:Stop(0.1) end)
            end
        end
    end

    task.wait(0.1)

    if Animate and Animate.Parent then
        Animate.Disabled = true
        task.wait(0.05)
        if Animate.Parent then
            Animate.Disabled = false
        end
    end
end

function AnimNotify(msg)
    pcall(function() Library:Notify(msg, 4) end)
end

function AnimApplySet(setName)
    local char = _56.Character
    if not char then return end

    local Animate = AnimWaitForAnimate(char)
    if not Animate or not char.Parent then return end

    local desc = AnimGetDesc(char)
    AnimCaptureOriginals(char, Animate, desc)

    local ids = {}
    local isDefault = (not setName) or setName == 'Default'
    if not isDefault then
        local data = AnimationSets[setName]
        if not data then return end
        local hum = char:FindFirstChildOfClass('Humanoid')
        if hum and hum.RigType == Enum.HumanoidRigType.R6 then
            AnimNotify(setName .. ' is R15 only - this character is R6 :(')
            return
        end
        for _, slot in ipairs(AnimSlots) do
            ids[slot.key] = ASSET .. data[slot.key]
        end
    else
        ids = OriginalAnims[char] or {}
    end

    for _, slot in ipairs(AnimSlots) do
        local obj = AnimGetSlotObject(Animate, slot)
        if obj and ids[slot.key] then
            obj.AnimationId = ids[slot.key]
        end
    end

    if desc then
        local descSource = isDefault and OriginalDescIDs[char] or nil
        for key, attr in pairs(AnimHDAttr) do
            local id
            if isDefault then
                id = descSource and descSource[key]
            else
                id = ids[key]
            end
            if id then
                local bare = tostring(id):gsub("^rbxassetid://", ""):gsub("^http://www%.roblox%.com/asset/%?id=", "")
                pcall(function() desc:SetAttribute(attr, bare) end)
                pcall(function() desc[attr] = tonumber(bare) or bare end)
            end
        end
    end

    AnimReloadAnimate(char, Animate)
end

function AnimScheduleApply(setName)
    AnimPendingSet = setName
    if AnimDebounceRunning then return end
    AnimDebounceRunning = true
    task.spawn(function()
        while AnimPendingSet do
            local set = AnimPendingSet
            AnimPendingSet = nil
            AnimApplySet(set)
            task.wait(AnimDebounceDelay)
        end
        AnimDebounceRunning = false
    end)
end

function AnimRestoreOriginal()
    AnimApplySet('Default')
end

if _56.Character then
    task.spawn(function()
        local Animate = AnimWaitForAnimate(_56.Character)
        if Animate then
            local desc = AnimGetDesc(_56.Character)
            AnimCaptureOriginals(_56.Character, Animate, desc)
        end
    end)
end

if AnimCharConn then AnimCharConn:Disconnect() end
AnimCharConn = _56.CharacterAdded:Connect(function(char)
    local Animate = AnimWaitForAnimate(char)
    if not Animate then return end
    local desc = AnimGetDesc(char)
    AnimCaptureOriginals(char, Animate, desc)
    task.wait(0.5)
    if AnimChangerEnabled then
        AnimApplySet(Options.AnimSet.Value or 'Default')
    end
end)

AnimationSection:AddToggle('AnimSetEnabled', {
    Text = 'Apply Animation',
    Default = false,
    Searchable = true,
})

AnimationSection:AddDropdown('AnimSet', {
    Text = 'Animation',
    Values = (function()
        local names = {'Default'}
        local sets = {}
        for name in pairs(AnimationSets) do table.insert(sets, name) end
        table.sort(sets)
        for _, name in ipairs(sets) do table.insert(names, name) end
        return names
    end)(),
    Default = 'Default',
})

Toggles.AnimSetEnabled:OnChanged(function(value)
    AnimChangerEnabled = value
    if value then
        AnimScheduleApply(Options.AnimSet.Value or 'Default')
    else
        AnimRestoreOriginal()
    end
end)

Options.AnimSet:OnChanged(function(value)
    if AnimChangerEnabled then
        AnimScheduleApply(value)
    end
end)

_48:OnUnload(function()
    AnimChangerEnabled = false
    if AnimCharConn then AnimCharConn:Disconnect() AnimCharConn = nil end
    AnimRestoreOriginal()
end)

-- Character Material / Self Charms Core
SelfChams = {}
SC_lp = game:GetService("Players").LocalPlayer
SC_loopManager = _52
SC_enabled = false
SC_color = Color3.fromRGB(155, 125, 175)
SC_transparency = 0
SC_reflectance = 0
SC_material = 'ForceField'
SC_effect = 'none'
SC_addEffect = 'none'
SC_particleColor = Color3.fromRGB(255, 255, 255)
SC_particleTransparency = 0
SC_particleLifetime = 2.0
SC_particleRate = 60
SC_heatTime = 0
SC_charConnection = nil
SC_cachedData = { parts = {}, clothing = {}, bodyColors = nil, appearance = {}, variants = {}, applied = false }
SC_lastHeatTick = 0
SC_heatConnection = nil
SC_guards = {}

-- scan line
SC_scanOn = false
SC_scanColor = Color3.fromRGB(255, 255, 255)
SC_scanPeriod = 2.5
SC_scanWidth = 0.22
SC_scanPause = 0.6
SC_scanDir = 'Up'
SC_scanTime = 0
SC_scanConn = nil
SC_scanInt = setmetatable({}, { __mode = 'k' })

SC_r15Parts = {
    'LeftFoot', 'LeftLowerLeg', 'LeftUpperLeg',
    'RightFoot', 'RightLowerLeg', 'RightUpperLeg',
    'LeftHand', 'LeftLowerArm', 'LeftUpperArm',
    'RightHand', 'RightLowerArm', 'RightUpperArm',
    'LowerTorso', 'UpperTorso', 'Head'
}

SC_heatMap = {
    LeftFoot = 0.7, LeftLowerLeg = 0.3, LeftUpperLeg = 0.5,
    RightFoot = 0.7, RightLowerLeg = 0.3, RightUpperLeg = 0.5,
    LeftHand = 0.7, LeftLowerArm = 0.3, LeftUpperArm = 0.5,
    RightHand = 0.7, RightLowerArm = 0.3, RightUpperArm = 0.5,
    LowerTorso = 0.3, UpperTorso = 0.5, Head = 0.5,
}

SC_partSet = {}
for _, name in ipairs(SC_r15Parts) do SC_partSet[name] = true end

function SC_isR15Part(name) return SC_partSet[name] == true end

function SC_getMaterial()
    if SC_material == 'Neon' then return Enum.Material.Neon end
    if SC_material == 'Glass' then return Enum.Material.Glass end
    return Enum.Material.ForceField
end

function SC_colorFor(part)
    local k = SC_scanInt[part]
    if k and k > 0.002 then return SC_color:Lerp(SC_scanColor, k) end
    return SC_color
end

function SC_cacheCharacter(char)
    if not char then return end
    SC_cachedData.parts = {}
    SC_cachedData.clothing = {}
    SC_cachedData.bodyColors = nil
    SC_cachedData.appearance = {}
    SC_cachedData.variants = {}
    SC_cachedData.applied = false

    for _, part in ipairs(char:GetChildren()) do
        if SC_isR15Part(part.Name) and (part:IsA('MeshPart') or part:IsA('BasePart')) then
            SC_cachedData.parts[part.Name] = {
                Material = part.Material, Color = part.Color,
                Transparency = part.Transparency, Reflectance = part.Reflectance,
                TextureID = part:IsA('MeshPart') and part.TextureID or nil,
            }
        end
    end

    for _, desc in ipairs(char:GetDescendants()) do
        if desc:IsA('Shirt') then SC_cachedData.clothing.Shirt = desc.ShirtTemplate
        elseif desc:IsA('Pants') then SC_cachedData.clothing.Pants = desc.PantsTemplate end
    end
end

function SC_stripOverrides(part)
    if not part or not part.Parent then return end
    for _, child in ipairs(part:GetChildren()) do
        if child:IsA('SurfaceAppearance') then
            SC_cachedData.appearance[child] = part
            pcall(function() child.Parent = nil end)
        end
    end
    pcall(function()
        if part.MaterialVariant ~= '' then
            SC_cachedData.variants[part] = part.MaterialVariant
            part.MaterialVariant = ''
        end
    end)
end

function SC_guardPart(part)
    if SC_guards[part] then return end
    local conns = {}

    table.insert(conns, part:GetPropertyChangedSignal('Material'):Connect(function()
        if not SC_enabled then return end
        if not part.Parent then return end
        local want = SC_getMaterial()
        if part.Material ~= want then pcall(function() part.Material = want end) end
    end))

    table.insert(conns, part:GetPropertyChangedSignal('Color'):Connect(function()
        if not SC_enabled then return end
        if not part.Parent then return end
        local want = SC_colorFor(part)
        if part.Color ~= want then pcall(function() part.Color = want end) end
    end))

    table.insert(conns, part.ChildAdded:Connect(function(child)
        if not SC_enabled then return end
        if child:IsA('SurfaceAppearance') then
            task.defer(function()
                if SC_enabled and child.Parent == part then SC_stripOverrides(part) end
            end)
        end
    end))

    SC_guards[part] = conns
end

function SC_clearGuards()
    for _, conns in pairs(SC_guards) do
        for _, c in ipairs(conns) do pcall(function() c:Disconnect() end) end
    end
    SC_guards = {}
end

function SC_removeParticles(char)
    if not char then return end
    for _, part in ipairs(char:GetChildren()) do
        if SC_isR15Part(part.Name) then
            local stars = part:FindFirstChild('stars')
            local specks = part:FindFirstChild('Specks')
            if stars then pcall(function() stars:Destroy() end) end
            if specks then pcall(function() specks:Destroy() end) end
        end
    end
end

function SC_applyStars(char)
    if not char then return end
    for _, part in ipairs(char:GetChildren()) do
        if SC_isR15Part(part.Name) and (part:IsA('MeshPart') or part:IsA('BasePart')) then
            local stars = part:FindFirstChild('stars')
            if not stars then
                stars = Instance.new('ParticleEmitter')
                stars.Name = 'stars'
                stars.Parent = part
                pcall(function()
                    stars.LockedToPart = true
                    stars.LightEmission = 1
                    stars.Drag = 5
                    stars.Squash = NumberSequence.new(-0.1)
                    stars.Speed = NumberRange.new(0.001, 0.001)
                    stars.Brightness = 3
                    stars.ZOffset = 1
                    stars.Size = NumberSequence.new({NumberSequenceKeypoint.new(0, 0), NumberSequenceKeypoint.new(0.508, 0.05, 0.05), NumberSequenceKeypoint.new(1, 0)})
                    stars.Texture = 'rbxassetid://1084996976'
                    stars.EmissionDirection = Enum.NormalId.Bottom
                end)
            end
            pcall(function()
                stars.Lifetime = NumberRange.new(SC_particleLifetime, SC_particleLifetime * 1.5)
                stars.Rate = SC_particleRate
                stars.Color = ColorSequence.new(SC_particleColor)
                stars.Transparency = NumberSequence.new(SC_particleTransparency)
            end)
        end
    end
end

function SC_applyParticles(char)
    if not char then return end
    for _, part in ipairs(char:GetChildren()) do
        if SC_isR15Part(part.Name) and (part:IsA('MeshPart') or part:IsA('BasePart')) then
            local specks = part:FindFirstChild('Specks')
            if not specks then
                specks = Instance.new('ParticleEmitter')
                specks.Name = 'Specks'
                specks.Parent = part
                pcall(function()
                    specks.SpreadAngle = Vector2.new(90, 90)
                    specks.LightEmission = 1
                    specks.Drag = 3
                    specks.Squash = NumberSequence.new(0)
                    specks.Speed = NumberRange.new(1, 2)
                    specks.Brightness = 4.2
                    specks.Size = NumberSequence.new(0.15)
                    specks.Acceleration = Vector3.new(0, -6, 0)
                    specks.RotSpeed = NumberRange.new(-45, 45)
                    specks.Texture = 'rbxassetid://7216849703'
                end)
            end
            pcall(function()
                specks.Lifetime = NumberRange.new(SC_particleLifetime, SC_particleLifetime * 1.5)
                specks.Rate = SC_particleRate
                local t = SC_particleTransparency
                specks.Transparency = NumberSequence.new({NumberSequenceKeypoint.new(0, math.min(1, t + 0.8)), NumberSequenceKeypoint.new(0.25, math.max(0, t - 0.1)), NumberSequenceKeypoint.new(1, math.min(1, t + 0.8))})
                specks.Color = ColorSequence.new(SC_particleColor)
            end)
        end
    end
end

function SC_applyChams(char, heatPulse, skipParticles)
    if not char then return end

    for _, desc in ipairs(char:GetDescendants()) do
        if desc:IsA('Pants') or desc:IsA('Shirt') then
            pcall(function() desc:Destroy() end)
        end
    end

    local mat = SC_getMaterial()

    for _, part in ipairs(char:GetChildren()) do
        if SC_isR15Part(part.Name) and (part:IsA('MeshPart') or part:IsA('BasePart')) then
            local trans = SC_transparency
            if SC_effect == 'heat' and SC_heatMap[part.Name] then
                local base = SC_heatMap[part.Name]
                if heatPulse then trans = base + (math.min(base + 0.2, 1) - base) * heatPulse
                else trans = base end
            end

            SC_stripOverrides(part)

            if part:IsA('MeshPart') then
                pcall(function() part.Material = mat part.Color = SC_colorFor(part) part.Transparency = trans part.Reflectance = SC_reflectance part.TextureID = '' end)
            elseif part:IsA('BasePart') then
                pcall(function() part.Material = mat part.Color = SC_colorFor(part) part.Reflectance = SC_reflectance if part.Transparency < 1 then part.Transparency = trans end end)
            end

            SC_guardPart(part)
        end
    end

    SC_cachedData.applied = true

    if not skipParticles then
        if SC_addEffect == 'stars' then
            SC_applyStars(char)
        elseif SC_addEffect == 'particles' then
            SC_applyParticles(char)
        end
    end
end

function SC_restoreCharacter(char)
    SC_clearGuards()
    if not char then return end
    SC_removeParticles(char)

    for _, part in ipairs(char:GetChildren()) do
        if SC_isR15Part(part.Name) and SC_cachedData.parts[part.Name] then
            local data = SC_cachedData.parts[part.Name]
            pcall(function()
                part.Material = data.Material part.Color = data.Color
                part.Transparency = data.Transparency part.Reflectance = data.Reflectance
                if part:IsA('MeshPart') and data.TextureID then part.TextureID = data.TextureID end
            end)
        end
    end

    for inst, part in pairs(SC_cachedData.appearance) do
        if part and part.Parent and inst and inst.Parent == nil then
            pcall(function() inst.Parent = part end)
        end
    end
    SC_cachedData.appearance = {}
    for part, variant in pairs(SC_cachedData.variants) do
        if part and part.Parent then pcall(function() part.MaterialVariant = variant end) end
    end
    SC_cachedData.variants = {}

    if SC_cachedData.clothing.Shirt then
        local hasShirt = false
        for _, d in ipairs(char:GetDescendants()) do
            if d:IsA('Shirt') then hasShirt = true break end
        end
        if not hasShirt then
            pcall(function() local shirt = Instance.new('Shirt') shirt.ShirtTemplate = SC_cachedData.clothing.Shirt shirt.Parent = char end)
        end
    end
    if SC_cachedData.clothing.Pants then
        local hasPants = false
        for _, d in ipairs(char:GetDescendants()) do
            if d:IsA('Pants') then hasPants = true break end
        end
        if not hasPants then
            pcall(function() local pants = Instance.new('Pants') pants.PantsTemplate = SC_cachedData.clothing.Pants pants.Parent = char end)
        end
    end

    SC_cachedData.parts = {}
    SC_cachedData.clothing = {}
    SC_cachedData.applied = false
end

function SC_stopHeatLoop()
    if SC_heatConnection then SC_heatConnection:Disconnect() SC_heatConnection = nil end
    SC_heatTime = 0 SC_lastHeatTick = 0
end

function SC_startHeatLoop()
    SC_stopHeatLoop()
    SC_lastHeatTick = tick()
    SC_heatConnection = SC_loopManager.Heartbeat:Connect(function()
        if not SC_enabled or SC_effect ~= 'heat' then SC_stopHeatLoop() return end
        local char = SC_lp.Character
        if not char then return end
        local now = tick()
        local dt = now - SC_lastHeatTick
        SC_lastHeatTick = now
        SC_heatTime = SC_heatTime + dt
        local pulse = math.sin(SC_heatTime * 2) * 0.5 + 0.5
        SC_applyChams(char, pulse, true)
    end)
end

function SC_scanPos(t)
    local travel = 1 + SC_scanWidth * 2
    local cycle = SC_scanPeriod + SC_scanPause
    local ph = t % cycle
    if SC_scanDir == 'Ping-Pong' then
        cycle = (SC_scanPeriod + SC_scanPause) * 2
        ph = t % cycle
        local half = cycle / 2
        local up = ph < half
        local p = (up and ph or ph - half) / SC_scanPeriod
        if p > 1 then return nil end
        local s = -SC_scanWidth + travel * p
        return up and s or (1 - s)
    end
    local p = ph / SC_scanPeriod
    if p > 1 then return nil end
    local s = -SC_scanWidth + travel * p
    if SC_scanDir == 'Down' then s = 1 - s end
    return s
end

function SC_bandAt(y, baseY, height, s)
    if not s then return 0 end
    local t = math.clamp((y - baseY) / height, 0, 1)
    local k = 1 - math.abs(t - s) / SC_scanWidth
    if k <= 0 then return 0 end
    return k * k * (3 - 2 * k)
end

function SC_stopScan()
    if SC_scanConn then SC_scanConn:Disconnect() SC_scanConn = nil end
    SC_scanTime = 0
    local had = false
    for part in pairs(SC_scanInt) do had = true break end
    SC_scanInt = setmetatable({}, { __mode = 'k' })
    if had and SC_enabled and SC_lp.Character then SC_applyChams(SC_lp.Character, nil, true) end
end

function SC_startScan()
    if SC_scanConn then SC_scanConn:Disconnect() SC_scanConn = nil end
    SC_scanTime = 0
    local last = tick()
    SC_scanConn = SC_loopManager.Heartbeat:Connect(function()
        if not SC_enabled or not SC_scanOn then SC_stopScan() return end
        local char = SC_lp.Character
        local root = char and char:FindFirstChild('HumanoidRootPart')
        if not root then return end

        local now = tick()
        SC_scanTime = SC_scanTime + math.min(now - last, 0.1)
        last = now

        local s = SC_scanPos(SC_scanTime)
        local height = 6.2
        local baseY = root.Position.Y - 3.2

        for _, part in ipairs(char:GetChildren()) do
            if SC_isR15Part(part.Name) and part:IsA('BasePart') then
                SC_scanInt[part] = SC_bandAt(part.Position.Y, baseY, height, s)
                local want = SC_colorFor(part)
                if part.Color ~= want then
                    pcall(function() part.Color = want end)
                end
            end
        end
    end)
end

function SelfChams:setScan(on)
    SC_scanOn = on == true
    if SC_scanOn and SC_enabled then SC_startScan() else SC_stopScan() end
end

function SelfChams:setEnabled(val)
    val = val == true
    if val == SC_enabled then
        if not val then
            local char = SC_lp.Character
            if SC_cachedData.applied then SC_restoreCharacter(char) end
        end
        return
    end

    SC_enabled = val
    local char = SC_lp.Character

    if SC_enabled then
        SC_stopHeatLoop()
        SC_clearGuards()
        SC_cacheCharacter(char)
        SC_applyChams(char)
        if SC_effect == 'heat' then SC_startHeatLoop() end
        if SC_scanOn then SC_startScan() end

        if SC_charConnection then SC_charConnection:Disconnect() end
        SC_charConnection = SC_lp.CharacterAdded:Connect(function(newChar)
            SC_stopHeatLoop()
            SC_clearGuards()
            newChar:WaitForChild('Humanoid')
            task.wait(1.1)
            if SC_enabled then
                SC_cacheCharacter(newChar)
                SC_applyChams(newChar)
                if SC_effect == 'heat' then SC_startHeatLoop() end
                task.wait(0.5)
                if SC_enabled then SC_applyChams(newChar) end
            end
        end)
    else
        SC_stopHeatLoop()
        SC_stopScan()
        if SC_charConnection then SC_charConnection:Disconnect() SC_charConnection = nil end
        if SC_cachedData.applied then
            SC_restoreCharacter(char)
        else
            SC_clearGuards()
            SC_removeParticles(char)
            SC_cachedData.parts = {}
            SC_cachedData.clothing = {}
            SC_cachedData.appearance = {}
            SC_cachedData.variants = {}
            SC_cachedData.applied = false
        end
    end
end

function SelfChams:setColor(c) SC_color = c if SC_enabled then SC_applyChams(SC_lp.Character) end end
function SelfChams:setTransparency(t) SC_transparency = t if SC_enabled then SC_applyChams(SC_lp.Character) end end
function SelfChams:setReflectance(r) SC_reflectance = r if SC_enabled then SC_applyChams(SC_lp.Character) end end
function SelfChams:setMaterial(m) SC_material = m if SC_enabled then SC_applyChams(SC_lp.Character) end end
function SelfChams:setEffect(e)
    SC_effect = e
    if SC_enabled then
        if e == 'heat' then
            SC_startHeatLoop()
        else
            SC_stopHeatLoop()
            SC_applyChams(SC_lp.Character)
        end
    end
end
function SelfChams:setAddEffect(e)
    if e == SC_addEffect and SC_enabled then return end
    SC_addEffect = e
    if SC_enabled then
        SC_removeParticles(SC_lp.Character)
        if e == 'stars' then SC_applyStars(SC_lp.Character)
        elseif e == 'particles' then SC_applyParticles(SC_lp.Character) end
    end
end

function SelfChams:setParticleColor(c)
    SC_particleColor = c
    if SC_enabled then
        local char = SC_lp.Character
        if SC_addEffect == 'stars' then SC_applyStars(char)
        elseif SC_addEffect == 'particles' then SC_applyParticles(char) end
    end
end

function SelfChams:setParticleTransparency(t)
    SC_particleTransparency = t
    if SC_enabled then
        local char = SC_lp.Character
        if SC_addEffect == 'stars' then SC_applyStars(char)
        elseif SC_addEffect == 'particles' then SC_applyParticles(char) end
    end
end

function SelfChams:setParticleLifetime(l)
    SC_particleLifetime = l
    if SC_enabled then
        local char = SC_lp.Character
        if SC_addEffect == 'stars' then SC_applyStars(char)
        elseif SC_addEffect == 'particles' then SC_applyParticles(char) end
    end
end

function SelfChams:setParticleRate(r)
    SC_particleRate = r
    if SC_enabled then
        local char = SC_lp.Character
        if SC_addEffect == 'stars' then SC_applyStars(char)
        elseif SC_addEffect == 'particles' then SC_applyParticles(char) end
    end
end

