local function hmacBin(keyStr, msg)
    local blockSize = 64
    if #keyStr > blockSize then
        keyStr = hexDecode(sha256hex(keyStr))
    end
    if #keyStr < blockSize then
        keyStr = keyStr .. string.rep("\0", blockSize - #keyStr)
    end
    local ipad, opad = {}, {}
    for i = 1, blockSize do
        ipad[i] = string.char(bit32.bxor(keyStr:byte(i), 0x36))
        opad[i] = string.char(bit32.bxor(keyStr:byte(i), 0x5c))
    end
    local innerHex = sha256hex(table.concat(ipad) .. msg)
    return hexDecode(sha256hex(table.concat(opad) .. hexDecode(innerHex)))
end

local function hmacHex(keyStr, msg)
    local bin = hmacBin(keyStr, msg)
    local out = {}
    for i = 1, #bin do
        out[i] = string.format("%02x", bin:byte(i))
    end
    return table.concat(out)
end

local function hkdfSha256(ikm, salt, info, length)
    local prk = hmacBin(salt, ikm)
    local hashLen = 32
    local n = math.ceil(length / hashLen)
    local okm = {}
    local prev = ""
    for i = 1, n do
        prev = hmacBin(prk, prev .. info .. string.char(i))
        okm[#okm + 1] = prev
    end
    return table.concat(okm):sub(1, length)
end

