    local function fe_copy(a)
        local o = {}
        for i = 1, 16 do o[i] = a[i] end
        return o
    end
    local function fe_carry(o)
        for i = 1, 16 do
            local v = o[i] + 65536
            local c = floor(v / 65536)
            if i < 16 then
