local function signRequest(keyStr, method, pathname, search, nonce, ts, bodyHash)
    local canonical = method .. "|" .. pathname .. (search or "") .. "|" .. nonce .. "|" .. ts .. "|" .. bodyHash
    return hmacHex(keyStr, canonical)
end

local function newSignedHeaders(sessionId, hwid, keyStr, method, pathname, search)
    local nonce = HS:GenerateGUID(false):gsub("%-", ""):sub(1, 32)
    local ts = tostring(math.floor(DateTime.now().UnixTimestampMillis))
    local bodyHash = hmacHex("", "{}")
    local sig = signRequest(keyStr, method, pathname, search, nonce, ts, bodyHash)
    return {
        ["x-session"] = sessionId,
        ["x-hwid"] = hwid,
        ["x-nonce"] = nonce,
        ["x-timestamp"] = ts,
        ["x-signature"] = sig,
    }
end

local function ctrDecrypt(dec, ctB64, keyB64, ivB64)
    local noPad = function(s) return (s:gsub("=+$", "")) end
    local variants = {
        { ctB64, keyB64, ivB64, "CTR" },
        { ctB64, keyB64, ivB64, "ctr" },
        { ctB64, keyB64, ivB64 },
        { noPad(ctB64), noPad(keyB64), noPad(ivB64), "CTR" },
        { noPad(ctB64), noPad(keyB64), noPad(ivB64), "ctr" },
    }
    for _, args in ipairs(variants) do
        local ok, r = pcall(dec, args[1], args[2], args[3], args[4])
        if ok and type(r) == "string" and #r > 0 then
            return r
        end
    end
    if isDeltaExecutor() then
        local ok, r = pcall(dec, ctB64, keyB64, ivB64)
        if ok and type(r) == "string" and #r > 0 then
            return r
        end
    end
    return nil
end

local function loadRemoteModule(req, sessionId, hwid, keyStr, remotePath, localPath)
    if isfile and isfile(localPath) then
        local okR, src = pcall(readfile, localPath)
        if okR and type(src) == "string" and #src > 100 then
            local chunk = loadstring(src, "=" .. localPath)
            if chunk then
                local okC, mod = pcall(chunk)
                if okC and type(mod) == "table" then
                    return mod
                end
            end
        end
    end

    if not sessionId or not keyStr then return nil end

    local pathname = "/api/f/" .. remotePath
    local signedSearch = "?s=" .. tostring(sessionId)
    local headers = newSignedHeaders(sessionId, hwid, keyStr, "GET", pathname, signedSearch)

    local okH, hRes = pcall(req, {
        Url = RL .. "/f/" .. remotePath .. "?s=" .. tostring(sessionId)
            .. "&__route=script_proxy&__path=" .. tostring(remotePath),
        Method = "GET",
        Headers = headers,
    })
    if not okH or type(hRes) ~= "table" or tonumber(hRes.StatusCode) ~= 200
        or type(hRes.Body) ~= "string" or #hRes.Body < 100 then
        return nil
    end

    local src = hRes.Body
    local chunk, lerr = loadstring(src, "=" .. localPath)
    if not chunk then return nil end
    local okC, mod = pcall(chunk)
    if not okC or type(mod) ~= "table" then return nil end

    if writefile then pcall(writefile, localPath, src) end
    return mod
end

local function loadHashLib(req, sessionId, hwid, keyStr)
    if getgenv().__RAWR_HASHLIB then return getgenv().__RAWR_HASHLIB end
    local mod = loadRemoteModule(req, sessionId, hwid, keyStr,
        "private/librarys/hash.lua", "rawr_hashlib.lua")
    if mod and type(mod.aes_ctr_decrypt) == "function" then
        getgenv().__RAWR_HASHLIB = mod
        return mod
    end
    return nil
end

local function wrapDerSpki(rawPub)
    return string.char(
        0x30, 0x2a, 0x30, 0x05, 0x06, 0x03, 0x2b, 0x65, 0x6e, 0x03, 0x21, 0x00
    ) .. rawPub
end

local function unwrapDerSpki(derBin)
    if #derBin == 32 then return derBin end
    if #derBin == 44 and derBin:sub(1, 12) == string.char(
        0x30, 0x2a, 0x30, 0x05, 0x06, 0x03, 0x2b, 0x65, 0x6e, 0x03, 0x21, 0x00
    ) then
        return derBin:sub(13)
    end
    return nil
end

local hwid
if gethwid then
    local ok, h = pcall(gethwid)
    if ok and type(h) == "string" and #h > 0 then hwid = h end
end
if not hwid and syn and syn.get_hwid then
    local ok, h = pcall(syn.get_hwid)
    if ok and type(h) == "string" and #h > 0 then hwid = h end
end
if not hwid then
    hwid = HS:GenerateGUID(false) .. ":" .. tostring((PL and PL.UserId) or 0) .. ":" .. getExecutorName()
end

local req = (syn and syn.request) or (http and http.request) or request
if not req then kick("no request function") end

local X25519 = loadInlineX25519()

local clientPriv = X25519.randomPrivateKey()
local clientPubRaw = X25519.publicKey(clientPriv)
if not clientPriv or not clientPubRaw or #clientPubRaw ~= 32 then
    kick("x25519 keygen failed")
end
local clientPubDer = wrapDerSpki(clientPubRaw)
local clientPubB64 = binToB64(clientPubDer)

local needs = {"base", "render", "support", "addons", "sounds", "game:ttk", "game:tubbies", "game:arc"}

local ok, resp = pcall(req, {
    Url = RL .. "/session/init",
    Method = "POST",
    Headers = { ["Content-Type"] = "application/json" },
    Body = HS:JSONEncode({
        hwid = hwid,
        executor = getExecutorName(),
        placeId = game.PlaceId,
        jobId = game.JobId,
        userId = (PL and PL.UserId) or 0,
        userName = tostring((PL and PL.Name) or "?"),
        client_pub_b64 = clientPubB64,
        needs = needs,
    }),
})
if not ok or type(resp) ~= "table" then kick("session init failed") end
if tonumber(resp.StatusCode) ~= 200 then
    kick("session init HTTP " .. tostring(resp.StatusCode))
end

local okJson, sess = pcall(function() return HS:JSONDecode(resp.Body) end)
if not okJson or type(sess) ~= "table" or not sess.session_id or not sess.server_pub_b64 then
    kick("bad session response")
end

local serverPubRaw = unwrapDerSpki(b64ToBin(sess.server_pub_b64))
if not serverPubRaw or #serverPubRaw ~= 32 then
    kick("bad server pub")
end

local sharedSecret = X25519.x25519(clientPriv, serverPubRaw)
if type(sharedSecret) ~= "string" or #sharedSecret ~= 32 then
    kick("x25519 DH failed")
end

local keyStr = hkdfSha256(
    sharedSecret,
    hexDecode(sess.session_id),
    "rawr-session-v3",
    32
)
if type(keyStr) ~= "string" or #keyStr ~= 32 then
    kick("key derivation failed")
end

local loaderPathname = "/api/loader.enc"
local loaderSearch = "?s=" .. sess.session_id
local loaderHeaders = newSignedHeaders(sess.session_id, hwid, keyStr, "GET", loaderPathname, loaderSearch)

ok, resp = pcall(req, {
    Url = RL .. "/loader.enc?s=" .. sess.session_id,
    Method = "GET",
    Headers = loaderHeaders,
})
if not ok or type(resp) ~= "table" then kick("loader fetch failed") end
if tonumber(resp.StatusCode) ~= 200 then kick("loader fetch HTTP " .. tostring(resp.StatusCode)) end
if type(resp.Body) ~= "string" or #resp.Body < 100 then kick("loader empty") end

local okLoad, loadData = pcall(function() return HS:JSONDecode(resp.Body) end)
if not okLoad or type(loadData) ~= "table" then kick("loader not json") end
if not loadData.iv_b64 or not loadData.tag_hex or not loadData.ciphertext_b64 then
    kick("loader missing crypto fields")
end

local ivBin = b64ToBin(loadData.iv_b64)
local ctBin = b64ToBin(loadData.ciphertext_b64)
if type(ivBin) ~= "string" or #ivBin ~= 16 then kick("loader bad iv") end
if type(ctBin) ~= "string" or #ctBin == 0 then kick("loader bad ciphertext") end

local expectedTag = hmacHex(keyStr, ivBin .. ctBin)
if expectedTag ~= loadData.tag_hex then kick("loader hmac mismatch") end

local loaderSource
local dec = (syn and syn.crypt and syn.crypt.decrypt) or (crypt and crypt.decrypt)

if dec then
    local keyB64 = binToB64(keyStr)
    loaderSource = ctrDecrypt(dec, loadData.ciphertext_b64, keyB64, loadData.iv_b64)
end

if loaderSource then
    local head = loaderSource:sub(1, 20)
    if not head:match("^%s*%-%-") and not head:match("^%s*local") and not head:match("^%s*return") then
        loaderSource = nil -- decrypt failed or returned garbage
    end
end

if not loaderSource then
    local HashLib = loadHashLib(req, sess.session_id, hwid, keyStr)
    if not HashLib then kick("decrypt failed (no native AES-CTR, hash.lua missing)") end
    loaderSource = HashLib.aes_ctr_decrypt(keyStr, ivBin, ctBin)
    if type(loaderSource) ~= "string" or #loaderSource == 0 then kick("hash.lua decrypt failed") end
end

getgenv().__RAWR_SESSION = {
    session_id = sess.session_id,
    session_key_hex = (function()
        local o = {}
        for i = 1, #keyStr do o[i] = string.format("%02x", keyStr:byte(i)) end
        return table.concat(o)
    end)(),
    session_key_str = keyStr,
    server_pub_b64 = sess.server_pub_b64,
    expires = os.time() + math.floor(((sess.expires_at or 0) - DateTime.now().UnixTimestampMillis) / 1000),
    hwid = hwid,
}

local chunk, lerr = loadstring(loaderSource)
if not chunk then kick("loader compile: " .. tostring(lerr)) end

local okRun, runErr = pcall(chunk)
if not okRun then
    warn("[Rawr] loader runtime: " .. tostring(runErr))
end
]==]

