_104.hitNotifyLastHealth = {}
_104.hitNotifyLastArmor = {}
_104.hitNotifySeenTarget = nil
_104._armorCache = _104._armorCache or setmetatable({}, { __mode = "k" })

function _104:GetTargetArmorValue(target)
    if not target or not target.Character then return nil end
    local c = self._armorCache[target]
    if c and c.char == target.Character and c.armor and c.armor.Parent then
        return c.armor.Value
    end
    local char = target.Character
    local be = char:FindFirstChild("BodyEffects") or char:FindFirstChild("Character")
    if not be then return nil end
    local armor = be:FindFirstChild("Armor") or be:FindFirstChild("Armour") or be:FindFirstChild("Vest")
    self._armorCache[target] = { char = char, armor = armor }
    return armor and armor.Value or nil
end

