_SoundService = game:GetService("SoundService")
_SoundCache = {}
_SoundKeyMap = {}
_SOUND_DIR = "woodie/assets/sounds"

for k in pairs(SoundRegistry) do
    _SoundKeyMap[k:lower()] = k
end

local function _ensureDir()
    for _, folder in ipairs({ "woodie", "woodie/assets", "woodie/assets/sounds" }) do
        pcall(function()
            if isfolder and not isfolder(folder) then
                makefolder(folder)
            end
        end)
    end
end

function fetchAsset(path)
    if type(fetchScript) ~= "function" then
        warn("[Loader/sound] fetchScript not available")
        return nil
    end
    local data = fetchScript(path)
    if type(data) ~= "string" or #data == 0 then
        warn("[Loader/sound] fetch failed for " .. tostring(path))
        return nil
    end
    return data
end

function GetSoundAsset(filename)
    if _SoundCache[filename] then return _SoundCache[filename] end

    _ensureDir()

    local filePath = _SOUND_DIR .. "/" .. tostring(filename)
    local exists = false
    pcall(function()
        if isfile and isfile(filePath) then
            local ok, data = pcall(readfile, filePath)
            exists = ok and type(data) == "string" and #data > 0
        end
    end)

    if not exists then
        local bytes = fetchAsset("assets/sounds/" .. tostring(filename))
        if not bytes then
            warn("[Loader/sound] fetch failed for " .. tostring(filename))
            return nil
        end
        local ok, writeErr = pcall(function()
            writefile(filePath, bytes)
        end)
        if not ok then
            warn("[rawr/sound] writefile failed for " .. tostring(filename) .. ": " .. tostring(writeErr))
            return nil
        end
    end

    local ok2, asset = pcall(getcustomasset, filePath)
    if ok2 and asset then
        _SoundCache[filename] = asset
        return asset
    end
    warn("[rawr/sound] getcustomasset failed for " .. tostring(filePath))
    return nil
end

function _resolveSoundName(soundName)
    if not soundName then return nil end
    if SoundRegistry[soundName] then return soundName end
    local realKey = _SoundKeyMap[tostring(soundName):lower()]
    if realKey then return realKey end
    return nil
end

function PlaySoundByName(soundName, volume)
    if not soundName or soundName == "None" then return end

    local resolved = _resolveSoundName(soundName)
    if not resolved then
        warn("[rawr/sound] unknown sound name: " .. tostring(soundName))
        return
    end

    local filename = SoundRegistry[resolved]
    if not filename then return end

    local asset = GetSoundAsset(filename)
    if not asset then return end

    local s = Instance.new("Sound")
    s.SoundId = asset
    s.Volume = math.clamp((volume or 50) / 100 * 2.5, 0, 3)
    s.Parent = _SoundService
    s:Play()

    task.delay(10, function()
        pcall(function() s:Destroy() end)
    end)
end

function PlayHitSound()
    if not Toggles or not Toggles.HitSoundEnabled or not Toggles.HitSoundEnabled.Value then return end
    PlaySoundByName(Options.HitSoundType.Value, Options.HitSoundVolume.Value)
end

function PlayKillSound()
    if not Toggles or not Toggles.KillSoundEnabled or not Toggles.KillSoundEnabled.Value then return end
    PlaySoundByName(Options.KillSoundType.Value, Options.KillSoundVolume.Value)
end

KillTracker = {
    lastTarget = nil,
    firedFor = {},
}

function UpdateKillSound(target)
    if not target then
        KillTracker.lastTarget = nil
        return
    end

    local userId = target.UserId
    if KillTracker.firedFor[userId] then
        KillTracker.lastTarget = target
        return
    end

    local char = target.Character
    if not char then
        KillTracker.firedFor[userId] = true
        PlayKillSound()
        KillTracker.lastTarget = nil
        return
    end

    local be = char:FindFirstChild("BodyEffects")
    if not be then
        KillTracker.lastTarget = target
        return
    end

    local dead = be:FindFirstChild("Dead")
    if dead and dead.Value == true then
        KillTracker.firedFor[userId] = true
        PlayKillSound()
        KillTracker.lastTarget = nil
        return
    end

    KillTracker.lastTarget = target
end

do
    local _autoDone = false

    function _autoCleanup()
        _autoDone = nil
        _autoCleanup = nil
        _autoDownload = nil
        _autoQueue = nil
    end

    function _autoDownload()
        if _autoDone or type(fetchScript) ~= "function" then return end
        _autoDone = true

        warn("[Rawr] Download started, " .. tostring(#SoundRegistry) .. " registry entries")

        _ensureDir()

        local queue = {}
        for _, filename in pairs(SoundRegistry) do
            if type(filename) == "string" and #filename > 0 then
                queue[#queue + 1] = filename
            end
        end
        _autoQueue = queue

        task.spawn(function()
            for i = 1, #queue do
                local filename = queue[i]
                local filePath = _SOUND_DIR .. "/" .. filename
                local exists = false
                pcall(function()
                    if isfile and isfile(filePath) then
                        local ok, data = pcall(readfile, filePath)
                        exists = ok and type(data) == "string" and #data > 0
                    end
                end)
                if not exists then
                    local bytes = fetchAsset("assets/sounds/" .. filename)
                    if bytes then
                        pcall(writefile, filePath, bytes)
                    else
                        warn("[dbg] " .. filename .. " -> fetch returned nil")
                    end
                end
                if i % 4 == 0 then task.wait() end
            end
            queue = nil
            _autoCleanup()
        end)
    end

    task.spawn(function()
        local t0 = tick()
        while tick() - t0 < 15 do
            if type(fetchScript) == "function" and getgenv().__RAWR_SESSION then
                pcall(_autoDownload)
                return
            end
            task.wait(0.25)
        end
        warn("[Rawr] download never worked: fs or session missing after 15s")
    end)
end

