KO_FLAG_NAMES   = {"K.O", "KO", "Knocked", "KnockedOut", "Stunned"}
DEAD_FLAG_NAMES = {"Dead", "Killed", "Lifeless"}

function FindMainRemote()
    local ReplicatedStorage = game:GetService("ReplicatedStorage")
    local paths = {
        {"GameRemotes", "MainGameEvent"},
        {"MainRemotes", "MainRemoteEvent"},
        {"Remotes", "MainRemoteEvent"},
        {"MainEvent"},
    }
    for _, path in ipairs(paths) do
        local current = ReplicatedStorage
        local found = true
        for i = 1, #path do
            current = current:FindFirstChild(path[i])
            if not current then found = false; break end
        end
        if found and current then return current end
    end
    return nil
end

function HasAnyFlag(container, names)
    if not container then return false end
    for i = 1, #names do
        local f = container:FindFirstChild(names[i])
        if f and f.Value == true then return true end
    end
    return false
end

function GetBodyEffects(target)
    if not target or not target.Character then return nil end
    return target.Character:FindFirstChild("BodyEffects") or target.Character:FindFirstChild("Character")
end

function findSafeReturnPosition(originalPos)
    local selfChar = _56.Character

    if not originalPos or typeof(originalPos) ~= "Vector3" then
        originalPos = LastRealSelfCFrame and LastRealSelfCFrame.Position
            or (selfChar and selfChar:FindFirstChild("HumanoidRootPart") and selfChar.HumanoidRootPart.Position)
            or Vector3.new(0, 100, 0)
    end

    local function isVoid(pos)
        if not pos then return true end
        if pos.X ~= pos.X or pos.Y ~= pos.Y or pos.Z ~= pos.Z then return true end
        if math.abs(pos.X) > 500000000 or math.abs(pos.Y) > 500000000 or math.abs(pos.Z) > 500000000 then return true end
        local fpdh = workspace.FallenPartsDestroyHeight
        if fpdh and pos.Y < fpdh + 20 then return true end
        if pos.Y < -500 then return true end
        return false
    end

    local rp = RaycastParams.new()
    rp.FilterType = Enum.RaycastFilterType.Exclude
    rp.FilterDescendantsInstances = selfChar and { selfChar } or {}

    local function groundAt(pos)
        if isVoid(pos) then return nil end
        local hit = workspace:Raycast(pos + Vector3.new(0, 5, 0), Vector3.new(0, -200, 0), rp)
        if not hit then return nil end
        local result = hit.Position + Vector3.new(0, 3, 0)
        if isVoid(result) then return nil end
        return CFrame.new(result)
    end

    if not isVoid(originalPos) then
        local g = groundAt(originalPos)
        if g then return g end
    end

    if LastRealSelfCFrame and not isVoid(LastRealSelfCFrame.Position) then
        local g = groundAt(LastRealSelfCFrame.Position)
        if g then return g end
    end

    if ReturnSet and ReturnCFrame and not isVoid(ReturnCFrame.Position) then
        local g = groundAt(ReturnCFrame.Position)
        if g then return g end
    end

    local offsets = {
        Vector3.new(0, 0, 0),
        Vector3.new(0, 5, 0),
        Vector3.new(5, 0, 0),
        Vector3.new(-5, 0, 0),
        Vector3.new(0, 0, 5),
        Vector3.new(0, 0, -5),
        Vector3.new(5, 5, 0),
        Vector3.new(-5, 5, 0),
        Vector3.new(0, 5, 5),
        Vector3.new(0, 5, -5),
        Vector3.new(0, 10, 0),
        Vector3.new(10, 0, 0),
        Vector3.new(-10, 0, 0),
        Vector3.new(0, 0, 10),
        Vector3.new(0, 0, -10),
    }

    for _, offset in ipairs(offsets) do
        local checkPos = originalPos + offset
        if not isVoid(checkPos) then
            local hit = workspace:Raycast(checkPos + Vector3.new(0, 20, 0), Vector3.new(0, -200, 0), rp)
            if hit and not isVoid(hit.Position) then
                return CFrame.new(hit.Position + Vector3.new(0, 3, 0))
            end
        end
    end

    local spawn = workspace:FindFirstChildOfClass("SpawnLocation")
    if spawn and not isVoid(spawn.Position) then
        return CFrame.new(spawn.Position + Vector3.new(0, 5, 0))
    end

    local char = _56.Character
    if char then
        local hrp = char:FindFirstChild("HumanoidRootPart")
        if hrp and not isVoid(hrp.Position) then
            local g = groundAt(hrp.Position)
            if g then return g end
        end
    end

    return CFrame.new(Vector3.new(0, 100, 0))
end

local PhysicsRepRootRefTable = setmetatable({}, { __mode = "k" })
local InstanceHandleClass = getrenv and getrenv().InstanceHandle
local hasInstanceHandle = InstanceHandleClass ~= nil

if type(sethiddenproperty) == "function" then
    local originalSetHiddenProperty = sethiddenproperty
    sethiddenproperty = function(part, property, value, ...)
        if property == "PhysicsRepRootPart" then
            PhysicsRepRootRefTable[part] = value
            if hasInstanceHandle then
                if value ~= nil then
                    pcall(originalSetHiddenProperty, part, "PhysicsRepRootRef", InstanceHandleClass.new(value))
                else
                    pcall(originalSetHiddenProperty, part, "PhysicsRepRootRef", nil)
                end
            end
        end
        return originalSetHiddenProperty(part, property, value, ...)
    end
end

do
    stomping = stomping or false
    grabbing = grabbing or false
    stompConnection = nil
    stompRemote = nil
    StompReturnLocked = false
    StompStartTime = 0
    StompMode = "direct"
    StompLockTarget = nil
    StompLockChar = nil
    STOMP_MAX_DURATION = 10

    StompToggle:OnChanged(function(value)
        StompEnabled = value
        if not value and stompConnection then
            stompConnection:Disconnect()
            stompConnection = nil
            stomping = false
            StompStartTime = 0
            if sethiddenproperty then
                local char = _56.Character
                local hum = char and char:FindFirstChildOfClass('Humanoid')
                local root = hum and hum.RootPart
                if root then
                    pcall(function() sethiddenproperty(root, "PhysicsRepRootPart", nil) end)
                end
            end
        end
    end)

    StompModeDropdown:OnChanged(function(value)
        if type(value) == "table" then value = value[1] end
        StompMode = value or "direct"
    end)

    function CheckStompLockClear()
        if not StompLockTarget then return end
        if not StompLockTarget.Parent
            or not StompLockTarget.Character
            or StompLockTarget.Character ~= StompLockChar then
            StompLockTarget = nil
            StompLockChar = nil
            return
        end
        local koOK,   koVal   = pcall(IsTargetKO,      StompLockTarget)
        local deadOK, deadVal = pcall(IsTargetDeadFlag, StompLockTarget)
        if deadOK and deadVal then
            StompLockTarget = nil
            StompLockChar = nil
            return
        end
        if koOK and deadOK and not koVal and not deadVal then
            StompLockTarget = nil
            StompLockChar = nil
        end
    end

    function getStompRemote()
        if stompRemote and stompRemote.Parent then return stompRemote end
        stompRemote = FindMainRemote()
        return stompRemote
    end

    function fireStomp()
        local remote = getStompRemote()
        if not remote then return end
        pcall(function() remote:FireServer("Stomp") end)
    end

    function getBestStompPosition(targetChar)
        local parts = {"UpperTorso", "Torso", "HumanoidRootPart", "LowerTorso", "Head"}
        for _, partName in ipairs(parts) do
            local part = targetChar:FindFirstChild(partName)
            if part and part:IsA("BasePart") then return part end
        end
        return nil
    end

    function getStompCFrame(targetPart)
        if not targetPart or not targetPart.Parent then return nil end
        if StompMode == "vector" then
            return CFrame.new(targetPart.Position + Vector3.new(0, 2.1, 0))
        end
        return targetPart.CFrame
    end

    function applyPhysicsRep(part, targetPart)
        if sethiddenproperty and part and targetPart then
            pcall(function() sethiddenproperty(part, "PhysicsRepRootPart", targetPart) end)
        end
    end

    function clearPhysicsRep(part)
        if sethiddenproperty and part then
            pcall(function() sethiddenproperty(part, "PhysicsRepRootPart", nil) end)
        end
    end

    function autoStompTarget()
        if not StompEnabled then return end
        if _118 then return end
        if stomping then return end
        if _AA_busy then return end

        CheckStompLockClear()

        local target = _104.targetplayer
        if not target or not target.Parent then return end
        if not target.Character or not target.Character.Parent then return end

        local targetChar = target.Character
        local BodyEffects = targetChar:FindFirstChild("BodyEffects")
        if not BodyEffects then return end

        local KOCheck = BodyEffects:FindFirstChild("K.O")
        if not KOCheck or KOCheck.Value ~= true then return end

        local grabbedNow = false
        pcall(function() grabbedNow = Grabbed(target) == true end)
        if grabbedNow then return end

        if IsTargetDeadFlag(target) then return end
        if StompLockTarget == target and StompLockChar == targetChar then return end
        if IdleState == "hiding" and (IdleReason == "reload" or IdleReason == "spam") then return end

        local localChar = _56.Character
        if not localChar then return end
        local localHRP = localChar:FindFirstChild("HumanoidRootPart")
        if not localHRP then return end
        local localHum = localChar:FindFirstChildOfClass("Humanoid")

        local targetPart = getBestStompPosition(targetChar)
        if not targetPart then return end

        local returnCF = nil
        if LastRealSelfCFrame and not IsVoidPosition(LastRealSelfCFrame.Position) then
            returnCF = LastRealSelfCFrame
        elseif ReturnSet and ReturnCFrame and not IsVoidPosition(ReturnCFrame.Position) then
            returnCF = ReturnCFrame
        end

        if not returnCF then
            local groundCheck = findSafeReturnPosition(localHRP.Position)
            if groundCheck then returnCF = groundCheck end
        end

        StompLockTarget = target
        StompLockChar = targetChar

        stomping = true
        StompStartTime = os.clock()
        local finished = false
        local stompFires = 0
        local STOMP_MAX_FIRES = 600

        local function finishStomp(success)
            if finished then return end
            finished = true
            pcall(function()
                stomping = false
                StompStartTime = 0
                if stompConnection then
                    stompConnection:Disconnect()
                    stompConnection = nil
                end
                if sethiddenproperty and localChar then
                    local hum = localChar:FindFirstChildOfClass("Humanoid")
                    local root = hum and hum.RootPart
                    if root then
                        clearPhysicsRep(root)
                    end
                end
                if not StompReturnLocked and not Restoring then
                    if localHRP and localHRP.Parent then
                        local safeReturn
                        if returnCF and not IsVoidPosition(returnCF.Position) then
                            safeReturn = findSafeReturnPosition(returnCF.Position)
                        else
                            safeReturn = findSafeReturnPosition(localHRP.Position)
                        end
                        if safeReturn then
                            localHRP.CFrame = safeReturn
                            localHRP.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
                            localHRP.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
                        end
                    end
                end
            end)
        end

        localHRP.Anchored = false
        pcall(function()
            localHRP:SetNetworkOwner(_56)
            targetPart:SetNetworkOwner(_56)
        end)

        applyPhysicsRep(localHum and localHum.RootPart, targetPart)

        localHRP.CFrame = getStompCFrame(targetPart) or targetPart.CFrame
        localHRP.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
        localHRP.AssemblyAngularVelocity = Vector3.new(0, 0, 0)

        for i = 1, 10 do fireStomp() end
        stompFires = 10

        if stompConnection then stompConnection:Disconnect() end
        stompConnection = _52.RenderStepped:Connect(function()
            if not stomping then
                if stompConnection then
                    stompConnection:Disconnect()
                    stompConnection = nil
                end
                return
            end

            if os.clock() - StompStartTime > STOMP_MAX_DURATION then
                finishStomp(false); return
            end
            if not target or not target.Parent or not target.Character or target.Character ~= targetChar then
                finishStomp(false); return
            end
            if not targetChar or not targetChar.Parent then
                finishStomp(false); return
            end
            local beNow = targetChar:FindFirstChild("BodyEffects")
            if not beNow then finishStomp(false); return end

            local deadNow = beNow:FindFirstChild("Dead")
            if deadNow and deadNow.Value == true then
                finishStomp(true); return
            end
            local targetHum = targetChar:FindFirstChildOfClass("Humanoid")
            if targetHum and targetHum.Health <= 0 then
                finishStomp(true); return
            end

            local koNow = beNow:FindFirstChild("K.O")
            if not koNow or koNow.Value ~= true then
                finishStomp(false); return
            end

            if not localHRP or not localHRP.Parent then
                finishStomp(false); return end

            local currentTargetPart = getBestStompPosition(targetChar)
            if not currentTargetPart then finishStomp(false); return end

            local preferredPart = PhysicsRepRootRefTable[localHum and localHum.RootPart]
            local usePart = (preferredPart and preferredPart.Parent and preferredPart:IsA("BasePart")) and preferredPart or currentTargetPart

            applyPhysicsRep(localHum and localHum.RootPart, usePart)

            localHRP.CFrame = getStompCFrame(usePart) or usePart.CFrame
            localHRP.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
            localHRP.AssemblyAngularVelocity = Vector3.new(0, 0, 0)

            if stompFires < STOMP_MAX_FIRES then
                fireStomp()
                stompFires = stompFires + 1
            end
        end)
    end
end

-- grab

do
    GrabbingEnabled = false
    grabbing = grabbing or false
    GrabConnection = nil
    GrabRemote = nil
    GrabStartTime = 0
    GrabLastFire = 0
    GRAB_FIRE_INTERVAL = 0.8

    GrabToggle:OnChanged(function(value)
        GrabbingEnabled = value
        if not value and GrabConnection then
            GrabConnection:Disconnect()
            GrabConnection = nil
            grabbing = false
            GrabStartTime = 0
            GrabLastFire = 0
        end
    end)

    function getGrabRemote()
        if GrabRemote and GrabRemote.Parent then
            return GrabRemote
        end
        local replicatedStorage = game:GetService("ReplicatedStorage")
        local mainRemotes = replicatedStorage:FindFirstChild("MainRemotes")
        if mainRemotes then
            local m = mainRemotes:FindFirstChild("MainRemoteEvent")
            if m then GrabRemote = m; return m end
        end
        return nil
    end

    function fireGrab(grabbing_state)
        local remote = getGrabRemote()
        if not remote then return end
        pcall(function() remote:FireServer("Grabbing", grabbing_state) end)
    end

    function getGrabCFrame(targetPart)
        if not targetPart or not targetPart.Parent then return nil end
        return CFrame.new(targetPart.Position + Vector3.new(0, 2.1, 0))
    end

    function autoGrabTarget()
        if not GrabbingEnabled then return end
        if _118 then return end
        if grabbing then return end
        if stomping then return end
        if _AA_busy then return end
        if IdleState ~= "none" then return end
        if Restoring then return end

        local target = _104.targetplayer
        if not target then return end
        local targetChar = target.Character
        if not targetChar then return end
        if Grabbed(target) then return end

        local BodyEffects = targetChar:FindFirstChild("BodyEffects")
        if not BodyEffects then return end
        local KOCheck = BodyEffects:FindFirstChild("K.O")
        if not KOCheck or KOCheck.Value ~= true then return end

        local localChar = _56.Character
        if not localChar then return end
        local localHRP = localChar:FindFirstChild("HumanoidRootPart")
        if not localHRP then return end

        local targetPart = getBestStompPosition(targetChar)
        if not targetPart then return end

        local lastpos = localHRP.CFrame
        if IsVoidPosition(lastpos.Position) then
            if LastRealSelfCFrame and not IsVoidPosition(LastRealSelfCFrame.Position) then
                lastpos = LastRealSelfCFrame
            elseif ReturnSet and ReturnCFrame and not IsVoidPosition(ReturnCFrame.Position) then
                lastpos = ReturnCFrame
            else
                lastpos = findSafeReturnPosition(localHRP.Position) or CFrame.new(0, 100, 0)
            end
        end

        local function grabRelease(returnToPos)
            grabbing = false
            GrabStartTime = 0
            GrabLastFire = 0
            if GrabConnection then
                GrabConnection:Disconnect()
                GrabConnection = nil
            end
            pcall(function() fireGrab(false) end)
            if StompReturnLocked or Restoring or IdleState ~= "none" then return end
            if not localHRP or not localHRP.Parent then return end
            local safeReturn = findSafeReturnPosition(returnToPos and returnToPos.Position or lastpos.Position)
            if safeReturn then
                localHRP.CFrame = safeReturn
                localHRP.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
                localHRP.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
            end
        end

        grabbing = true
        GrabStartTime = tick()

        localHRP.Anchored = false
        pcall(function()
            localHRP:SetNetworkOwner(_56)
            targetPart:SetNetworkOwner(_56)
        end)

        localHRP.CFrame = getGrabCFrame(targetPart)
        localHRP.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
        localHRP.AssemblyAngularVelocity = Vector3.new(0, 0, 0)

        for i = 1, 20 do
            fireGrab(true)
        end
        GrabLastFire = tick()

        if GrabConnection then GrabConnection:Disconnect() end
        GrabConnection = _52.RenderStepped:Connect(function()
            if not grabbing then
                if GrabConnection then
                    GrabConnection:Disconnect()
                    GrabConnection = nil
                end
                return
            end

            local beNow = targetChar and targetChar.Parent and targetChar:FindFirstChild("BodyEffects")
            local koNow = beNow and beNow:FindFirstChild("K.O")
            if not koNow or koNow.Value ~= true then
                grabRelease(lastpos)
                return
            end

            local currentTargetPart = getBestStompPosition(targetChar)
            if not currentTargetPart then
                grabRelease(lastpos)
                return
            end

            localHRP.CFrame = getGrabCFrame(currentTargetPart)
            localHRP.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
            localHRP.AssemblyAngularVelocity = Vector3.new(0, 0, 0)

            local now = tick()
            if now - GrabLastFire >= GRAB_FIRE_INTERVAL then
                GrabLastFire = now
                fireGrab(true)
            end
        end)

        task.delay(0.5, function()
            if grabbing then
                grabRelease(lastpos)
            end
        end)
    end
end

StompGrabConn = _52.RenderStepped:Connect(function()
    if not _104.active or not _104.targetplayer then return end
    local target = _104.targetplayer
    if not (target and target.Character and target.Character:FindFirstChild("Humanoid")) then return end
    if StompEnabled and not stomping and not grabbing then pcall(autoStompTarget) end
    if GrabbingEnabled and not grabbing and not stomping then pcall(autoGrabTarget) end
end)

