resolverLastRun = 0
resolvedPredictedPos = nil
resolvedAimPoint = nil
resolvedAnchorCF = nil
LastAimPoint = nil
LastAimLead = nil
LastAimState = nil

SnapEnabled    = false
SnapHoldTime   = 0.5
SnapOrbitTime  = 2.0
SnapPhase      = "off"
SnapPhaseUntil = 0
SnapWelded     = false
SnapPushSpeed  = 75

PullEnabled      = false
