PullStrafeAmp    = 4
PullStrafeRate   = 2.5

PullTargetHRP    = nil
PullSavedAnchor  = nil
PullStrafePhase  = 0
PullLastShot     = 0

PositionSourceWeights = {
    HumanoidRootPart = 1.00, UpperTorso = 0.95, LowerTorso = 0.90,
    Torso = 0.85, Head = 0.80, LeftUpperArm = 0.50, RightUpperArm = 0.50,
    LeftHand = 0.35, RightHand = 0.35, LeftUpperLeg = 0.45, RightUpperLeg = 0.45,
    LeftFoot = 0.25, RightFoot = 0.25,
}

OUTLIER_THRESHOLD    = 15
AnchorSmoothRate     = 0.55
AnchorSmoothRateFast = 0.85
AnchorFastMoveDist   = 25
LastAnchorPos        = nil
LastAnchorLook       = nil

ResolverEnabled        = false
ResolverMode           = "velocity"
ResolverSmoothing      = 0.55
ResolverMaxSpeed       = 250
ResolverAccelSmoothing = 0.35
ResolverMaxAccel       = 750
ResolverStates         = {}

ClusterStates              = {}
ClusterSampleInterval      = 0.016
ClusterHistorySize         = 32
ClusterMinSamples          = 8
ClusterBinCount            = 12
ClusterDecayRate           = 0.9
ClusterPeakThreshold       = 0.30
ClusterRecencyHalfLife     = 8
ClusterGroundedWeight      = 0.6
ClusterAirborneWeight      = 0.25
ClusterConfidentBonus      = 0.15
ClusterLookSmooth          = 0.55

ClusterTasks = {}
ClusterTaskClock = 0

TAU = 6.28318530718

InstanceHandle    = InstanceHandle or (getrenv and getrenv().InstanceHandle)
_snapHandleCache  = _snapHandleCache or setmetatable({}, { __mode = "k" })

function _snapRefOf(part)
    if not part then return nil end
    local h = _snapHandleCache[part]
    if h then return h end
    if InstanceHandle and InstanceHandle.new then
        local ok, ref = pcall(InstanceHandle.new, part)
        if ok and ref then
            _snapHandleCache[part] = ref
            return ref
        end
    end
    return nil
end

function _snapSetPart(hrp, targetHRP)
    if not sethiddenproperty or not hrp then return false end
    return pcall(sethiddenproperty, hrp, "PhysicsRepRootPart", targetHRP)
end

function _snapSetRef(hrp, targetHRP)
    if not sethiddenproperty or not hrp then return false end
    local ref = _snapRefOf(targetHRP)
    if not ref then return false end
    return pcall(sethiddenproperty, hrp, "PhysicsRepRootRef", ref)
end

function _snapClear(hrp)
    if not sethiddenproperty or not hrp then return end
    pcall(sethiddenproperty, hrp, "PhysicsRepRootPart", nil)
    pcall(sethiddenproperty, hrp, "PhysicsRepRootRef", nil)
end

function _snapApply(hrp, targetHRP)
    if not sethiddenproperty or not hrp or not targetHRP then return false end
    _snapSetPart(hrp, targetHRP)
    _snapSetRef(hrp, targetHRP)
    return true
end

function RegisterClusterTask(name, interval, fn)
    ClusterTasks[name] = {
        interval = interval,
        nextRun = 0,
        fn = fn,
        lastRun = 0,
    }
end

function RunClusterTasks(target, hrp, now)
    for name, task in pairs(ClusterTasks) do
        if now >= task.nextRun then
            task.nextRun = now + task.interval
            local ok = pcall(task.fn, target, hrp, now)
            if ok then task.lastRun = now end
        end
    end
end

function ResolverUpdate(target, pos)
    if not ResolverEnabled or not target then return pos end
    local now = os.clock()
    local st = ResolverStates[target]
    if not st then
        ResolverStates[target] = {
            lastPos = pos, lastTime = now, velocity = Vector3.new(),
            prevVelocity = Vector3.new(), accel = Vector3.new(),
        }
        return pos
    end
    local dt = now - st.lastTime
    if dt > 0.0005 and dt < 0.5 then
        local invDt = 1 / dt
        local instVel = (pos - st.lastPos) * invDt
        local speed = instVel.Magnitude
        if speed > ResolverMaxSpeed then instVel = instVel * (ResolverMaxSpeed / speed) end
        st.velocity = st.velocity:Lerp(instVel, ResolverSmoothing)
        local instAccel = (st.velocity - st.prevVelocity) * invDt
        local accelMag = instAccel.Magnitude
        if accelMag > ResolverMaxAccel then instAccel = instAccel * (ResolverMaxAccel / accelMag) end
        st.accel = st.accel:Lerp(instAccel, ResolverAccelSmoothing)
        st.prevVelocity = st.velocity
    end
    st.lastPos = pos
    st.lastTime = now
    return pos
end

function ResolverGetVelocity(target)
    if not ResolverEnabled then return Vector3.new() end
    if ResolverMode == "cluster" then
        return ClusterGetVelocity(target)
    end
    local st = ResolverStates[target]
    return st and st.velocity or Vector3.new()
end

function ResolverGetAcceleration(target)
    if not ResolverEnabled then return Vector3.new() end
    if ResolverMode == "cluster" then
        return ClusterGetAcceleration(target)
    end
    local st = ResolverStates[target]
    return st and st.accel or Vector3.new()
end

function ClusterGetOrCreate(target)
    local st = ClusterStates[target]
    if st then return st end
    st = {
        yawSamples = {},
        yawHead = 0,
        yawCount = 0,
        realYaw = 0,
        yawConfidence = 0,
        yawSpinRate = 0,
        pitchSamples = {},
        pitchHead = 0,
        pitchCount = 0,
        realPitch = 0,
        pitchConfidence = 0,
        posSamples = {},
        posHead = 0,
        posCount = 0,
        velocity = Vector3.new(),
        prevVelocity = Vector3.new(),
        accel = Vector3.new(),
        strafeBias = 0,
        movementMode = "idle",
        grounded = true,
        stateType = nil,
        lastPos = nil,
        lastTime = 0,
        lastSampleTime = 0,
        confidence = 0,
        stablePos = nil,
        spoofScore = 0,
        lockedYaw = 0,
        quatDelta = 0,
        lastQuat = nil,
    }
    ClusterStates[target] = st
    return st
end

function ClusterGetVelocity(target)
    local st = ClusterStates[target]
    return st and st.velocity or Vector3.new()
end

function ClusterGetAcceleration(target)
    local st = ClusterStates[target]
    return st and st.accel or Vector3.new()
end

RegisterClusterTask("yaw", 0.016, function(target, hrp, now)
    local st = ClusterGetOrCreate(target)
    local look = hrp.CFrame.LookVector
    local yaw = math.atan2(-look.X, -look.Z)
    local pitch = math.asin(math.clamp(look.Y, -1, 1))

    st.yawHead = (st.yawHead % ClusterHistorySize) + 1
    st.yawSamples[st.yawHead] = yaw
    if st.yawCount < ClusterHistorySize then st.yawCount = st.yawCount + 1 end

    st.pitchHead = (st.pitchHead % ClusterHistorySize) + 1
    st.pitchSamples[st.pitchHead] = pitch
    if st.pitchCount < ClusterHistorySize then st.pitchCount = st.pitchCount + 1 end

    st.lastSampleTime = now
end)

RegisterClusterTask("movement", 0.033, function(target, hrp, now)
    local st = ClusterGetOrCreate(target)
    local pos = hrp.Position
    if st.lastPos and st.lastTime > 0 then
        local dt = now - st.lastTime
        if dt > 0.001 and dt < 0.5 then
            local instVel = (pos - st.lastPos) / dt
            local speed = instVel.Magnitude
            if speed > ResolverMaxSpeed then
                instVel = instVel * (ResolverMaxSpeed / speed)
            end

            local w = st.grounded and ClusterGroundedWeight or ClusterAirborneWeight
            if st.yawConfidence >= ClusterPeakThreshold then
                w = math.min(w + ClusterConfidentBonus, 0.9)
            end
            st.velocity = st.velocity:Lerp(instVel, w)

            local instAccel = (st.velocity - st.prevVelocity) / dt
            local aMag = instAccel.Magnitude
            if aMag > ResolverMaxAccel then
                instAccel = instAccel * (ResolverMaxAccel / aMag)
            end
            st.accel = st.accel:Lerp(instAccel, ResolverAccelSmoothing)
            st.prevVelocity = st.velocity

            local right = hrp.CFrame.RightVector
            st.strafeBias = right:Dot(st.velocity)
        end
    end
    st.lastPos = pos
    st.lastTime = now
end)

RegisterClusterTask("state", 0.1, function(target, hrp, now)
    local st = ClusterGetOrCreate(target)
    local hum = hrp.Parent:FindFirstChildOfClass("Humanoid")
    if hum then
        st.stateType = hum:GetState()
        st.grounded = (st.stateType == Enum.HumanoidStateType.Running
                    or st.stateType == Enum.HumanoidStateType.RunningNoPhysics
                    or st.stateType == Enum.HumanoidStateType.Landed
                    or st.stateType == Enum.HumanoidStateType.Climbing)
    end
end)

RegisterClusterTask("quat", 0.016, function(target, hrp, now)
    local st = ClusterGetOrCreate(target)
    local cf = hrp.CFrame
    local x, y, z, w = cf:ToQuaternion()
    if st.lastQuat then
        local lx, ly, lz, lw = st.lastQuat[1], st.lastQuat[2], st.lastQuat[3], st.lastQuat[4]
        local dot = x*lx + y*ly + z*lz + w*lw
        if dot < 0 then dot = -dot end
        local angle = 2 * math.acos(math.clamp(dot, -1, 1))
        st.quatDelta = angle
        if angle > 1.0 then st.spoofScore = math.min(st.spoofScore + 0.3, 1) end
    end
    st.lastQuat = {x, y, z, w}
end)

RegisterClusterTask("cluster", 0.05, function(target, hrp, now)
    local st = ClusterGetOrCreate(target)
    if st.yawCount < ClusterMinSamples then return end

    local bins = {}
    for i = 1, ClusterBinCount do bins[i] = 0 end
    local twoPi = math.pi * 2
    for i = 1, st.yawCount do
        local y = st.yawSamples[i]
        if y then
            local norm = (y % twoPi + twoPi) % twoPi
            local idx = math.floor(norm / twoPi * ClusterBinCount) + 1
            idx = math.clamp(idx, 1, ClusterBinCount)
            local age = (st.yawHead - i) % ClusterHistorySize
            bins[idx] = bins[idx] + math.exp(-age / ClusterRecencyHalfLife)
        end
    end

    local total, peakIdx, peakW = 0, 1, 0
    for i = 1, ClusterBinCount do
        total = total + bins[i]
        if bins[i] > peakW then peakIdx, peakW = i, bins[i] end
    end
    if total <= 0 then return end

    st.yawConfidence = peakW / total

    local wsum, ysum = 0, 0
    for di = -1, 1 do
        local i = ((peakIdx + di - 1) % ClusterBinCount) + 1
        local w = bins[i]
        local center = (i - 0.5) / ClusterBinCount * twoPi
        wsum = wsum + w
        ysum = ysum + w * center
    end
    st.realYaw = wsum > 0 and (ysum / wsum) or ((peakIdx - 0.5) / ClusterBinCount * twoPi)

    local prevYaw = st.lockedYaw or st.realYaw
    local dy = st.realYaw - prevYaw
    if dy > math.pi then dy = dy - twoPi elseif dy < -math.pi then dy = dy + twoPi end
    st.yawSpinRate = dy / ClusterSampleInterval
    st.lockedYaw = st.realYaw

    st.confidence = st.yawConfidence
    if st.grounded and st.confidence >= ClusterPeakThreshold then
        st.stablePos = hrp.Position
    end
end)

RegisterClusterTask("spoof", 0.1, function(target, hrp, now)
    local st = ClusterGetOrCreate(target)
    local score = 0

    if math.abs(st.yawSpinRate) > 8 then score = score + 0.35 end
    if math.abs(st.yawSpinRate) > 15 then score = score + 0.25 end
    if st.yawConfidence < 0.2 and st.velocity.Magnitude > 10 then
        score = score + 0.25
    end
    if st.realPitch and math.abs(st.realPitch) > 1.3 then score = score + 0.15 end

    local moveDir = st.velocity
    if moveDir.Magnitude > 5 then
        local cframeDir = hrp.CFrame.LookVector
        local dot = moveDir.Unit:Dot(cframeDir)
        if dot < -0.85 then score = score + 0.2 end
    end

    st.spoofScore = math.min(score, 1)

    local speed = st.velocity.Magnitude
    if speed < 2 then
        st.movementMode = "idle"
    elseif math.abs(st.yawSpinRate) > 8 then
        st.movementMode = "spin"
    elseif math.abs(st.strafeBias) > speed * 0.6 then
        st.movementMode = "strafe"
    else
        st.movementMode = "walk"
    end
end)

function ResolverClear(target)
    if target then
        ResolverStates[target] = nil
        ClusterStates[target] = nil
    else
        ResolverStates = {}
        ClusterStates = {}
    end
end

AntiAimEnabled        = false
AntiAimMode           = "spin"
AntiAimYaw            = 0
AntiAimPitch          = 0
AntiAimSpeed          = 12
AntiAimJitterMin      = -80
AntiAimJitterMax      = 80
AntiAimJitterInterval = 0.06
AntiAimLastJitter     = 0
AntiAimStaticYaw      = 180

function AntiAimComputeAngle(dt)
    local now = os.clock()
    if AntiAimMode == "spin" then
        AntiAimYaw = AntiAimYaw + AntiAimSpeed * dt
        if AntiAimYaw > TAU then AntiAimYaw = AntiAimYaw - TAU * math.floor(AntiAimYaw / TAU) end
        return AntiAimYaw, math.rad(AntiAimPitch)
    elseif AntiAimMode == "jitter" then
        if now - AntiAimLastJitter >= AntiAimJitterInterval then
            AntiAimLastJitter = now
            local r = math.random()
            AntiAimYaw = math.rad(AntiAimJitterMin + r * (AntiAimJitterMax - AntiAimJitterMin))
        end
        return AntiAimYaw, math.rad(AntiAimPitch)
    elseif AntiAimMode == "static" then
        return math.rad(AntiAimStaticYaw), math.rad(AntiAimPitch)
    end
    return 0, 0
end

function AntiAimApply(baseCF, dt)
    if not AntiAimEnabled or not baseCF then return baseCF end
    local yaw, pitch = AntiAimComputeAngle(dt or 0.016)
    return baseCF * CFrame.Angles(pitch, yaw, 0)
end

OrbitRadiusJitter = 1.5
OrbitHeightJitter = 1.0
OrbitNoiseSeedX   = math.random() * 1000
OrbitNoiseSeedY   = math.random() * 1000
OrbitNoiseSeedZ   = math.random() * 1000
OrbitLastRadius   = nil
OrbitLastHeight   = nil
orbit_smoothrate  = 0.25

function ComputeJitteredOrbit(anchorPos, now)
    local phase = math.noise(now * 0.3, OrbitNoiseSeedX) * TAU
    local rNoise1 = math.noise(now * 0.7, OrbitNoiseSeedY)
    local rNoise2 = math.noise(now * 1.9, OrbitNoiseSeedY + 17) * 0.35
    local rawRadius = OrbitRadius + (rNoise1 + rNoise2) * OrbitRadiusJitter
    local hNoise1 = math.noise(0, now * 0.9 + OrbitNoiseSeedZ)
    local hNoise2 = math.noise(0, now * 2.3 + OrbitNoiseSeedZ + 31) * 0.25
    local rawHeight = OrbitHeight + (hNoise1 + hNoise2) * OrbitHeightJitter
    if OrbitLastRadius then
        OrbitLastRadius = OrbitLastRadius + (rawRadius - OrbitLastRadius) * orbit_smoothrate
        OrbitLastHeight = OrbitLastHeight + (rawHeight - OrbitLastHeight) * orbit_smoothrate
    else
        OrbitLastRadius = rawRadius
        OrbitLastHeight = rawHeight
    end
    local angle = OrbitAngle + phase
    local cosA, sinA = math.cos(angle), math.sin(angle)
    local x = cosA * OrbitLastRadius
    local z = sinA * OrbitLastRadius
    local bob   = math.sin(now * 1.6 + OrbitNoiseSeedX) * 0.35
    local drift = math.noise(now * 0.15, OrbitNoiseSeedZ + 7) * 0.5
    local y     = OrbitLastHeight + bob + drift
    return Vector3.new(anchorPos.X + x, anchorPos.Y + y, anchorPos.Z + z)
end

function UpdateReloadingState()
    local reloading = rawget(_G, "IsReloading") == true
    if reloading then
        ReloadingActive = true
        ReloadHoldUntil = os.clock() + RELOAD_HOLD_TIME
    elseif ReloadingActive then
        if os.clock() >= ReloadHoldUntil then ReloadingActive = false end
    end
    return ReloadingActive
end

function IsVoidPosition(pos)
    if typeof(pos) ~= "Vector3" then return true end
    if pos.X ~= pos.X or pos.Y ~= pos.Y or pos.Z ~= pos.Z then return true end
    return math.abs(pos.X) > VOID_THRESHOLD
        or math.abs(pos.Y) > VOID_THRESHOLD
        or math.abs(pos.Z) > VOID_THRESHOLD
end

function SafeSetOwner(hrp, owner)
    if not hrp then return end
    if not hrp:IsA("BasePart") then return end
    local ok, current = pcall(function() return hrp:GetNetworkOwner() end)
    if ok and current == owner then return end
    pcall(function() hrp:SetNetworkOwner(owner) end)
end

function IsGrounded(hrp)
    if not hrp or not hrp.Parent then return false end
    local hum = hrp.Parent:FindFirstChildOfClass("Humanoid")
    if not hum then return false end
    local st = hum:GetState()
    if st == Enum.HumanoidStateType.Freefall
        or st == Enum.HumanoidStateType.Jumping
        or st == Enum.HumanoidStateType.FallingDown
        or st == Enum.HumanoidStateType.Swimming then return false end
    if hum.FloorMaterial == Enum.Material.Air then return false end
    local v = hrp.AssemblyLinearVelocity
    if math.abs(v.Y) > 2 then return false end
    return true
end

function ProjectToGround(cf)
    if not cf then return nil end
    local selfChar = _56.Character
    local rp = RaycastParams.new()
    rp.FilterType = Enum.RaycastFilterType.Exclude
    rp.FilterDescendantsInstances = selfChar and { selfChar } or {}
    local origin = cf.Position + Vector3.new(0, 5, 0)
    local result = workspace:Raycast(origin, Vector3.new(0, -200, 0), rp)
    if result then
        local pos = Vector3.new(cf.Position.X, result.Position.Y + 3, cf.Position.Z)
        return CFrame.new(pos, pos + cf.LookVector)
    end
    return cf
end

function IsSelfAlive()
    local char = _56.Character
    if not char then return false end
    local hum = char:FindFirstChildOfClass("Humanoid")
    return hum ~= nil and hum.Health > 0
end

function GetSelfHRP()
    local char = _56.Character
    if not char then return nil end
    local hum = char:FindFirstChildOfClass("Humanoid")
    if not hum or hum.Health <= 0 then return nil end
    return char:FindFirstChild("HumanoidRootPart")
end

function CanSaveAnchor()
    if Restoring then return false end
    if stomping then return false end
    if IdleState ~= "none" then return false end
    if os.clock() - LastIdleExitTime < AnchorSaveDelay then return false end
    return true
end

function UpdateSelfAnchor()
    if Restoring or IdleState ~= "none" or stomping then return end
    local hrp = GetSelfHRP()
    if not hrp then return end
    if IsVoidPosition(hrp.Position) then return end
    if not IsGrounded(hrp) then return end
    LastRealSelfCFrame = hrp.CFrame
end

function CaptureReturnPoint()
    if ReturnSet and ReturnCFrame then return end
    if not CanSaveAnchor() then return end
    local hrp = GetSelfHRP()
    if not hrp then return end
    if IsVoidPosition(hrp.Position) then
        if LastRealSelfCFrame then
            local p = ProjectToGround(LastRealSelfCFrame)
            if p then ReturnCFrame = p; ReturnSet = true end
        end
        return
    end
    local p = ProjectToGround(hrp.CFrame)
    if p then ReturnCFrame = p; ReturnSet = true end
end

function ForceReturnPoint()
    if ReturnSet and ReturnCFrame then return end
    if LastRealSelfCFrame and not IsVoidPosition(LastRealSelfCFrame.Position) then
        local p = ProjectToGround(LastRealSelfCFrame)
        if p then ReturnCFrame = p; ReturnSet = true; return end
    end
    local hrp = GetSelfHRP()
    if not hrp then return end
    if IsVoidPosition(hrp.Position) then return end
    local p = ProjectToGround(hrp.CFrame)
    if p then ReturnCFrame = p; ReturnSet = true end
end

function ClearReturnPoint()
    ReturnCFrame = nil
    ReturnSet = false
end

function ClaimLocal()
    local hrp = GetSelfHRP()
    if not hrp then return end
    SafeSetOwner(hrp, _56)
    OrbitNetworkClaimed = true
end

function ReleaseLocal()
    local hrp = GetSelfHRP()
    if hrp then SafeSetOwner(hrp, nil) end
    OrbitNetworkClaimed = false
end

function IsTargetKO(target)
    if not target or not target.Character or not target.Character.Parent then return false end
    return HasAnyFlag(GetBodyEffects(target), KO_FLAG_NAMES)
end

function IsTargetDeadFlag(target)
    if not target or not target.Character or not target.Character.Parent then return false end
    return HasAnyFlag(GetBodyEffects(target), DEAD_FLAG_NAMES)
end

function _orbitTargetValid(target)
    if not target or not target.Parent or not target.Character or not target.Character.Parent then return false end
    local be = GetBodyEffects(target)
    if not be then return false end
    if HasAnyFlag(be, KO_FLAG_NAMES) then return false end
    if HasAnyFlag(be, DEAD_FLAG_NAMES) then return false end
    local ok1, g = pcall(Grabbed, target)
    if ok1 and g == true then return false end
    local ok2, dd = pcall(isDead, target)
    if ok2 and dd == true then return false end
    return true
end

function IsWaitingForRespawn(target)
    if not target then return false end
    if not target.Character or not target.Character.Parent then return false end
    if lastTargetPlayer ~= target then
        lastTargetPlayer = target
        lastTargetCharacter = target.Character
        respawnPending = false
        return false
    end
    if lastTargetCharacter == nil then
        lastTargetCharacter = target.Character
        respawnPending = false
        return false
    end
    if lastTargetCharacter ~= target.Character then
        if not respawnPending then
            respawnPending = true
            targetRespawnTime = os.clock()
            IdleSpamFirst = false
            IdleSpamSwitchAt = os.clock() + IdleSpamStrafeTime
            return true
        end
        if os.clock() - targetRespawnTime < RespawnWaitTime then
            return true
        end
        respawnPending = false
        lastTargetCharacter = target.Character
        return false
    end
    if respawnPending then
        if os.clock() - targetRespawnTime < RespawnWaitTime then return true end
        respawnPending = false
    end
    return false
end

_pingCache = 0
_pingCacheAt = 0
function GetPingSeconds()
    if not _56 then return 0 end
    if not PingPredictionEnabled then return 0 end
    local now = os.clock()
    if now - _pingCacheAt < 0.5 then return _pingCache end
    _pingCacheAt = now
    local ok, ping = pcall(function()
        local item = game:GetService("Stats").Network.ServerStatsItem["Data Ping"]
        if not item then return nil end
        return item:GetValue()
    end)
    if ok and type(ping) == "number" and ping == ping then
        _pingCache = (ping * 0.001) * PingPredictionScale
    else
        _pingCache = 0
    end
    return _pingCache
end

function ResolveTargetPosition(target)
    if not target or not target.Character then return nil end
    local char = target.Character
    local hrp = char:FindFirstChild("HumanoidRootPart")
    if not hrp or not hrp.Parent or IsVoidPosition(hrp.Position) then
        return lastValidTargetState
    end

    local now = os.clock()
    local st = ClusterGetOrCreate(target)

    if ResolverEnabled and ResolverMode == "cluster" then
        RunClusterTasks(target, hrp, now)
    end

    local fusedPos = hrp.Position
    if LastAnchorPos then
        local d = fusedPos - LastAnchorPos
        local rate = (d:Dot(d) > AnchorFastMoveDist^2) and AnchorSmoothRateFast or AnchorSmoothRate
        fusedPos = LastAnchorPos:Lerp(fusedPos, rate)
    end
    LastAnchorPos = fusedPos

    local fusedYaw
    if ResolverMode == "cluster" and st.yawConfidence >= ClusterPeakThreshold then
        fusedYaw = st.realYaw
    else
        local look = hrp.CFrame.LookVector
        fusedYaw = math.atan2(-look.X, -look.Z)
    end
    local fusedLook = Vector3.new(-math.sin(fusedYaw), 0, -math.cos(fusedYaw))
    if LastAnchorLook then
        fusedLook = LastAnchorLook:Lerp(fusedLook, ClusterLookSmooth)
    end
    LastAnchorLook = fusedLook

    local fusedVel = st.velocity
    if ResolverMode ~= "cluster" then
        ResolverUpdate(target, hrp.Position)
        fusedVel = ResolverGetVelocity(target)
    end

    local out = {
        pos = fusedPos,
        rawPos = hrp.Position,
        yaw = fusedYaw,
        pitch = st.realPitch or 0,
        look = fusedLook,
        velocity = fusedVel,
        accel = st.accel,
        confidence = st.yawConfidence,
        spoofScore = st.spoofScore,
        movementMode = st.movementMode,
        grounded = st.grounded,
        cframe = CFrame.new(fusedPos, fusedPos + fusedLook),
        time = now,
    }
    lastValidTargetState = out
    lastValidTargetCFrame = out.cframe
    lastValidTargetPos = fusedPos
    lastValidTargetPosTime = now
    return out
end

function ComputeAimPoint(target, resolved)
    if not resolved then return nil end

    local lead = Vector3.new(0, 0, 0)

    if PredictionEnabled then
        local vel = resolved.velocity
        if vel.Magnitude < 0.01 then
            vel = predictionVelocity
        end

        lead = vel * PredictionMultiplier

        if PingPredictionEnabled then
            local ping = GetPingSeconds()
            if ping > 0 then
                lead = lead + vel * ping * PredictionMultiplier
            end
        end

        if resolved.accel.Magnitude > 1 then
            local dt = 1 / 60
            lead = lead + resolved.accel * (0.5 * dt * dt)
        end

        if resolved.movementMode == "spin" then
            lead = lead * 0.5
        end

        if resolved.grounded then
            lead = Vector3.new(lead.X, math.min(lead.Y, 0), lead.Z)
        end
    end

    local aimPos = resolved.pos + lead

    if resolved.confidence >= ClusterPeakThreshold then
        aimPos = Vector3.new(aimPos.X, resolved.pos.Y, aimPos.Z)
    end

    if resolved.confidence < 0.15 and resolved.spoofScore > 0.6 then
        return resolved.pos, resolved.look, Vector3.new(0, 0, 0)
    end

    return aimPos, resolved.look, lead
end

function ResolveTargetPreSimulation(target)
    local char = target and target.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    if not hrp or not hrp.Parent or IsVoidPosition(hrp.Position) then return end

    local resolved = ResolveTargetPosition(target)
    if not resolved then return end

    local aimPos, look, lead = ComputeAimPoint(target, resolved)
    if not aimPos then return end

    resolvedAimPoint = aimPos
    resolvedPredictedPos = aimPos
    resolvedAnchorCF = CFrame.new(aimPos, aimPos + (look or Vector3.new(0,0,1)))
    LastAimPoint = aimPos
    LastAimLead = lead
    LastAimState = resolved
end

function GetOrbitAnchorCFrame(target)
    local now = os.clock()
    if now - resolverLastRun < ResolverRate and resolvedAimPoint then
        return resolvedAnchorCF, resolvedAimPoint
    end
    resolverLastRun = now

    ResolveTargetPreSimulation(target)

    if not resolvedAimPoint then
        return nil, lastValidTargetPos
    end

    if LastAnchorPos then
        local d = resolvedAimPoint - LastAnchorPos
        local rate = (d:Dot(d) > AnchorFastMoveDist^2) and AnchorSmoothRateFast or AnchorSmoothRate
        LastAnchorPos = LastAnchorPos:Lerp(resolvedAimPoint, rate)
    else
        LastAnchorPos = resolvedAimPoint
    end

    return resolvedAnchorCF, resolvedAimPoint
end

function PickVoidBase()
    local x = (math.random() < 0.5) and VoidDistance or -VoidDistance
    local z = (math.random() < 0.5) and VoidDistance or -VoidDistance
    local y = VoidDistance * (0.5 + math.random() * 0.5)
    return Vector3.new(x, y, z)
end

function PickVoidOffset(now)
    local t = now * VoidJitterRate
    local jx = math.sin(t) * VoidJitterStrength + (math.random() - 0.5) * VoidJitterStrength
    local jy = math.abs(math.cos(t * 1.3) * VoidJitterStrength + (math.random() - 0.5) * VoidJitterStrength)
    local jz = math.sin(t * 0.7) * VoidJitterStrength + (math.random() - 0.5) * VoidJitterStrength
    return jx, jy, jz
end

function RefreshVoidBase(now)
    if math.random() < VoidRandomCornerChance then
        VoidBasePos = Vector3.new(
            (math.random() * 2 - 1) * VoidDistance,
            math.random() * VoidDistance,
            (math.random() * 2 - 1) * VoidDistance
        )
    else
        VoidBasePos = PickVoidBase()
    end
    VoidCycleTime = now
end

function EnterVoid()
    local hrp = GetSelfHRP()
    if not hrp then return false end
    ForceReturnPoint()
    hrp.Anchored = false
    SafeSetOwner(hrp, _56)
    local now = os.clock()
    if not VoidBasePos or (now - VoidCycleTime) > VoidCycleInterval then
        RefreshVoidBase(now)
    end
    local jx, jy, jz = PickVoidOffset(now)
    local ok = pcall(function()
        hrp.CFrame = CFrame.new(VoidBasePos.X + jx, VoidBasePos.Y + jy, VoidBasePos.Z + jz)
        hrp.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
        hrp.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
    end)
    if ok then
        IdleState = "hiding"
        VoidLastTeleport = now
    end
    return ok
end

function KeepVoidAnchor()
    if IdleState ~= "hiding" then return end
    if not IsSelfAlive() then return end
    local hrp = GetSelfHRP()
    if not hrp then return end
    if not VoidBasePos then EnterVoid(); return end
    local now = os.clock()

    hrp.Anchored = false
    SafeSetOwner(hrp, _56)

    local pos = hrp.Position
    local dx = pos.X - VoidBasePos.X
    local dy = pos.Y - VoidBasePos.Y
    local dz = pos.Z - VoidBasePos.Z
    local driftedSq = dx * dx + dy * dy + dz * dz
    local teleportDue = (now - VoidLastTeleport) >= VoidTeleportInterval
    local baseStale = (now - VoidCycleTime) >= VoidCycleInterval
    if driftedSq > 250000 or teleportDue or baseStale then
        if baseStale then RefreshVoidBase(now) end
        local jx, jy, jz = PickVoidOffset(now)
        pcall(function()
            hrp.CFrame = CFrame.new(VoidBasePos.X + jx, VoidBasePos.Y + jy, VoidBasePos.Z + jz)
            hrp.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
            hrp.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
        end)
        VoidLastTeleport = now
    end
end

function ReturnToRealWorld()
    if Restoring then return end
    if not IsSelfAlive() then return end
    local hrp = GetSelfHRP()
    if not hrp then return end

    Restoring = true
    StompReturnLocked = true

    pcall(function()
        ForceReturnPoint()
        local target = ReturnCFrame or LastRealSelfCFrame
        if target then
            local ok, projected = pcall(ProjectToGround, target)
            if ok and projected then target = projected end
        end
        if not target then
            hrp.Anchored = false
            hrp.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
            hrp.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
            return
        end
        SafeSetOwner(hrp, _56)
        hrp.CFrame = target
        hrp.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
        hrp.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
        task.wait(0.02)
        if IsSelfAlive() and hrp.Parent and _56.Character == hrp.Parent then
            hrp.CFrame = target
            hrp.Anchored = false
        end
    end)

    Restoring = false
    StompReturnLocked = false
    ReleaseLocal()
    ClearReturnPoint()
    predictionLastPos = nil
    predictionLastTime = 0
    predictionVelocity = Vector3.new(0, 0, 0)
    resolvedPredictedPos = nil
    resolvedAimPoint = nil
    LastAimPoint = nil
    LastAimLead = nil
    LastAimState = nil
    LastAnchorPos = nil
    LastAnchorLook = nil
end

function ComputeRandomOffset(now)
    if not orbitRandomOffset or (now - orbitRandomUpdate) > ORBIT_RANDOM_INTERVAL then
        local theta = math.random() * TAU
        local cosPhi = 2 * math.random() - 1
        local sinPhi = math.sqrt(1 - cosPhi * cosPhi)
        local r = OrbitRadius * (0.25 + math.random() * 0.75)
        local x = sinPhi * math.cos(theta) * r
        local y = cosPhi * r + OrbitHeight
        local z = sinPhi * math.sin(theta) * r
        orbitRandomOffset = Vector3.new(x, y, z)
        orbitRandomUpdate = now
    end
    return orbitRandomOffset
end

function ReleaseSnapWeld()
    if not SnapWelded then return end
    SnapWelded = false
    local hrp = GetSelfHRP()
    if hrp then _snapClear(hrp) end
end

function PerformSnap(hrp, targetHRP, anchorPos)
    if not targetHRP or not targetHRP.Parent then return end
    if not hrp or not hrp.Parent then return end

    local basePos = resolvedAimPoint or resolvedPredictedPos or anchorPos or lastValidTargetPos
    if not basePos or IsVoidPosition(basePos) then return end
    if IsVoidPosition(targetHRP.Position) then return end

    SafeSetOwner(hrp, _56)
    SafeSetOwner(targetHRP, _56)

    if sethiddenproperty and not SnapWelded then
        _snapApply(hrp, targetHRP)
        SnapWelded = true
    elseif sethiddenproperty and SnapWelded then
        _snapApply(hrp, targetHRP)
    end

    local look = (LastAimState and LastAimState.look) or LastAnchorLook or targetHRP.CFrame.LookVector
    local baseCF = CFrame.new(basePos, basePos + look * 0.001)
    baseCF = AntiAimApply(baseCF, 0.02)
    hrp.CFrame = baseCF

    if SnapWelded then
        local targetVel = targetHRP.AssemblyLinearVelocity
        local rx = (math.random() - 0.5) * 2 * SnapPushSpeed
        local ry = math.random() * SnapPushSpeed * 0.3
        local rz = (math.random() - 0.5) * 2 * SnapPushSpeed
        hrp.AssemblyLinearVelocity = targetVel + Vector3.new(rx, ry, rz)
    else
        hrp.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
    end
    hrp.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
end

local _PullAimRemote = nil

local function PullGetAimRemote()
    if _PullAimRemote and _PullAimRemote.Parent then
        return _PullAimRemote
    end
    local mr = game:GetService("ReplicatedStorage"):FindFirstChild("MainRemotes")
    _PullAimRemote = mr and mr:FindFirstChild("MainRemoteEvent")
    return _PullAimRemote
end

local function PullSendAim(pos)
    local ev = PullGetAimRemote()
    if ev then
        pcall(ev.FireServer, ev, "Z33H00DM2U4SEP0S" .. string.char(94) .. "2", pos)
    end
end

local function PullVisibleFrom(origin, part, targetChar)
    local rp = RaycastParams.new()
    rp.FilterType = Enum.RaycastFilterType.Exclude
    rp.FilterDescendantsInstances = { _56.Character, targetChar }
    return workspace:Raycast(origin, part.Position - origin, rp) == nil
end

function releasePullTarget()
    if PullTargetHRP and PullTargetHRP.Parent then
        pcall(function() PullTargetHRP.Anchored = false end)
        pcall(function() PullTargetHRP.AssemblyLinearVelocity = Vector3.new(0, 0, 0) end)
        pcall(function() PullTargetHRP.AssemblyAngularVelocity = Vector3.new(0, 0, 0) end)
    end
    PullTargetHRP = nil
    PullSavedAnchor = nil
end

function PullToMe(target, dt)
    local hrp = GetSelfHRP()
    if not hrp then
        releasePullTarget()
        return
    end
    local tChar = target and target.Character
    local tHRP = tChar and tChar:FindFirstChild("HumanoidRootPart")
    if not tHRP or not tChar.Parent then
        releasePullTarget()
        return
    end
    if IsVoidPosition(tHRP.Position) then
        releasePullTarget()
        return
    end
    local thum = tChar:FindFirstChildOfClass("Humanoid")
    if not thum or thum.Health <= 0 then
        releasePullTarget()
        return
    end

    if not PullSavedAnchor then
        PullSavedAnchor = hrp.CFrame
    end

    SafeSetOwner(hrp, _56)
    SafeSetOwner(tHRP, _56)

    PullStrafePhase = PullStrafePhase + PullStrafeRate * TAU * dt
    local strafe = math.sin(PullStrafePhase) * PullStrafeAmp
    local strafeRight = PullSavedAnchor.RightVector * strafe
    local anchorPos = PullSavedAnchor.Position + strafeRight
    local anchorCF = CFrame.new(anchorPos, anchorPos + PullSavedAnchor.LookVector)

    hrp.CFrame = anchorCF
    hrp.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
    hrp.AssemblyAngularVelocity = Vector3.new(0, 0, 0)

    if PullTargetHRP ~= tHRP then
        if PullTargetHRP and PullTargetHRP.Parent then
            pcall(function() PullTargetHRP.Anchored = false end)
        end
        PullTargetHRP = tHRP
    end

    local front = anchorCF * CFrame.new(0, 0, -PullRadius)
    tHRP.Anchored = true
    tHRP.CFrame = CFrame.lookAt(front.Position, anchorPos)
    tHRP.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
    tHRP.AssemblyAngularVelocity = Vector3.new(0, 0, 0)

    local tool = _56.Character and _56.Character:FindFirstChildWhichIsA("Tool")
    if not tool or tool.Parent ~= _56.Character then return end

    local ammo = tool:FindFirstChild("Ammo") or tool:FindFirstChild("CurrentAmmo") or tool:FindFirstChild("Clip")
    local ammoVal = ammo and tonumber(ammo.Value) or nil
    if ammoVal and ammoVal <= 0 then return end

    local now = os.clock()
    if now - PullLastShot < 0.03 then return end

    local checkPos = anchorPos + Vector3.new(0, 1.5, 0)
    if not PullVisibleFrom(checkPos, tHRP, tChar) then return end

    local head = tChar:FindFirstChild("Head")
    local ap = head and head.Position or tHRP.Position
    if resolvedAimPoint and not IsVoidPosition(resolvedAimPoint) then
        ap = resolvedAimPoint
    end

    for _ = 1, 3 do
        PullSendAim(ap)
    end

    pcall(function() tool:Activate() end)
    pcall(function() tool:Activate() end)

    PullSendAim(ap)
    PullLastShot = now
end

function OrbitAroundTarget(target, dt)
    dt = dt or 0.016
    local hrp = GetSelfHRP()
    if not hrp then return end

    if PullEnabled then
        local tChar = target and target.Character
        local tHRP = tChar and tChar:FindFirstChild("HumanoidRootPart")
        if not tHRP or not tChar.Parent or IsTargetKO(target) or IsTargetDeadFlag(target) then
            releasePullTarget()
            return
        end
        PullToMe(target, dt)
        return
    else
        if PullTargetHRP then releasePullTarget() end
    end

    local targetChar = target.Character
    local targetHRP = targetChar and targetChar:FindFirstChild("HumanoidRootPart")
    if not targetHRP then return end
    local anchorCF, anchorPos = GetOrbitAnchorCFrame(target)
    if not anchorPos then return end

    if SnapEnabled then
        local now = os.clock()
        if SnapPhase == "off" or (SnapPhase == "orbit" and now >= SnapPhaseUntil) then
            SnapPhase = "snap"
            SnapPhaseUntil = now + SnapHoldTime
            local selfHRP = GetSelfHRP()
            if selfHRP then SafeSetOwner(selfHRP, _56) end
        elseif SnapPhase == "snap" and now >= SnapPhaseUntil then
            SnapPhase = "orbit"
            SnapPhaseUntil = now + SnapOrbitTime
            ReleaseSnapWeld()
        end
        if SnapPhase == "snap" then PerformSnap(hrp, targetHRP, anchorPos); return end
    end

    local behavior = OrbitBehavior or 'Orbit'
    local now = os.clock()
    local targetPos
    if behavior == 'Orbit' then
        OrbitAngle = OrbitAngle + (OrbitSpeed * 3 * dt)
        targetPos = ComputeJitteredOrbit(anchorPos, now)
    elseif behavior == 'Above' then
        targetPos = Vector3.new(anchorPos.X, anchorPos.Y + OrbitHeight + 5, anchorPos.Z)
    elseif behavior == 'Hide' then
        targetPos = Vector3.new(anchorPos.X, anchorPos.Y - 7, anchorPos.Z)
    elseif behavior == 'Random' then
        targetPos = anchorPos + ComputeRandomOffset(now)
    else
        targetPos = Vector3.new(anchorPos.X, anchorPos.Y + OrbitHeight, anchorPos.Z)
    end
    if IsVoidPosition(targetPos) then return end
    local lookAt = anchorPos
    if anchorCF then lookAt = anchorCF.Position + anchorCF.LookVector * 0.001 end
    local baseCF = CFrame.new(targetPos, lookAt)
    baseCF = AntiAimApply(baseCF, dt)
    if behavior == 'Random' then
        if now - lastSnapTime >= SNAP_INTERVAL then
            lastSnapTime = now
            if not IsVoidPosition(targetHRP.Position) then
                local tp = resolvedAimPoint or targetHRP.Position
                local tl = (LastAimState and LastAimState.look) or targetHRP.CFrame.LookVector
                local snapCF = CFrame.new(tp, tp + tl * 0.001)
                local sx = (math.random() - 0.5) * 2
                local sy = OrbitHeight * (0.5 + math.random())
                local sz = (math.random() - 0.5) * 2
                local snapFinal = AntiAimApply(snapCF + Vector3.new(sx, sy, sz), dt)
                hrp.CFrame = snapFinal
                hrp.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
                hrp.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
                return
            end
        end
    end
    hrp.CFrame = baseCF
    hrp.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
    hrp.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
end

function EnterIdle(reason)
    if Restoring then return false end
    if IdleState == "hiding" then
        IdleReason = reason or IdleReason
        StartIdle()
        return true
    end
    _enterIdleLock = false
    local hrp = GetSelfHRP()
    if not hrp then return false end
    local ok = false
    pcall(function()
        ForceReturnPoint()
        VoidBasePos = nil
        VoidCycleTime = 0
        ok = EnterVoid()
    end)
    _enterIdleLock = false
    if ok then
        IdleReason = reason or "idle"
        StartIdle()
    end
    return ok
end

function ExitIdle(restore)
    _exitIdleLock = true
    local wasHiding = IdleState == "hiding"
    IdleState = "none"
    IdleReason = nil
    LastIdleExitTime = os.clock()
    VoidBasePos = nil
    VoidCycleTime = 0
    VoidLastTeleport = 0
    resolvedPredictedPos = nil
    resolvedAimPoint = nil
    LastAimPoint = nil
    LastAimLead = nil
    LastAimState = nil
    LastAnchorPos = nil
    LastAnchorLook = nil
    resolverLastRun = 0
    if restore and wasHiding then
        pcall(function() ReturnToRealWorld() end)
    else
        local hrp = GetSelfHRP()
        if hrp then
            pcall(function()
                hrp.Anchored = false
                hrp.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
                hrp.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
            end)
        end
    end
    _exitIdleLock = false
end

function ExitIdleToOrbit()
    local target = _104.targetplayer
    local hrp = GetSelfHRP()
    if hrp and target and target.Character then
        local tHRP = target.Character:FindFirstChild("HumanoidRootPart")
        if tHRP and not IsVoidPosition(tHRP.Position) then
            local angle = OrbitAngle
            local startPos = tHRP.Position + Vector3.new(
                math.cos(angle) * OrbitRadius,
                OrbitHeight,
                math.sin(angle) * OrbitRadius
            )
            pcall(function() hrp.CFrame = CFrame.new(startPos, tHRP.Position) end)
            ExitIdle(false)
            return
        end
    end
    ForceReturnPoint()
    ExitIdle(ReturnSet and ReturnCFrame ~= nil)
end

function IdleKOStep(reason)
    if IdleState ~= "hiding" then
        EnterIdle(reason or "ko")
    else
        IdleReason = reason or IdleReason or "ko"
        EnterVoid()
    end
end

function StartDisengage()
    if not EngagementActive then return end
    if Disengaging then return end
    Disengaging = true
    EngagementActive = false
    disengageAt = os.clock() + DisengageDelay
    ForceReturnPoint()
end

function HandleTargetLost()
    releasePullTarget()
    PullStrafePhase = 0
    local wasHiding = IdleState == "hiding"
    if wasHiding then
        ForceReturnPoint()
        ExitIdle(true)
    else
        ForceReturnPoint()
        if ReturnSet and ReturnCFrame then
            pcall(function() ReturnToRealWorld() end)
        end
    end
    if EngagementActive and not Disengaging then
        Disengaging = true
        EngagementActive = false
        disengageAt = os.clock() + DisengageDelay
        ForceReturnPoint()
    end
    ReleaseSnapWeld()
    OrbitTarget = nil
    OrbitNetworkClaimed = false
    lastValidTargetPos = nil
    lastValidTargetCFrame = nil
    lastValidTargetState = nil
    orbitRandomOffset = nil
    lastTargetCharacter = nil
    lastTargetPlayer = nil
    respawnPending = false
    lastSnapTime = 0
    IdleSpamState = "none"
    IdleSpamSwitchAt = 0
    IdleSpamFirst = false
    predictionLastPos = nil
    predictionLastTime = 0
    predictionVelocity = Vector3.new(0, 0, 0)
    resolvedPredictedPos = nil
    resolvedAimPoint = nil
    resolvedAnchorCF = nil
    LastAimPoint = nil
    LastAimLead = nil
    LastAimState = nil
    LastAnchorPos = nil
    LastAnchorLook = nil
    OrbitLastRadius = nil
    OrbitLastHeight = nil
    SnapPhase = "off"
    SnapPhaseUntil = 0
    if ResolverStates then ResolverClear() end
end

function EvaluateIdle()
    if Restoring then return end
    if stomping then return end
    if CheckStompLockClear then pcall(CheckStompLockClear) end

    if not OrbitEnabled then
        if IdleState ~= "none" then ExitIdle(true) end
        return
    end
    if not IsSelfAlive() then return end

    local target = _104.targetplayer
    local reloading = UpdateReloadingState()

    if IdleState ~= "hiding" then
        if not target or not target.Parent then return end
        if not target.Character or not target.Character.Parent then
            if IdleKOEnabled then EnterIdle("gone") end
            return
        end
        if IdleReloadEnabled and reloading then EnterIdle("reload"); return end
        local targetKO = IsTargetKO(target)
        local targetDeadFlag = IsTargetDeadFlag(target)
        if IdleKOEnabled and (targetKO or targetDeadFlag) then
            if StompEnabled then
                local sameKO = (StompLockTarget == target and StompLockChar == target.Character)
                if not sameKO and targetKO then return end
            end
            EnterIdle(targetKO and "ko" or "dead")
            return
        end
        if IdleSpamEnabled then
            local now = os.clock()
            if IdleSpamState ~= "strafing" then
                IdleSpamState = "strafing"
                IdleSpamSwitchAt = now + IdleSpamStrafeTime
                IdleSpamFirst = not IdleSpamKnown[target]
                IdleSpamKnown[target] = true
            elseif now >= IdleSpamSwitchAt then
                if IdleSpamFirst then
                    IdleSpamFirst = false
                    IdleSpamSwitchAt = now + IdleSpamStrafeTime
                else
                    IdleSpamState = "idling"
                    IdleSpamSwitchAt = now + IdleSpamIdleTime
                    EnterIdle("spam")
                    return
                end
            end
        end
        return
    end

    KeepVoidAnchor()

    if not target or not target.Parent then
        IdleReason = "gone"
        ForceReturnPoint()
        ExitIdle(ReturnSet and ReturnCFrame ~= nil)
        return
    end

    if not target.Character or not target.Character.Parent then return end

    local targetKO = IsTargetKO(target)
    local targetDeadFlag = IsTargetDeadFlag(target)
    local grabbed = false
    pcall(function() grabbed = Grabbed(target) == true end)

    if reloading and IdleReloadEnabled then IdleReason = "reload"; return end
    if (targetKO or targetDeadFlag) and IdleKOEnabled then
        IdleReason = targetKO and "ko" or "dead"
        return
    end
    if IdleReason == "spam" then
        local now = os.clock()
        if now >= IdleSpamSwitchAt then
            if targetDeadFlag or grabbed or IsWaitingForRespawn(target) then
                IdleSpamSwitchAt = now + 0.25
                return
            end
            IdleSpamState = "strafing"
            IdleSpamSwitchAt = now + IdleSpamStrafeTime
            ExitIdleToOrbit()
            return
        end
        return
    end
    if IdleReason == "ko" then
        if not targetKO and not targetDeadFlag and not grabbed then ExitIdleToOrbit() end
        return
    end
    if IdleReason == "dead" then
        if not targetDeadFlag and not grabbed then ExitIdleToOrbit() end
        return
    end
    if IdleReason == "reload" then
        if not reloading then ExitIdleToOrbit() end
        return
    end
    if IdleReason == "gone" then
        ForceReturnPoint()
        ExitIdle(ReturnSet and ReturnCFrame ~= nil)
        return
    end
    if IdleReason == "hide" then ExitIdleToOrbit(); return end
    if not targetKO and not targetDeadFlag and not grabbed then ExitIdleToOrbit(); return end
end

function StartIdle()
    if not (IdleKOEnabled or IdleReloadEnabled or IdleSpamEnabled) or not OrbitEnabled then
        if IdleConnection then IdleConnection:Disconnect(); IdleConnection = nil end
        return
    end
    if IdleConnection then return end
    IdleConnection = RunService.Heartbeat:Connect(EvaluateIdle)
end

function StopIdle()
    if IdleConnection then IdleConnection:Disconnect() IdleConnection = nil end
    if IdleState ~= "none" then ExitIdle(true) end
end

function Orbit(dt)
    dt = dt or 0.016
    if Restoring then return end
    if not OrbitEnabled then return end
    if _118 then return end
    if _AA_busy then return end
    if stomping then return end
    if grabbing then return end
    if not IsSelfAlive() then return end

    if CheckStompLockClear then pcall(CheckStompLockClear) end
    if IdleState == "hiding" and not IdleConnection then StartIdle() end
    if IdleState == "hiding" then return end

    local reloading = UpdateReloadingState()

    if Disengaging then
        local nowDis = os.clock()
        if disengageAt > 0 and nowDis >= disengageAt then
            Disengaging = false
            disengageAt = 0
            EngagementActive = false
            ReleaseSnapWeld()
            releasePullTarget()
            local doReturn = ReturnSet and ReturnCFrame ~= nil and IsSelfAlive()
            if doReturn then
                task.spawn(function() pcall(ReturnToRealWorld) end)
            else
                local hrpNow = GetSelfHRP()
                if hrpNow then
                    pcall(function()
                        hrpNow.Anchored = false
                        hrpNow.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
                        hrpNow.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
                    end)
                end
                ReleaseLocal()
                ClearReturnPoint()
            end
        end
        return
    end

    UpdateSelfAnchor()

    local target = _104.targetplayer
    if not target or not target.Parent then
        ReleaseSnapWeld()
        OrbitTarget = nil
        OrbitNetworkClaimed = false
        lastTargetCharacter = nil
        lastTargetPlayer = nil
        respawnPending = false
        StartDisengage()
        return
    end

    if IsWaitingForRespawn(target) then
        local hrp = GetSelfHRP()
        if hrp and ReturnCFrame then pcall(function() hrp.CFrame = ReturnCFrame end) end
        return
    end

    if not target.Character or not target.Character.Parent then
        if IdleKOEnabled then
            EnterIdle("gone")
            disengageAt = 0
        end
        return
    end

    if IdleReloadEnabled and reloading then
        EnterIdle("reload")
        disengageAt = 0
        return
    end

    local targetKO   = IsTargetKO(target)
    local targetDead = IsTargetDeadFlag(target)

    if IdleKOEnabled and (targetKO or targetDead) then
        if StompEnabled and targetKO and not targetDead then
            local sameKO = (StompLockTarget == target and StompLockChar == target.Character)
            if not sameKO then
                disengageAt = 0
                return
            end
        end

        if not ReturnSet or not ReturnCFrame or IsVoidPosition(ReturnCFrame.Position) then
            ClearReturnPoint()
            local hrpNow = GetSelfHRP()
            if hrpNow and not IsVoidPosition(hrpNow.Position) then
                local p = ProjectToGround(hrpNow.CFrame)
                if p then ReturnCFrame = p; ReturnSet = true end
            end
        end
        EnterIdle(targetKO and "ko" or "dead")
        disengageAt = 0
        return
    end

    if (targetKO or targetDead) and not IdleKOEnabled then
        StartDisengage()
        return
    end

    if not _orbitTargetValid(target) then return end
    disengageAt = 0

    local hrp = GetSelfHRP()
    if not hrp then return end
    local targetHRP = target.Character:FindFirstChild("HumanoidRootPart")
    if not targetHRP then return end

    if OrbitTarget ~= target then
        ReleaseSnapWeld()
        releasePullTarget()
        PullStrafePhase = 0
        OrbitTarget = target
        OrbitNetworkClaimed = false
        lastValidTargetPos = nil
        lastValidTargetCFrame = nil
        lastValidTargetState = nil
        orbitRandomOffset = nil
        lastTargetCharacter = target.Character
        lastTargetPlayer = target
        respawnPending = false
        lastSnapTime = 0
        predictionLastPos = nil
        predictionLastTime = 0
        predictionVelocity = Vector3.new(0, 0, 0)
        resolvedPredictedPos = nil
        resolvedAimPoint = nil
        resolvedAnchorCF = nil
        LastAimPoint = nil
        LastAimLead = nil
        LastAimState = nil
        LastAnchorPos = nil
        LastAnchorLook = nil
        OrbitLastRadius = nil
        OrbitLastHeight = nil
        SnapPhase = "off"
        SnapPhaseUntil = 0
        ClusterStates[target] = nil
    end

    CaptureReturnPoint()
    ClaimLocal()
    if not IsVoidPosition(targetHRP.Position) then SafeSetOwner(targetHRP, _56) end
    EngagementActive = true
    OrbitAroundTarget(target, dt)
end

function OrbitPreSimulation()
    if Restoring then return end
    if not OrbitEnabled then return end
    if _118 then return end
    if _AA_busy then return end
    if stomping then return end
    if grabbing then return end
    if not IsSelfAlive() then return end
    if IdleState == "hiding" then return end
    if Disengaging then return end

    local target = _104.targetplayer
    if not target or not target.Parent then return end
    if not target.Character or not target.Character.Parent then return end
    local tHRP = target.Character:FindFirstChild("HumanoidRootPart")
    if not tHRP or not tHRP.Parent or IsVoidPosition(tHRP.Position) then return end

    ResolveTargetPreSimulation(target)

    if SnapEnabled and SnapPhase == "snap" and sethiddenproperty then
        local hrp = GetSelfHRP()
        if hrp then
            _snapSetPart(hrp, tHRP)
            _snapSetRef(hrp, tHRP)
            SnapWelded = true
        end
    end
end

function StartOrbit()
    if Restoring then Restoring = false end
    if OrbitConnection then OrbitConnection:Disconnect() OrbitConnection = nil end
    if OrbitPreSimConn then OrbitPreSimConn:Disconnect() OrbitPreSimConn = nil end
    if not OrbitEnabled then return end
    _enterIdleLock = false
    _exitIdleLock = false
    OrbitAngle = 0
    OrbitNetworkClaimed = false
    EngagementActive = false
    Disengaging = false
    disengageAt = 0
    IdleState = "none"
    IdleReason = nil
    IdleSpamState = "none"
    IdleSpamSwitchAt = 0
    IdleSpamFirst = false
    VoidBasePos = nil
    VoidCycleTime = 0
    VoidLastTeleport = 0
    ClearReturnPoint()
    LastIdleExitTime = 0
    OrbitTarget = nil
    lastValidTargetPos = nil
    lastValidTargetCFrame = nil
    lastValidTargetState = nil
    orbitRandomOffset = nil
    lastTargetCharacter = nil
    lastTargetPlayer = nil
    respawnPending = false
