    resolvedAimPoint = nil
    resolvedAnchorCF = nil
    LastAimPoint = nil
    LastAimLead = nil
    LastAimState = nil
    LastAnchorPos = nil
    LastAnchorLook = nil
    OrbitLastRadius = nil
    OrbitLastHeight = nil
    SnapPhase = "off"
    SnapPhaseUntil = 0
    SnapWelded = false
    if ResolverStates then ResolverClear() end
    UpdateSelfAnchor()
    OrbitPreSimConn = RunService.PreSimulation:Connect(OrbitPreSimulation)
    OrbitConnection = RunService.Heartbeat:Connect(Orbit)
    StartIdle()
end

function StopOrbit()
    releasePullTarget()
    PullStrafePhase = 0
    ReleaseSnapWeld()
    if IdleConnection then IdleConnection:Disconnect() IdleConnection = nil end
    if OrbitConnection then OrbitConnection:Disconnect() OrbitConnection = nil end
    if OrbitPreSimConn then OrbitPreSimConn:Disconnect() OrbitPreSimConn = nil end
    Disengaging = false
    disengageAt = 0
    EngagementActive = false
    if IdleState ~= "none" then ExitIdle(true) end
    if ReturnSet and IsSelfAlive() then ReturnToRealWorld() end
    _enterIdleLock = false
