Core = Core or {}

Core.parts = Core.parts or {
    Head = true, UpperTorso = false, LowerTorso = false, HumanoidRootPart = false,
    ["Left Arm"] = false, ["Right Arm"] = false, ["Left Leg"] = false, ["Right Leg"] = false,
    LeftUpperArm = false, LeftLowerArm = false, LeftHand = false,
    RightUpperArm = false, RightLowerArm = false, RightHand = false,
    LeftUpperLeg = false, LeftLowerLeg = false, LeftFoot = false,
    RightUpperLeg = false, RightLowerLeg = false, RightFoot = false,
    Torso = false, Closest = false,
}

Core.wall    = false
Core.enabled = false

local rayParams = RaycastParams.new()
rayParams.FilterType = Enum.RaycastFilterType.Exclude

local Fallback = {
    UpperTorso = "Torso", LowerTorso = "Torso", Torso = "UpperTorso",
    LeftUpperArm = "Left Arm", LeftLowerArm = "Left Arm", LeftHand = "Left Arm",
    RightUpperArm = "Right Arm", RightLowerArm = "Right Arm", RightHand = "Right Arm",
    LeftUpperLeg = "Left Leg", LeftLowerLeg = "Left Leg", LeftFoot = "Left Leg",
    RightUpperLeg = "Right Leg", RightLowerLeg = "Right Leg", RightFoot = "Right Leg",
    ["Left Arm"] = "LeftUpperArm", ["Right Arm"] = "RightUpperArm",
    ["Left Leg"] = "LeftUpperLeg", ["Right Leg"] = "RightUpperLeg",
}

function matches(name, set)
    for sel in pairs(set) do
        if sel == name or Fallback[sel] == name then
            return true
        end
    end
    return false
end

function alive(player, minHp)
    if not player or player.Parent ~= Players then return nil end
    local char = player.Character
    if not char then return nil end
    local hum = char:FindFirstChildOfClass("Humanoid")
    if not hum or hum.Health <= (minHp or 0) then return nil end
    return char, hum
end

function Core.visible(c, part, char)
    local myChar = LocalPlayer.Character
    rayParams.FilterDescendantsInstances = { myChar, char }
    local origin = c.CFrame.Position
    return workspace:Raycast(origin, part.Position - origin, rayParams) == nil
end

function resolvePart(c, player)
    local char = alive(player, 0)
    if not char then return nil end

    if GetAimPart then
        local ok, part = pcall(GetAimPart, player)
        if ok and part and part.Parent and part:IsA("BasePart") then
            return char, part
        end
    end

    local all = Core.parts.Closest or next(Core.parts) == nil
    local center = c.ViewportSize / 2
    local best, bestD
    for _, part in ipairs(char:GetChildren()) do
        if part:IsA("BasePart") then
            local ok = all and part.Name ~= "HumanoidRootPart" or matches(part.Name, Core.parts)
            if ok then
                local sp = c:WorldToViewportPoint(part.Position)
                local d = (Vector2.new(sp.X, sp.Y) - center).Magnitude
                if not bestD or d < bestD then
                    best, bestD = part, d
                end
            end
        end
    end
    return char, best
end

function Core.step(dt)
    local c = workspace.CurrentCamera
    if not c then return end
    if not Core.enabled then return end

    local player = _104.targetplayer
    if not player or player.Parent ~= Players then return end
    if player == LocalPlayer then return end

    local char, part = resolvePart(c, player)
    if not (char and part) then return end

    if Core.wall and not Core.visible(c, part, char) then return end

    local targetPos = part.Position
    local vel = part.AssemblyLinearVelocity
    if vel then
        targetPos = targetPos + vel * 0.03
    end

    local s = _G.AimSmoothness or 0.25
    local goal = CFrame.new(c.CFrame.Position, targetPos)

    if s <= 0.01 then
        c.CFrame = goal
    else
        local alpha = math.clamp(1 - s, 0.02, 1)
        c.CFrame = c.CFrame:Lerp(goal, alpha)
    end
end

RunService:BindToRenderStep("localcameraforus", Enum.RenderPriority.Camera.Value + 1, function(dt)
    if _G.AimMethod ~= 'Aimbot' then return end
    Core.enabled = _104.active and true or false
    local ok, err = pcall(Core.step, dt or (1/60))
    if not ok then warn("[aimbot] " .. tostring(err)) end
end)

