function cleanup()
    isRunning = false
    for _, connection in pairs(connections) do
        if connection then
            pcall(connection.Disconnect, connection)
        end
    end
    connections = {}
    for _, taskId in pairs(spawnedTasks) do
        if taskId and type(taskId) == "thread" then
            pcall(task.cancel, taskId)
        end
    end
    spawnedTasks = {}
    for player, label in pairs(names) do
        if label and label.Parent then
            pcall(label.Destroy, label)
        end
    end
    names = {}
    shared.FriendsCache = {}
    local coreGui = game:GetService("CoreGui")
    local screenGui = coreGui:FindFirstChild("ESPGui")
    if screenGui then
        pcall(screenGui.Destroy, screenGui)
    end
end

function fetchAllFriends()
    if not isRunning then return {} end
    local friendIds = {}
    local cursor = nil
    local hasMore = true
    local maxPages = 20
    local pageCount = 0
    while hasMore and pageCount < maxPages and isRunning do
        pageCount = pageCount + 1
        local success, result = pcall(function()
            if cursor then
                return _51:GetFriendsAsync(ESPLocalPlayer.UserId, cursor)
            else
                return _51:GetFriendsAsync(ESPLocalPlayer.UserId)
            end
        end)
        if not success or not result then
            break
        end
        local pageData = nil
        local getPageSuccess = pcall(function()
            pageData = result:GetCurrentPage()
        end)
        if not getPageSuccess or not pageData then
            break
        end
        for _, friend in ipairs(pageData) do
            if friend and friend.Id then
                friendIds[friend.Id] = {
                    UserId = friend.Id,
                    Username = friend.Username or "Unknown",
                    DisplayName = friend.DisplayName or friend.Username or "Unknown"
                }
            end
        end
        local nextCursor = nil
        local getCursorSuccess = pcall(function()
            nextCursor = result:GetNextCursor()
        end)
        if getCursorSuccess and nextCursor and nextCursor ~= "" then
            cursor = nextCursor
        else
            hasMore = false
        end
        task.wait(0.05)
    end
    return friendIds
end

function getPlayerTeam(player)
    if not player or not player.Character then return nil end
    local character = player.Character
    local humanoid = character:FindFirstChild("Humanoid")
    if humanoid then
        local teamValue = humanoid:FindFirstChild("Team")
        if teamValue then
            return teamValue.Value
        end
    end
    local torso = character:FindFirstChild("Torso") or character:FindFirstChild("UpperTorso")
    if torso then
        local teamValue = torso:FindFirstChild("Team")
        if teamValue then
            return teamValue.Value
        end
    end
    for _, child in ipairs(character:GetChildren()) do
        if child:IsA("Accessory") then
            local handle = child:FindFirstChild("Handle")
            if handle then
                local teamValue = handle:FindFirstChild("Team")
                if teamValue then
                    return teamValue.Value
                end
            end
        end
        local teamValue = child:FindFirstChild("Team")
        if teamValue and type(teamValue.Value) == "string" then
            return teamValue.Value
        end
    end
    local characterTeam = character:GetAttribute("Team")
    if characterTeam then
        return characterTeam
    end
    return nil
end

function isSameTeam(player)
    local localTeam = getPlayerTeam(ESPLocalPlayer)
    local playerTeam = getPlayerTeam(player)
    if not localTeam or not playerTeam then return false end
    return localTeam == playerTeam
end

function isFriend(player)
    if not player or not player.UserId then return false end
    return shared.FriendsCache[player.UserId] ~= nil
end

function updateAllESPLabels()
    for player, label in pairs(names) do
        if label and label.Parent and player and player.Parent then
            updateLabelStyle(label, player)
        elseif label and not label.Parent then
            names[player] = nil
        end
    end
end

function espToggleOn(toggleName)
    return Toggles and Toggles[toggleName] and Toggles[toggleName].Value
end

_MOD_CACHE = {}
_COLOR_TARGET = Color3.fromRGB(255, 255, 255)
_COLOR_TEAM = Color3.fromRGB(0, 255, 0)
_COLOR_FRIEND = Color3.fromRGB(0, 200, 255)
_COLOR_STROKE = Color3.fromRGB(0, 0, 0)

function _hasModFlag(userId)
    local cache = _MOD_CACHE[userId]
    if cache ~= nil then return cache end
    local v = _G.j2h5g8f1 and _G.j2h5g8f1[userId] ~= nil
    _MOD_CACHE[userId] = v
    return v
end
function buildESPText(player, nameText)
    local showNames = espToggleOn("ESPShowNames")
    if not showNames then return "" end

    local showDist = espToggleOn("ESPShowDistance")
    local showHp = espToggleOn("ESPShowHealth")
    local character = player.Character
    local dist, hp

    if character and (showDist or showHp) then
        if showDist then
            local head = character:FindFirstChild("Head")
            if head then
                dist = math.floor((Camera.CFrame.Position - head.Position).Magnitude)
            end
        end
        if showHp then
            local hum = character:FindFirstChild("Humanoid")
            if hum then hp = math.floor(hum.Health) end
        end
    end

    local mod = _hasModFlag(player.UserId) and " [MOD]" or ""
    if not dist and not hp then
        return nameText .. mod
    end
    return string.format("%s%s%s%s",
        nameText, mod,
        dist and (" [" .. dist .. "m]") or "",
        hp and (" " .. hp .. " HP") or ""
    )
end

function setAllESPVisible(visible)
    for _, label in pairs(names) do
        if label and label.Parent then
            label.Visible = visible
        end
    end
end

function updateLabelStyle(label, player)
    if not label or not player or not isRunning then return end
    if not espToggleOn("ESPEnabled") then return end
    updateCurrentTarget()
    local isTargeted = (currentTargetPlayer == player)
    local isTeammate = (not isTargeted) and isSameTeam(player)
    local isPlayerFriend = (not isTargeted) and (not isTeammate) and isFriend(player)
    local displayName = player.DisplayName or player.Name
    local text, color, size
    if isTargeted then
        text = buildESPText(player, " " .. displayName .. " ")
        color = _COLOR_TARGET
        size = 14
    elseif isTeammate then
        text = buildESPText(player, "◉ " .. displayName .. " ◉")
        color = _COLOR_TEAM
        size = 13
    elseif isPlayerFriend then
        text = buildESPText(player, "★ " .. displayName .. " ★")
        color = _COLOR_FRIEND
        size = 13
    else
        text = buildESPText(player, displayName)
        color = _COLOR_TARGET
        size = 13
    end
    if label.Text ~= text then label.Text = text end
    if label.TextColor3 ~= color then label.TextColor3 = color end
    if label.TextStrokeColor3 ~= _COLOR_STROKE then label.TextStrokeColor3 = _COLOR_STROKE end
    if label.TextStrokeTransparency ~= 0 then label.TextStrokeTransparency = 0 end
    if label.TextSize ~= size then label.TextSize = size end
    if label.Font ~= Enum.Font.GothamBold then label.Font = Enum.Font.GothamBold end
end

skeletonLines = {}
skeletonConnections = {}

bones = {
    {"Head", "UpperTorso"},
    {"UpperTorso", "LowerTorso"},
    {"UpperTorso", "LeftUpperArm"},
    {"LeftUpperArm", "LeftLowerArm"},
    {"LeftLowerArm", "LeftHand"},
    {"UpperTorso", "RightUpperArm"},
    {"RightUpperArm", "RightLowerArm"},
    {"RightLowerArm", "RightHand"},
    {"LowerTorso", "LeftUpperLeg"},
    {"LeftUpperLeg", "LeftLowerLeg"},
    {"LeftLowerLeg", "LeftFoot"},
    {"LowerTorso", "RightUpperLeg"},
    {"RightUpperLeg", "RightLowerLeg"},
    {"RightLowerLeg", "RightFoot"}
}

partNames = {
    "Head", "UpperTorso", "LowerTorso",
    "LeftUpperArm", "LeftLowerArm", "LeftHand",
    "RightUpperArm", "RightLowerArm", "RightHand",
    "LeftUpperLeg", "LeftLowerLeg", "LeftFoot",
    "RightUpperLeg", "RightLowerLeg", "RightFoot"
}

skeletonCamera = workspace.CurrentCamera
screenSize = skeletonCamera and skeletonCamera.ViewportSize or Vector2.new(1920, 1080)
screenPadding = 100

skeletonRenderConnection = nil
skeletonPlayerRemovingConnection = nil

function isOnScreen(position)
    return position.X > -screenPadding and position.X < screenSize.X + screenPadding and
           position.Y > -screenPadding and position.Y < screenSize.Y + screenPadding
end

function getJoints(character)
    local joints = {}
    for _, partName in ipairs(partNames) do
        local part = character:FindFirstChild(partName)
        if part and part:IsA("BasePart") then
            joints[partName] = part
        end
    end
    return joints
end

function createSkeletonLine(color)
    local line = Drawing.new("Line")
    line.Color = color
    line.Thickness = 1.5
    line.Transparency = 1
    line.ZIndex = 5
    line.Visible = false
    return line
end

function hideSkeleton(player)
    local lines = skeletonLines[player]
    if not lines then return end
    for _, line in ipairs(lines) do
        line.Visible = false
    end
end

function cleanupSkeleton(player)
    local lines = skeletonLines[player]
    if not lines then return end
    skeletonLines[player] = nil
    for _, line in ipairs(lines) do
        pcall(function() line:Remove() end)
    end
end

function cleanupAllSkeletons()
    for player in pairs(skeletonLines) do
        cleanupSkeleton(player)
    end
    skeletonLines = {}

    for player, conn in pairs(skeletonConnections) do
        pcall(function() conn:Disconnect() end)
    end
    skeletonConnections = {}

    if skeletonRenderConnection then
        pcall(function() skeletonRenderConnection:Disconnect() end)
        skeletonRenderConnection = nil
    end

    if skeletonPlayerRemovingConnection then
        pcall(function() skeletonPlayerRemovingConnection:Disconnect() end)
        skeletonPlayerRemovingConnection = nil
    end
end

function updateSkeleton(player)
    if not Toggles.ESPShowSkeleton.Value then
        hideSkeleton(player)
        return
    end

    local character = player.Character
    if not character then
        hideSkeleton(player)
        return
    end

    local joints = getJoints(character)
    if not next(joints) then
        hideSkeleton(player)
        return
    end

    local camera = workspace.CurrentCamera
    if not camera then return end

    screenSize = camera.ViewportSize

    local rootPart = character:FindFirstChild("HumanoidRootPart")
    if rootPart then
        local rootPos, onScreen = camera:WorldToViewportPoint(rootPart.Position)
        if not onScreen or not isOnScreen(rootPos) then
            hideSkeleton(player)
            return
        end
    end

    local color = Options.SkeletonColor.Value

    local lines = skeletonLines[player]
    if not lines then
        lines = {}
        for i = 1, #bones do
            lines[i] = createSkeletonLine(color)
        end
        skeletonLines[player] = lines
    end

    for i, bone in ipairs(bones) do
        local part1 = joints[bone[1]]
        local part2 = joints[bone[2]]
        local line = lines[i]

        if part1 and part2 and line then
            local pos1, onScreen1 = camera:WorldToViewportPoint(part1.Position)
            local pos2, onScreen2 = camera:WorldToViewportPoint(part2.Position)

            if (onScreen1 or onScreen2) and (isOnScreen(pos1) or isOnScreen(pos2)) then
                line.From = Vector2.new(pos1.X, pos1.Y)
                line.To = Vector2.new(pos2.X, pos2.Y)
                line.Color = color
                line.Visible = true
            else
                line.Visible = false
            end
        elseif line then
            line.Visible = false
        end
    end
end

function skeletonRenderTick()
    if not Toggles.ESPShowSkeleton.Value then return end

    local camera = workspace.CurrentCamera
    if not camera then return end

    screenSize = camera.ViewportSize

    for _, player in ipairs(_51:GetPlayers()) do
        if player ~= _56 then
            local character = player.Character
            if character and character:FindFirstChild("HumanoidRootPart") then
                updateSkeleton(player)
            else
                hideSkeleton(player)
            end
        end
    end
end

function skeletonStart()
    if skeletonRenderConnection then return end

    cleanupAllSkeletons()

    for _, player in ipairs(_51:GetPlayers()) do
        if player ~= _56 then
            skeletonLines[player] = nil
        end
    end

    skeletonRenderConnection = _52.RenderStepped:Connect(skeletonRenderTick)

    skeletonPlayerRemovingConnection = _51.PlayerRemoving:Connect(function(player)
        cleanupSkeleton(player)
    end)

    skeletonRenderTick()
end

function skeletonStop()
    cleanupAllSkeletons()
end

Toggles.ESPShowSkeleton:OnChanged(function(value)
    if value then
        skeletonStart()
    else
        skeletonStop()
    end
end)

Options.SkeletonColor:OnChanged(function()
    local color = Options.SkeletonColor.Value
    for _, lines in pairs(skeletonLines) do
        for _, line in ipairs(lines) do
            line.Color = color
        end
    end
end)

-- < Box Core > --

Options.BoxESPColor:OnChanged(function()
    _G.box_esp_color = Options.BoxESPColor.Value
end)

Options.BoxESPBarType:OnChanged(function()
    _G.box_esp_bar_types = {}
    for barType, enabled in pairs(Options.BoxESPBarType.Value) do
        if enabled then
            _G.box_esp_bar_types[barType] = true
        end
    end
end)

function getArmorValue(character)
    local bodyEffects = character:FindFirstChild("BodyEffects")
    if bodyEffects then
        local armor = bodyEffects:FindFirstChild("Armor")
        if armor then
            return armor.Value or 0
        end
    end
    return 0
end

