    local cornerHolder = _mk("Frame", {
        Visible = false,
        BackgroundTransparency = 1,
        Position = UDim2.new(0, -1, 0, -1),
        Size = UDim2.new(0, 0, 0, 0),
        BorderSizePixel = 0,
    }, targetHolder)

    local cornerLines = {}
    for i = 1, 8 do
        local layout = _CORNER_LAYOUT[i]
        local line = _mk("Frame", {
            Visible = false,
            BackgroundTransparency = 0,
            BackgroundColor3 = Color3.fromRGB(255, 255, 255),
            Position = layout[1],
            Size = layout[2],
            AnchorPoint = layout[3],
            Rotation = layout[4],
            BorderSizePixel = 0,
        }, cornerHolder)
        _mk("UIStroke", { Thickness = 1, LineJoinMode = Enum.LineJoinMode.Miter }, line)
        local gradient = _mk("UIGradient", { Rotation = (i % 2 == 1) and 0 or 90 }, line)
        cornerLines[i] = { line = line, gradient = gradient }
    end

    local function _makeBar(c1, c2, c3)
        local outline = _mk("Frame", {
            ZIndex = 5,
            Visible = false,
            BackgroundTransparency = 0,
            Size = UDim2.new(1, 0, 0, 1),
            BorderSizePixel = 0,
            BackgroundColor3 = Color3.fromRGB(0, 0, 0),
        }, nil)
        _mk("UIStroke", { Thickness = 1, LineJoinMode = Enum.LineJoinMode.Miter }, outline)
        local bar = _mk("Frame", {
            ZIndex = 6,
            BackgroundTransparency = 0,
            Size = UDim2.new(1, 0, 0, 1),
            BorderSizePixel = 0,
            BackgroundColor3 = Color3.fromRGB(255, 255, 255),
        }, outline)
        local grad = _mk("UIGradient", {
            Rotation = 90,
            Color = ColorSequence.new {
                ColorSequenceKeypoint.new(0, c1),
                ColorSequenceKeypoint.new(0.5, c2),
                ColorSequenceKeypoint.new(1, c3),
            },
            Transparency = NumberSequence.new {
                NumberSequenceKeypoint.new(0, 0),
                NumberSequenceKeypoint.new(1, 0),
            },
        }, bar)
        return { outline = outline, bar = bar, gradient = grad }
    end

    local healthBar = _makeBar(Color3.fromRGB(131, 245, 78), Color3.fromRGB(255, 255, 0), Color3.fromRGB(252, 71, 77))
    local armorBar = _makeBar(Color3.fromRGB(52, 131, 235), Color3.fromRGB(52, 131, 235), Color3.fromRGB(52, 131, 235))

    return {
        screenGui = screenGui,
        targetHolder = targetHolder,
        topBarHolder = topBarHolder,
        bottomBarHolder = bottomBarHolder,
        leftBarHolder = leftBarHolder,
        rightBarHolder = rightBarHolder,
        boxOutlineHolder = boxOutlineHolder,
        boxOutline = boxOutline,
        boxOutlineGradient = boxOutlineGradient,
        boxInlineHolder = boxInlineHolder,
        boxInline = boxInline,
        boxInlineGradient = boxInlineGradient,
        boxFill = boxFill,
        boxFillGradient = boxFillGradient,
        cornerHolder = cornerHolder,
        cornerLines = cornerLines,
        healthBar = healthBar,
        armorBar = armorBar,

        lastUpdate = 0,
        cachedChar = nil,
        cachedChildCount = -1,
        cachedParts = {},
        lastFx = nil,
        lastFy = nil,
        lastFw = nil,
        lastFh = nil,
        lastHolders = { Top = false, Bottom = false, Left = false, Right = false },
        lastHP = nil,
        lastArmor = nil,
        lastHPBarPos = nil,
        lastArmorBarPos = nil,
        lastHPOn = nil,
        lastArmorOn = nil,
        styleKey = nil,
    }
end

function applyBoxStyle(boxData, boxType, c1, c2, gradientOn)
    local is2D = boxType == "2D"

    boxData.boxOutlineHolder.Visible = is2D
    boxData.boxInlineHolder.Visible = is2D
    boxData.boxFill.Visible = is2D and gradientOn
    boxData.cornerHolder.Visible = not is2D

    local seq = ColorSequence.new {
        ColorSequenceKeypoint.new(0, c1),
        ColorSequenceKeypoint.new(1, c2),
    }
    boxData.boxOutlineGradient.Color = seq
    boxData.boxInlineGradient.Color = seq
    boxData.boxFillGradient.Color = seq

    if is2D and gradientOn then
        boxData.boxFill.BackgroundTransparency = 0
        boxData.boxFillGradient.Transparency = NumberSequence.new {
            NumberSequenceKeypoint.new(0, 1),
            NumberSequenceKeypoint.new(1, 0.5),
        }
    else
        boxData.boxFill.BackgroundTransparency = 1
        boxData.boxFillGradient.Transparency = NumberSequence.new(1)
    end

    for i = 1, 8 do
        local entry = boxData.cornerLines[i]
        entry.line.Visible = not is2D
        entry.gradient.Color = seq
    end
end

function updateBoxESP(player, boxData)
    local now = os.clock()
    if now - boxData.lastUpdate < 0.016 then
        return
    end
    boxData.lastUpdate = now

    local character = player.Character
    if not character then
        if boxData.screenGui.Enabled then boxData.screenGui.Enabled = false end
        return
    end

    if boxData.cachedChar ~= character then
        boxData.cachedChar = character
        boxData.cachedChildCount = -1
        boxData.lastFx = nil
        boxData.lastFy = nil
        boxData.lastFw = nil
        boxData.lastFh = nil
        boxData.lastHP = nil
        boxData.lastArmor = nil
        boxData.cachedParts = {}
    end

    local humanoid = character:FindFirstChildOfClass("Humanoid")
    if not humanoid or humanoid.Health <= 0 then
        if boxData.screenGui.Enabled then boxData.screenGui.Enabled = false end
        return
    end

    local camera = workspace.CurrentCamera
    if not camera then return end

    local rootPart = character:FindFirstChild("HumanoidRootPart")
    if not rootPart then
        if boxData.screenGui.Enabled then boxData.screenGui.Enabled = false end
        return
    end

    local rpPos = camera:WorldToViewportPoint(rootPart.Position)
    if rpPos.Z <= 0 then
        if boxData.screenGui.Enabled then boxData.screenGui.Enabled = false end
        return
    end

    local vp = camera.ViewportSize
    if rpPos.X < -200 or rpPos.Y < -200 or rpPos.X > vp.X + 200 or rpPos.Y > vp.Y + 200 then
        if boxData.screenGui.Enabled then boxData.screenGui.Enabled = false end
        return
    end

    local children = character:GetChildren()
    local childCount = #children
    if boxData.cachedChildCount ~= childCount then
        boxData.cachedChildCount = childCount
        local parts = {}
        for i = 1, childCount do
            local p = children[i]
            if p:IsA("BasePart") and p.Name ~= "HumanoidRootPart" and p.Transparency ~= 1 then
                parts[#parts + 1] = p
            end
        end
        boxData.cachedParts = parts
    end

    local minX, minY, maxX, maxY = math.huge, math.huge, -math.huge, -math.huge
    local parts = boxData.cachedParts
    for i = 1, #parts do
        local part = parts[i]
        local cf = part.CFrame
        local sz = part.Size
        local hx, hy, hz = sz.X * 0.5, sz.Y * 0.5, sz.Z * 0.5
        local corners = {
            cf * Vector3.new(hx, hy, hz),
            cf * Vector3.new(-hx, hy, hz),
            cf * Vector3.new(hx, -hy, hz),
            cf * Vector3.new(-hx, -hy, hz),
            cf * Vector3.new(hx, hy, -hz),
            cf * Vector3.new(-hx, hy, -hz),
            cf * Vector3.new(hx, -hy, -hz),
            cf * Vector3.new(-hx, -hy, -hz),
        }
        for j = 1, 8 do
            local sp = camera:WorldToViewportPoint(corners[j])
            if sp.X < minX then minX = sp.X end
            if sp.Y < minY then minY = sp.Y end
            if sp.X > maxX then maxX = sp.X end
            if sp.Y > maxY then maxY = sp.Y end
        end
    end

    if minX == math.huge then
        if boxData.screenGui.Enabled then boxData.screenGui.Enabled = false end
        return
    end

    local boxW = maxX - minX
    local boxH = maxY - minY

    if maxX < 0 or maxY < 0 or minX > vp.X or minY > vp.Y then
        if boxData.screenGui.Enabled then boxData.screenGui.Enabled = false end
        return
    end

    if not boxData.screenGui.Enabled then boxData.screenGui.Enabled = true end
    boxData.targetHolder.Visible = true

    local fx = math.floor(minX)
    local fy = math.floor(minY)
    if boxData.lastFx ~= fx or boxData.lastFy ~= fy then
        boxData.lastFx = fx
        boxData.lastFy = fy
        boxData.targetHolder.Position = UDim2.fromOffset(fx, fy)
    end

    local fw = math.floor(boxW)
    local fh = math.floor(boxH)
    if boxData.lastFw ~= fw or boxData.lastFh ~= fh then
        boxData.lastFw = fw
        boxData.lastFh = fh
        boxData.targetHolder.Size = UDim2.fromOffset(fw, fh)
    end

    boxData.boxOutlineHolder.Size = UDim2.fromOffset(boxW, boxH)
    boxData.boxInlineHolder.Size = UDim2.fromOffset(boxW + 2, boxH + 2)
    boxData.boxFill.Size = UDim2.fromOffset(boxW, boxH)
    boxData.cornerHolder.Size = UDim2.fromOffset(boxW + 2, boxH + 2)

    local boxType = (Options.BoxESPType and Options.BoxESPType.Value) or "2D"
    if type(boxType) == "table" then boxType = boxType[1] end

    local c1 = _G.box_esp_color or Color3.fromRGB(255, 255, 255)
    local gradientOn = (Toggles.BoxESPGradient and Toggles.BoxESPGradient.Value) or false
    local c2 = c1
    if gradientOn and Options.BoxESPColor2 then
        c2 = Options.BoxESPColor2.Value
    end

    local styleKey = boxType .. "|" .. tostring(c1) .. "|" .. tostring(c2) .. "|" .. tostring(gradientOn)
    if boxData.styleKey ~= styleKey then
        boxData.styleKey = styleKey
        applyBoxStyle(boxData, boxType, c1, c2, gradientOn)
    end

    local healthOn = _G.box_esp_bar_types["Health"] == true
    local armorOn = _G.box_esp_bar_types["Armor"] == true
    local healthPos = (Options.BoxESPHealthPosition and Options.BoxESPHealthPosition.Value) or "Left"
    if type(healthPos) == "table" then healthPos = healthPos[1] end
    local armorPos = (Options.BoxESPArmorPosition and Options.BoxESPArmorPosition.Value) or "Left"
    if type(armorPos) == "table" then armorPos = armorPos[1] end

    local wantTop = (healthOn and healthPos == "Top") or (armorOn and armorPos == "Top")
    local wantBottom = (healthOn and healthPos == "Bottom") or (armorOn and armorPos == "Bottom")
    local wantLeft = (healthOn and healthPos == "Left") or (armorOn and armorPos == "Left")
    local wantRight = (healthOn and healthPos == "Right") or (armorOn and armorPos == "Right")
    local hold = boxData.lastHolders
    if hold.Top ~= wantTop or hold.Bottom ~= wantBottom or hold.Left ~= wantLeft or hold.Right ~= wantRight then
        hold.Top = wantTop
        hold.Bottom = wantBottom
        hold.Left = wantLeft
        hold.Right = wantRight
        boxData.topBarHolder.Visible = wantTop
        boxData.bottomBarHolder.Visible = wantBottom
        boxData.leftBarHolder.Visible = wantLeft
        boxData.rightBarHolder.Visible = wantRight
    end

    if healthOn then
        local hpPct = humanoid.Health / math.max(1, humanoid.MaxHealth)
        if boxData.lastHP ~= humanoid.Health or boxData.lastHPBarPos ~= healthPos or boxData.lastHPOn ~= true then
            boxData.lastHP = humanoid.Health
            boxData.lastHPBarPos = healthPos
            boxData.lastHPOn = true
            boxData.healthBar.outline.Parent = boxData[healthPos:lower() .. "BarHolder"]
            boxData.healthBar.outline.Size = _BAR_OUTLINE[healthPos]
            boxData.healthBar.bar.AnchorPoint = _BAR_POS[healthPos][1]
            boxData.healthBar.bar.Position = _BAR_POS[healthPos][2]
            boxData.healthBar.bar.Size = _BAR_SIZE[healthPos](hpPct)
            local rot, offset = _BAR_GRAD[healthPos](hpPct)
            boxData.healthBar.gradient.Rotation = rot
            boxData.healthBar.gradient.Offset = offset
            boxData.healthBar.outline.Visible = true
        end
    elseif boxData.lastHPOn ~= false then
        boxData.lastHPOn = false
        boxData.healthBar.outline.Visible = false
    end

    if armorOn then
        local armor = getArmorValue(character)
        local armorPct = math.clamp(armor / 200, 0, 1)
        if boxData.lastArmor ~= armor or boxData.lastArmorBarPos ~= armorPos or boxData.lastArmorOn ~= true then
            boxData.lastArmor = armor
            boxData.lastArmorBarPos = armorPos
            boxData.lastArmorOn = true
            boxData.armorBar.outline.Parent = boxData[armorPos:lower() .. "BarHolder"]
            boxData.armorBar.outline.Size = _BAR_OUTLINE[armorPos]
            boxData.armorBar.bar.AnchorPoint = _BAR_POS[armorPos][1]
            boxData.armorBar.bar.Position = _BAR_POS[armorPos][2]
            boxData.armorBar.bar.Size = _BAR_SIZE[armorPos](armorPct)
            local rot, offset = _BAR_GRAD[armorPos](armorPct)
            boxData.armorBar.gradient.Rotation = rot
            boxData.armorBar.gradient.Offset = offset
            boxData.armorBar.outline.Visible = true
        end
    elseif boxData.lastArmorOn ~= false then
        boxData.lastArmorOn = false
        boxData.armorBar.outline.Visible = false
    end
end

Toggles.BoxESPEnabled:OnChanged(function(value)
    if _G.box_esp_connection then
        _G.box_esp_connection:Disconnect()
        _G.box_esp_connection = nil
    end

    for _, boxData in pairs(_G.box_esp_boxes) do
        if boxData.screenGui then
            pcall(function() boxData.screenGui:Destroy() end)
        end
    end
    _G.box_esp_boxes = {}

    if value then
        for _, player in ipairs(Players:GetPlayers()) do
            if player ~= LocalPlayer and not _G.box_esp_boxes[player] then
                _G.box_esp_boxes[player] = createBoxESP(player)
            end
        end

        _G.box_esp_connection = game:GetService("RunService").RenderStepped:Connect(function()
            for player, boxData in pairs(_G.box_esp_boxes) do
                if player and player.Parent then
                    pcall(updateBoxESP, player, boxData)
                else
                    if boxData and boxData.screenGui then
                        pcall(function() boxData.screenGui:Destroy() end)
                    end
                    _G.box_esp_boxes[player] = nil
                end
            end
        end)
    end
end)

