            end
        end
    end
    connections.FriendStatusMonitor = _51.PlayerAdded:Connect(onPlayerAdded)
end

local ESP = {
    labels = {},
    cache = {},
    lastUpdate = 0,
    interval = 0.01
}

function createLabel(player)
    if not ESPGui then
        ESPGui = Instance.new("ScreenGui")
        ESPGui.Name = "ESPGui"
        ESPGui.ResetOnSpawn = false
        ESPGui.ZIndexBehavior = Enum.ZIndexBehavior.Global
        ESPGui.Parent = game:GetService("CoreGui")
    end

    local label = Instance.new("TextLabel")
    label.BackgroundTransparency = 1
    label.TextColor3 = Color3.fromRGB(255, 255, 255)
    label.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
    label.TextStrokeTransparency = 0
    label.TextSize = 13
    label.Font = Enum.Font.GothamBold
    label.AnchorPoint = Vector2.new(0.5, 0.5)
    label.BorderSizePixel = 0
    label.TextXAlignment = Enum.TextXAlignment.Center
    label.TextYAlignment = Enum.TextYAlignment.Center
    label.RichText = true
    label.Visible = false
    label.ZIndex = 10
    label.Parent = ESPGui
    ESP.labels[player] = label
    return label
end

function removeLabel(player)
    if ESP.labels[player] then
        ESP.labels[player]:Destroy()
        ESP.labels[player] = nil
    end
    ESP.cache[player] = nil
end

function getHeadPos(head)
    if not head then return end
    local pos, onScreen = Camera:WorldToScreenPoint(head.Position + Vector3.new(0, head.Size.Y/2, 0))
    if onScreen and pos.Z > 0 then
        local dist = (Camera.CFrame.Position - head.Position).Magnitude
        local yOffset = 22
        if dist > 150 then yOffset = 12 end
        return Vector2.new(pos.X, pos.Y - yOffset), dist, true
    end
end
function colorToHex(c)
    return string.format("#%02X%02X%02X",
        math.floor(c.R * 255 + 0.5),
        math.floor(c.G * 255 + 0.5),
        math.floor(c.B * 255 + 0.5))
end

function getESPNameColor()
    return (Options.ESPNameColor and Options.ESPNameColor.Value) or Color3.fromRGB(255, 255, 255)
end

function buildText(player)
    local parts = {}
    local nameColor = getESPNameColor()
    local distColor = (Options.ESPDistanceColor and Options.ESPDistanceColor.Value) or Color3.fromRGB(200, 200, 200)
    local hpColor = (Options.ESPHealthColor and Options.ESPHealthColor.Value) or Color3.fromRGB(200, 200, 200)

    if Toggles.ESPShowNames and Toggles.ESPShowNames.Value then
        table.insert(parts, string.format('<font color="%s">%s</font>', colorToHex(nameColor), player.DisplayName))
    end
    if Toggles.ESPShowDistance and Toggles.ESPShowDistance.Value then
        local char = player.Character
        local head = char and char:FindFirstChild("Head")
        if head then
            local dist = math.floor((Camera.CFrame.Position - head.Position).Magnitude)
            table.insert(parts, string.format('<font color="%s">[%dm]</font>', colorToHex(distColor), dist))
        end
    end
    if Toggles.ESPShowHealth and Toggles.ESPShowHealth.Value then
        local char = player.Character
        local hum = char and char:FindFirstChild("Humanoid")
        if hum then
            table.insert(parts, string.format('<font color="%s">%d HP</font>', colorToHex(hpColor), math.floor(hum.Health)))
        end
    end
    return #parts > 0 and table.concat(parts, " ") or ""
end

function updateLabel(player)
    local label = ESP.labels[player]
    if not label then return end

    local char = player.Character
    if not char or not char.Parent then
        label.Visible = false
        return
    end

    local hum = char:FindFirstChild("Humanoid")
    if not hum or hum.Health <= 0 then
        label.Visible = false
        return
    end

    local head = char:FindFirstChild("Head")
    if not head then
        label.Visible = false
        return
    end

    local text = buildText(player)
    if text == "" then
        label.Visible = false
        return
    end

    local pos, dist, onScreen = getHeadPos(head)
    if not onScreen then
        label.Visible = false
        return
    end

    if label.Text ~= text then
        label.Text = text
    end

    local posX, posY = math.round(pos.X), math.round(pos.Y)
    if label.Position.X.Offset ~= posX or label.Position.Y.Offset ~= posY then
        label.Position = UDim2.new(0, posX, 0, posY)
    end

    local size = 13
    if dist > 150 then
        size = math.clamp(13 - ((dist - 150) / 200), 8, 13)
    end
    if label.TextSize ~= size then
        label.TextSize = size
    end

    ESP.cache[player] = char
    label.Visible = true
end

function updateAllLabels()
    if not Toggles.ESPEnabled or not Toggles.ESPEnabled.Value then
        for _, label in pairs(ESP.labels) do
            if label then label.Visible = false end
        end
        return
    end
    
    local now = tick()
    if now - ESP.lastUpdate < ESP.interval then return end
    ESP.lastUpdate = now
    
    for player in pairs(ESP.labels) do
        if player and player.Parent then
            updateLabel(player)
        else
            removeLabel(player)
        end
    end
end
function setupESP()
    ESP.conns = ESP.conns or {}
    ESP.charConns = ESP.charConns or {}

    local function trackChar(player)
        local old = ESP.charConns[player]
        if old then
            for _, c in ipairs(old) do pcall(function() c:Disconnect() end) end
        end
        ESP.charConns[player] = {
            player.CharacterAdded:Connect(function()
                ESP.cache[player] = nil
                updateLabel(player)
            end)
        }
    end

    local function untrackChar(player)
        local conns = ESP.charConns[player]
        if conns then
            for _, c in ipairs(conns) do pcall(function() c:Disconnect() end) end
            ESP.charConns[player] = nil
        end
    end

    for _, player in ipairs(_51:GetPlayers()) do
        if player ~= _56 then
            createLabel(player)
            trackChar(player)
        end
    end

    ESP.conns.playerAdded = _51.PlayerAdded:Connect(function(player)
        if player ~= _56 then
            createLabel(player)
            trackChar(player)
            task.wait(0.1)
            if shared.FriendsCache and shared.FriendsCache[player.UserId] then
                updateLabel(player)
            end
        end
    end)

    ESP.conns.playerRemoving = _51.PlayerRemoving:Connect(function(player)
        removeLabel(player)
        untrackChar(player)
    end)

    ESP.conns.localCharAdded = _56.CharacterAdded:Connect(function()
        for player in pairs(ESP.labels) do
            ESP.cache[player] = nil
        end
    end)

    ESP.conns.render = _52.RenderStepped:Connect(updateAllLabels)
    ESP.conns.camChanged = _53:GetPropertyChangedSignal("CurrentCamera"):Connect(function()
        Camera = _53.CurrentCamera
    end)
end

Toggles.ESPEnabled:OnChanged(function(v)
    if not v then
        for _, label in pairs(ESP.labels) do
            if label then label.Visible = false end
        end
    end
end)

Toggles.ESPShowNames:OnChanged(updateAllLabels)
Toggles.ESPShowDistance:OnChanged(updateAllLabels)
Toggles.ESPShowHealth:OnChanged(updateAllLabels)

setupESP()

